INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('scss','scss',8,'css-intermediate','published','{"title":{"it":"SCSS","en":"SCSS"},"short":{"it":"SCSS","en":"SCSS"},"desc":{"it":"CSS con i superpoteri: variabili, annidamento, mixin, moduli e cicli.","en":"CSS with superpowers: variables, nesting, mixins, modules and loops."},"level":{"it":"Preprocessori","en":"Preprocessors"}}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('sass','sass',9,'scss','published','{"title":{"it":"Sass (sintassi indentata)","en":"Sass (indented syntax)"},"short":{"it":"Sass","en":"Sass"},"desc":{"it":"La sintassi originale di Sass: niente graffe né punti e virgola, conta il rientro.","en":"The original Sass syntax: no braces or semicolons, indentation is what counts."},"level":{"it":"Preprocessori","en":"Preprocessors"}}');
