INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('js-intermediate','js',11,'js-base','published','{"title":{"it":"JavaScript intermedio","en":"Intermediate JavaScript"},"short":{"it":"JS intermedio","en":"JS Intermediate"},"desc":{"it":"Fai reagire le pagine: DOM, eventi, metodi degli array, sintassi moderna, JSON e salvataggio dati.","en":"Make pages react: DOM, events, array methods, modern syntax, JSON and saving data."},"level":{"it":"Intermedio","en":"Intermediate"}}');
