INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('php-base','php',14,'html-base','published','{"title":{"it":"PHP base","en":"PHP Basics"},"short":{"it":"PHP base","en":"PHP Basics"},"desc":{"it":"Il lato server del web: variabili, condizioni, array, funzioni, moduli e sicurezza di base.","en":"The server side of the web: variables, conditions, arrays, functions, forms and basic security."},"level":{"it":"Base","en":"Basic"}}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('php-advanced','php',15,'php-base','published','{"title":{"it":"PHP avanzato","en":"Advanced PHP"},"short":{"it":"PHP avanzato","en":"PHP Advanced"},"desc":{"it":"Classi, database con PDO, password sicure, API JSON, errori e progetti ordinati.","en":"Classes, databases with PDO, safe passwords, JSON APIs, errors and tidy projects."},"level":{"it":"Avanzato","en":"Advanced"}}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','structure',1,1,'published','{"it":"La struttura di una pagina","en":"The structure of a page"}','[{"t":"p","text":{"it":"HTML descrive il **contenuto** di una pagina usando i `tag`: parole tra parentesi angolari. Quasi tutti si aprono e si chiudono, e quello che sta in mezzo è il contenuto dell’elemento.","en":"HTML describes the **content** of a page using `tags`: words between angle brackets. Most of them open and close, and what sits in between is the content of the element."}},{"t":"code","code":"<!doctype html>\\n<html lang=\\"it\\">\\n  <head>\\n    <meta charset=\\"utf-8\\">\\n    <title>La mia pagina</title>\\n  </head>\\n  <body>\\n    <h1>Ciao mondo</h1>\\n  </body>\\n</html>","lang":"html"},{"t":"p","text":{"it":"`<!doctype html>` dice al browser che è una pagina moderna. Dentro `<head>` vanno le informazioni sulla pagina, che non si vedono nella pagina stessa. Dentro `<body>` va tutto ciò che si vede.","en":"`<!doctype html>` tells the browser this is a modern page. `<head>` holds information about the page, which is not shown on the page itself. `<body>` holds everything that is visible."}},{"t":"tip","text":{"it":"Il contenuto di `<title>` è il testo che compare nella scheda del browser.","en":"The content of `<title>` is the text shown on the browser tab."}}]','{"lang":"html","prompt":{"it":"Scrivi nel `body` un titolo `h1` con il testo **Ciao mondo**.","en":"Write an `h1` heading in the `body` with the text **Ciao mondo**."},"start":"<!doctype html>\\n<html lang=\\"it\\">\\n  <head>\\n    <title>Prima pagina</title>\\n  </head>\\n  <body>\\n\\n  </body>\\n</html>","html":"","checks":[{"sel":"h1","text":"","label":{"it":"C’è un titolo `h1`","en":"There is an `h1` heading"}},{"sel":"h1","text":"Ciao mondo","label":{"it":"Il titolo dice «Ciao mondo»","en":"The heading says “Ciao mondo”"}}],"hint":"<h1>Ciao mondo</h1>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','text',2,1,'published','{"it":"Titoli e paragrafi","en":"Headings and paragraphs"}','[{"t":"p","text":{"it":"I titoli vanno da `<h1>` a `<h6>`: `<h1>` è il più importante e di solito ce n’è uno per pagina. I paragrafi si scrivono con `<p>`.","en":"Headings go from `<h1>` to `<h6>`: `<h1>` is the most important and there is usually one per page. Paragraphs use `<p>`."}},{"t":"code","code":"<h1>Ricette</h1>\\n<h2>Primi piatti</h2>\\n<p>La pasta si cuoce in acqua <strong>salata</strong>.</p>\\n<p>Il sugo va <em>assaggiato</em> spesso.</p>","lang":"html"},{"t":"p","text":{"it":"`<strong>` indica un testo importante e `<em>` un’enfasi: comunicano un significato, non solo un aspetto. `<br>` va a capo e non ha tag di chiusura.","en":"`<strong>` marks important text and `<em>` emphasis: they carry meaning, not just looks. `<br>` is a line break and has no closing tag."}},{"t":"tip","text":{"it":"Scegli il titolo per la sua importanza, non per la sua grandezza: all’aspetto ci penserà il CSS.","en":"Choose a heading for its importance, not its size: CSS will take care of the look."}}]','{"lang":"html","prompt":{"it":"Aggiungi un titolo `h2` e un paragrafo `p` che contenga una parola in `strong`.","en":"Add an `h2` heading and a `p` paragraph containing a word in `strong`."},"start":"<h1>Il mio blog</h1>","html":"","checks":[{"sel":"h2","text":"","label":{"it":"C’è un titolo `h2`","en":"There is an `h2` heading"}},{"sel":"p","text":"","label":{"it":"C’è un paragrafo","en":"There is a paragraph"}},{"sel":"p strong","text":"","label":{"it":"Il paragrafo contiene `strong`","en":"The paragraph contains `strong`"}}],"hint":"<h2>Le novità</h2>\\n<p>Un testo <strong>importante</strong>.</p>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','links',3,1,'published','{"it":"Link e immagini","en":"Links and images"}','[{"t":"p","text":{"it":"Gli **attributi** aggiungono informazioni a un tag e si scrivono nel tag di apertura, come `nome=\\"valore\\"`. Un link è un tag `<a>` con l’attributo `href`.","en":"**Attributes** add information to a tag and go in the opening tag, as `name=\\"value\\"`. A link is an `<a>` tag with the `href` attribute."}},{"t":"code","code":"<a href=\\"https://example.com\\">Vai al sito</a>\\n<a href=\\"contatti.html\\">Contatti</a>\\n<img src=\\"gatto.jpg\\" alt=\\"Un gatto rosso che dorme\\">","lang":"html"},{"t":"p","text":{"it":"`<img>` mostra un’immagine: `src` dice dove si trova il file, `alt` la descrive a chi non può vederla. Anche `<img>` non ha tag di chiusura.","en":"`<img>` shows an image: `src` says where the file is, `alt` describes it to whoever cannot see it. `<img>` has no closing tag either."}},{"t":"tip","text":{"it":"Un `alt` utile descrive ciò che l’immagine comunica. Se è solo decorativa, scrivi `alt=\\"\\"`.","en":"A useful `alt` describes what the image conveys. If it is only decorative, write `alt=\\"\\"`."}}]','{"lang":"html","prompt":{"it":"Crea un link a `https://example.com` con il testo **Scopri** e un’immagine `logo.png` con un `alt`.","en":"Create a link to `https://example.com` with the text **Scopri** and a `logo.png` image with an `alt`."},"start":"","html":"","checks":[{"sel":"a[href=\\"https://example.com\\"]","text":"","label":{"it":"Il link punta a example.com","en":"The link points to example.com"}},{"sel":"a","text":"Scopri","label":{"it":"Il testo del link è «Scopri»","en":"The link text is “Scopri”"}},{"sel":"img[src=\\"logo.png\\"]","text":"","label":{"it":"C’è l’immagine `logo.png`","en":"There is the `logo.png` image"}},{"sel":"img[alt]:not([alt=\\"\\"])","text":"","label":{"it":"L’immagine ha un `alt`","en":"The image has an `alt`"}}],"hint":"<a href=\\"https://example.com\\">Scopri</a>\\n<img src=\\"logo.png\\" alt=\\"Logo\\">"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','lists',4,1,'published','{"it":"Le liste","en":"Lists"}','[{"t":"p","text":{"it":"`<ul>` crea una lista puntata, `<ol>` una numerata. Ogni voce è un `<li>`, in entrambi i casi.","en":"`<ul>` creates a bulleted list, `<ol>` a numbered one. Each item is an `<li>`, in both cases."}},{"t":"code","code":"<ul>\\n  <li>Pane</li>\\n  <li>Latte</li>\\n</ul>\\n\\n<ol>\\n  <li>Accendi il forno</li>\\n  <li>Inforna</li>\\n</ol>","lang":"html"},{"t":"p","text":{"it":"Una lista può stare dentro un’altra: la lista interna va **dentro** un `<li>`. Usa `<ol>` quando l’ordine conta.","en":"A list can sit inside another: the inner list goes **inside** an `<li>`. Use `<ol>` when the order matters."}}]','{"lang":"html","prompt":{"it":"Crea una lista numerata con tre passaggi.","en":"Create a numbered list with three steps."},"start":"","html":"","checks":[{"sel":"ol","text":"","label":{"it":"C’è una lista numerata","en":"There is a numbered list"}},{"sel":"ol > li:nth-child(3)","text":"","label":{"it":"Ha almeno tre voci","en":"It has at least three items"}}],"hint":"<ol>\\n  <li>Uno</li>\\n  <li>Due</li>\\n  <li>Tre</li>\\n</ol>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','tables',5,2,'published','{"it":"Le tabelle","en":"Tables"}','[{"t":"p","text":{"it":"Le tabelle servono a mostrare **dati**, non a impaginare. `<table>` contiene righe `<tr>`, che contengono celle: `<th>` per le intestazioni e `<td>` per i dati.","en":"Tables are for showing **data**, not for page layout. `<table>` contains `<tr>` rows, which contain cells: `<th>` for headers and `<td>` for data."}},{"t":"code","code":"<table>\\n  <thead>\\n    <tr><th>Città</th><th>Abitanti</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr><td>Udine</td><td>97 000</td></tr>\\n  </tbody>\\n</table>","lang":"html"},{"t":"p","text":{"it":"`<thead>` e `<tbody>` separano intestazione e dati. `colspan=\\"2\\"` fa occupare a una cella due colonne, `rowspan=\\"2\\"` due righe.","en":"`<thead>` and `<tbody>` separate header and data. `colspan=\\"2\\"` makes a cell span two columns, `rowspan=\\"2\\"` two rows."}}]','{"lang":"html","prompt":{"it":"Crea una tabella con una riga di intestazione (`th`) e una riga di dati (`td`).","en":"Create a table with a header row (`th`) and a data row (`td`)."},"start":"<table>\\n\\n</table>","html":"","checks":[{"sel":"table tr th","text":"","label":{"it":"C’è una cella `th`","en":"There is a `th` cell"}},{"sel":"table tr td","text":"","label":{"it":"C’è una cella `td`","en":"There is a `td` cell"}},{"sel":"table tr:nth-of-type(1)","text":"","label":{"it":"Le celle stanno in una riga `tr`","en":"The cells sit in a `tr` row"}}],"hint":"<tr><th>Nome</th></tr>\\n<tr><td>Sav</td></tr>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','forms',6,2,'published','{"it":"I primi moduli","en":"First forms"}','[{"t":"p","text":{"it":"`<form>` raccoglie i dati dell’utente. Ogni campo `<input>` ha un `type` e un `name`, il nome con cui il dato viene inviato.","en":"`<form>` collects data from the user. Each `<input>` field has a `type` and a `name`, the name the data is sent with."}},{"t":"code","code":"<form action=\\"/iscriviti\\" method=\\"post\\">\\n  <label for=\\"mail\\">Email</label>\\n  <input id=\\"mail\\" name=\\"mail\\" type=\\"email\\" required>\\n  <button type=\\"submit\\">Iscriviti</button>\\n</form>","lang":"html"},{"t":"p","text":{"it":"`<label>` è collegata al campo tramite `for` e `id`: toccando l’etichetta si attiva il campo. `required` rende il campo obbligatorio e `type=\\"email\\"` fa controllare al browser il formato.","en":"`<label>` is tied to the field through `for` and `id`: tapping the label activates the field. `required` makes the field mandatory and `type=\\"email\\"` has the browser check the format."}},{"t":"tip","text":{"it":"Ogni campo deve avere una `label`: un segnaposto `placeholder` non basta, perché sparisce quando si scrive.","en":"Every field needs a `label`: a `placeholder` is not enough, because it disappears while typing."}}]','{"lang":"html","prompt":{"it":"Completa il modulo: un campo `email` obbligatorio con la sua `label` e un pulsante di invio.","en":"Complete the form: a required `email` field with its `label` and a submit button."},"start":"<form>\\n\\n</form>","html":"","checks":[{"sel":"form input[type=\\"email\\"]","text":"","label":{"it":"C’è un campo email","en":"There is an email field"}},{"sel":"form input[required]","text":"","label":{"it":"Il campo è obbligatorio","en":"The field is required"}},{"sel":"form label[for]","text":"","label":{"it":"C’è una `label` con `for`","en":"There is a `label` with `for`"}},{"sel":"form button, form input[type=\\"submit\\"]","text":"","label":{"it":"C’è un pulsante","en":"There is a button"}}],"hint":"<label for=\\"m\\">Email</label>\\n<input id=\\"m\\" type=\\"email\\" required>\\n<button>Invia</button>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','entities',7,2,'published','{"it":"Caratteri speciali e commenti","en":"Special characters and comments"}','[{"t":"p","text":{"it":"Alcuni caratteri hanno un significato per l’HTML: per mostrare `<` si scrive un’**entità**, come `&lt;`. Le entità iniziano con `&` e finiscono con `;`.","en":"Some characters mean something to HTML: to show `<` you write an **entity**, like `&lt;`. Entities start with `&` and end with `;`."}},{"t":"code","code":"<p>2 &lt; 3 &amp; 3 &gt; 2</p>\\n<p>Fucina &copy; 2026</p>\\n<!-- Questo non si vede nella pagina -->","lang":"html"},{"t":"p","text":{"it":"I commenti `<!-- … -->` sono note per chi legge il codice: il browser li ignora, ma chiunque può leggerli aprendo il sorgente.","en":"Comments `<!-- … -->` are notes for those reading the code: the browser ignores them, but anyone can read them in the source."}}]','{"lang":"html","prompt":{"it":"Scrivi un paragrafo che contenga l’entità `&copy;`.","en":"Write a paragraph containing the `&copy;` entity."},"start":"<!-- scrivi qui sotto -->","html":"","checks":[{"sel":"p","text":"","label":{"it":"C’è un paragrafo","en":"There is a paragraph"}},{"re":"&copy;","label":{"it":"Usi l’entità `&copy;`","en":"You use the `&copy;` entity"}}],"hint":"<p>Fucina &copy; 2026</p>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','page-project',8,2,'published','{"it":"Progetto: la tua prima pagina","en":"Project: your first page"}','[{"t":"p","text":{"it":"Ora metti tutto insieme: una pagina con titolo, testo, immagine, lista e link. Ogni pezzo lo conosci già: la bravura sta nell’**ordine**.","en":"Now put it all together: a page with a heading, text, an image, a list and a link. You already know every piece: the skill is in the **order**."}},{"t":"code","code":"<h1>Ciao, sono Sav</h1>\\n<img src=\\"me.jpg\\" alt=\\"La mia foto\\">\\n<p>Imparo a costruire siti.</p>\\n<ul>\\n  <li>HTML</li>\\n  <li>CSS</li>\\n</ul>\\n<a href=\\"contatti.html\\">Scrivimi</a>","lang":"html"},{"t":"tip","text":{"it":"Scrivi prima il contenuto, poi pensa allo stile: una pagina ben strutturata è già mezza fatta.","en":"Write the content first, then think about style: a well-structured page is already half done."}}]','{"lang":"html","prompt":{"it":"Crea una pagina con un `h1`, un `p`, una lista `ul` con almeno un `li` e un link `a`.","en":"Create a page with an `h1`, a `p`, a `ul` list with at least one `li` and an `a` link."},"start":"","html":"","checks":[{"sel":"h1","text":"","label":{"it":"C’è un titolo","en":"There is a heading"}},{"sel":"p","text":"","label":{"it":"C’è un paragrafo","en":"There is a paragraph"}},{"sel":"ul li","text":"","label":{"it":"C’è una lista","en":"There is a list"}},{"sel":"a","text":"","label":{"it":"C’è un link","en":"There is a link"}}],"hint":"<h1>Ciao</h1>\\n<p>Testo</p>\\n<ul><li>Uno</li></ul>\\n<a href=\\"#\\">Link</a>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-intermediate','attributes',1,1,'published','{"it":"Attributi globali","en":"Global attributes"}','[{"t":"p","text":{"it":"Alcuni attributi valgono su quasi tutti i tag: `id` identifica un elemento, `class` lo raggruppa, `title` aggiunge un suggerimento, `hidden` lo nasconde, `lang` ne indica la lingua.","en":"Some attributes work on almost every tag: `id` identifies an element, `class` groups it, `title` adds a tooltip, `hidden` hides it, `lang` states its language."}},{"t":"code","code":"<p id=\\"intro\\" class=\\"nota grande\\" lang=\\"en\\" title=\\"Una nota\\">Hello!</p>\\n<div hidden>Non mi vedi</div>","lang":"html"},{"t":"p","text":{"it":"Un elemento può avere più classi separate da spazi, ma un solo `id`, unico in tutta la pagina.","en":"An element can have several classes separated by spaces, but only one `id`, unique in the whole page."}}]','{"lang":"html","prompt":{"it":"Crea un paragrafo con `id=\\"intro\\"` e le classi `nota` e `grande`.","en":"Create a paragraph with `id=\\"intro\\"` and the classes `nota` and `grande`."},"start":"","html":"","checks":[{"sel":"p#intro","text":"","label":{"it":"Il paragrafo ha l’id","en":"The paragraph has the id"}},{"sel":"p.nota.grande","text":"","label":{"it":"Ha entrambe le classi","en":"It has both classes"}}],"hint":"<p id=\\"intro\\" class=\\"nota grande\\">Ciao</p>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-intermediate','anchors',2,1,'published','{"it":"Link interni e percorsi","en":"Internal links and paths"}','[{"t":"p","text":{"it":"Un link può portare a un punto della stessa pagina: `href=\\"#contatti\\"` salta all’elemento con `id=\\"contatti\\"`. I percorsi **relativi** partono dalla pagina attuale, quelli **assoluti** includono tutto l’indirizzo.","en":"A link can lead to a spot in the same page: `href=\\"#contatti\\"` jumps to the element with `id=\\"contatti\\"`. **Relative** paths start from the current page, **absolute** ones include the whole address."}},{"t":"code","code":"<a href=\\"#contatti\\">Vai ai contatti</a>\\n<a href=\\"chi-siamo.html\\">Stessa cartella</a>\\n<a href=\\"../index.html\\">Cartella sopra</a>\\n<a href=\\"https://esempio.it/\\">Altro sito</a>\\n<a href=\\"mailto:ciao@esempio.it\\">Scrivimi</a>","lang":"html"},{"t":"p","text":{"it":"`mailto:` apre l’email e `tel:` il telefono. `../` sale di una cartella.","en":"`mailto:` opens email and `tel:` the phone. `../` goes up one folder."}}]','{"lang":"html","prompt":{"it":"Crea un link che salta a `#fine` e un `div` con `id=\\"fine\\"`.","en":"Create a link that jumps to `#fine` and a `div` with `id=\\"fine\\"`."},"start":"","html":"","checks":[{"sel":"a[href=\\"#fine\\"]","text":"","label":{"it":"Il link punta a #fine","en":"The link points to #fine"}},{"sel":"div#fine","text":"","label":{"it":"Il `div` ha l’id","en":"The `div` has the id"}}],"hint":"<a href=\\"#fine\\">Vai</a>\\n<div id=\\"fine\\">Fine</div>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-intermediate','rich-text',3,1,'published','{"it":"Testo ricco","en":"Rich text"}','[{"t":"p","text":{"it":"Oltre a `strong` ed `em` esistono tag per ogni sfumatura del testo: `blockquote` per le citazioni, `code` per il codice, `pre` per il testo preformattato, `abbr` per le sigle, `mark` per evidenziare.","en":"Besides `strong` and `em` there are tags for every shade of text: `blockquote` for quotes, `code` for code, `pre` for preformatted text, `abbr` for abbreviations, `mark` for highlights."}},{"t":"code","code":"<blockquote>Il codice è poesia.</blockquote>\\n<p>Usa <code>console.log</code> per il <abbr title=\\"debug\\">dbg</abbr>.</p>\\n<p>La parola <mark>chiave</mark> è qui.</p>\\n<pre>  rispetta\\n    gli spazi</pre>","lang":"html"},{"t":"p","text":{"it":"`pre` mantiene spazi e a capo così come li scrivi. Tutti gli altri tag li riducono a un solo spazio.","en":"`pre` keeps spaces and line breaks exactly as written. All other tags reduce them to a single space."}}]','{"lang":"html","prompt":{"it":"Scrivi un `blockquote` e un paragrafo con dentro una parola in `mark`.","en":"Write a `blockquote` and a paragraph with a word in `mark`."},"start":"","html":"","checks":[{"sel":"blockquote","text":"","label":{"it":"C’è la citazione","en":"The quote is there"}},{"sel":"p mark","text":"","label":{"it":"C’è la parola evidenziata","en":"The highlighted word is there"}}],"hint":"<blockquote>Forgia!</blockquote>\\n<p>Una <mark>parola</mark>.</p>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-intermediate','embed',4,2,'published','{"it":"Iframe e contenuti esterni","en":"Iframes and embedded content"}','[{"t":"p","text":{"it":"`iframe` inserisce un’altra pagina nella tua: mappe, video, widget. Dagli sempre un `title`, per chi usa un lettore di schermo.","en":"`iframe` puts another page inside yours: maps, videos, widgets. Always give it a `title`, for screen reader users."}},{"t":"code","code":"<iframe\\n  src=\\"https://esempio.it/mappa\\"\\n  title=\\"La nostra sede\\"\\n  width=\\"400\\" height=\\"300\\"\\n  loading=\\"lazy\\"></iframe>","lang":"html"},{"t":"p","text":{"it":"Un `iframe` carica codice di altri: con `sandbox` limiti quello che può fare, e `loading=\\"lazy\\"` evita di caricarlo finché non serve.","en":"An `iframe` loads other people’s code: `sandbox` limits what it can do, and `loading=\\"lazy\\"` avoids loading it until needed."}}]','{"lang":"html","prompt":{"it":"Inserisci un `iframe` con `src=\\"mappa.html\\"`, un `title` e `loading=\\"lazy\\"`.","en":"Add an `iframe` with `src=\\"mappa.html\\"`, a `title` and `loading=\\"lazy\\"`."},"start":"","html":"","checks":[{"sel":"iframe[src=\\"mappa.html\\"]","text":"","label":{"it":"Il `src` è giusto","en":"The `src` is right"}},{"sel":"iframe[title]","text":"","label":{"it":"C’è il `title`","en":"The `title` is there"}},{"sel":"iframe[loading=\\"lazy\\"]","text":"","label":{"it":"Il caricamento è pigro","en":"Loading is lazy"}}],"hint":"<iframe src=\\"mappa.html\\" title=\\"Mappa\\" loading=\\"lazy\\"></iframe>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-intermediate','more-inputs',5,2,'published','{"it":"Campi per ogni esigenza","en":"A field for every need"}','[{"t":"p","text":{"it":"I campi moderni fanno molto da soli: `date` apre un calendario, `range` un cursore, `color` una tavolozza, `number` accetta solo cifre, `search` è fatto per le ricerche.","en":"Modern fields do a lot by themselves: `date` opens a calendar, `range` a slider, `color` a palette, `number` takes digits only, `search` is made for searching."}},{"t":"code","code":"<input type=\\"date\\" min=\\"2026-01-01\\">\\n<input type=\\"range\\" min=\\"0\\" max=\\"10\\" step=\\"2\\">\\n<input type=\\"color\\" value=\\"#FF5B2E\\">\\n<select name=\\"corso\\">\\n  <option value=\\"html\\">HTML</option>\\n  <option value=\\"css\\" selected>CSS</option>\\n</select>","lang":"html"},{"t":"p","text":{"it":"In `select`, `selected` indica l’opzione scelta all’inizio. `value` è ciò che riceve il server, il testo è ciò che vede l’utente.","en":"In `select`, `selected` marks the option chosen at the start. `value` is what the server gets, the text is what the user sees."}}]','{"lang":"html","prompt":{"it":"Crea un campo `range` da `0` a `10` e un campo `date`.","en":"Create a `range` field from `0` to `10` and a `date` field."},"start":"","html":"","checks":[{"sel":"input[type=\\"range\\"][min=\\"0\\"][max=\\"10\\"]","text":"","label":{"it":"Il cursore va da 0 a 10","en":"The slider goes from 0 to 10"}},{"sel":"input[type=\\"date\\"]","text":"","label":{"it":"C’è la data","en":"The date is there"}}],"hint":"<input type=\\"range\\" min=\\"0\\" max=\\"10\\">\\n<input type=\\"date\\">"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','semantic',1,2,'published','{"it":"HTML semantico","en":"Semantic HTML"}','[{"t":"p","text":{"it":"I tag semantici dicono **che cosa è** un blocco, non come appare. Motori di ricerca e screen reader li usano per capire la pagina.","en":"Semantic tags say **what a block is**, not how it looks. Search engines and screen readers use them to understand the page."}},{"t":"code","code":"<header>Logo e titolo</header>\\n<nav>Menu principale</nav>\\n<main>\\n  <article>\\n    <h1>Una notizia</h1>\\n    <section>Una parte della notizia</section>\\n  </article>\\n  <aside>Articoli correlati</aside>\\n</main>\\n<footer>Contatti</footer>","lang":"html"},{"t":"p","text":{"it":"`<main>` è il contenuto principale e ce n’è uno solo per pagina. `<article>` è un contenuto che ha senso da solo; `<section>` è una parte tematica, di solito con un titolo. `<div>` non ha significato: usalo solo per raggruppare a fini di stile.","en":"`<main>` is the main content and there is only one per page. `<article>` is content that stands on its own; `<section>` is a thematic part, usually with a heading. `<div>` has no meaning: use it only to group for styling."}}]','{"lang":"html","prompt":{"it":"Struttura la pagina con `header`, `main` contenente un `article`, e `footer`.","en":"Structure the page with `header`, `main` containing an `article`, and `footer`."},"start":"<body>\\n\\n</body>","html":"","checks":[{"sel":"header","text":"","label":{"it":"C’è un `header`","en":"There is a `header`"}},{"sel":"main article","text":"","label":{"it":"Il `main` contiene un `article`","en":"`main` contains an `article`"}},{"sel":"footer","text":"","label":{"it":"C’è un `footer`","en":"There is a `footer`"}}],"hint":"<header>…</header>\\n<main><article>…</article></main>\\n<footer>…</footer>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','rich-forms',2,2,'published','{"it":"Moduli ricchi e validazione","en":"Rich forms and validation"}','[{"t":"p","text":{"it":"Il `type` giusto mostra la tastiera adatta e dà controlli gratuiti: `email`, `url`, `tel`, `number`, `date`, `range`, `color`.","en":"The right `type` shows the suitable keyboard and gives free checks: `email`, `url`, `tel`, `number`, `date`, `range`, `color`."}},{"t":"code","code":"<fieldset>\\n  <legend>Taglia</legend>\\n  <label><input type=\\"radio\\" name=\\"taglia\\" value=\\"s\\"> S</label>\\n  <label><input type=\\"radio\\" name=\\"taglia\\" value=\\"m\\"> M</label>\\n</fieldset>\\n\\n<label for=\\"eta\\">Età</label>\\n<input id=\\"eta\\" type=\\"number\\" min=\\"18\\" max=\\"99\\">\\n\\n<label for=\\"cap\\">CAP</label>\\n<input id=\\"cap\\" pattern=\\"[0-9]{5}\\" title=\\"5 cifre\\">\\n\\n<select name=\\"paese\\">\\n  <option value=\\"it\\">Italia</option>\\n</select>","lang":"html"},{"t":"p","text":{"it":"`<fieldset>` e `<legend>` raggruppano campi legati tra loro. I `radio` con lo stesso `name` si escludono a vicenda. `min`, `max` e `pattern` validano il dato nel browser.","en":"`<fieldset>` and `<legend>` group related fields. `radio` inputs with the same `name` exclude one another. `min`, `max` and `pattern` validate the value in the browser."}},{"t":"tip","text":{"it":"La validazione del browser aiuta l’utente, ma il server deve sempre ricontrollare i dati.","en":"Browser validation helps the user, but the server must always check the data again."}}]','{"lang":"html","prompt":{"it":"Crea un `fieldset` con `legend` e due `radio` con lo stesso `name` «piano».","en":"Create a `fieldset` with a `legend` and two `radio` inputs with the same `name` “piano”."},"start":"<form>\\n\\n</form>","html":"","checks":[{"sel":"fieldset legend","text":"","label":{"it":"Il `fieldset` ha una `legend`","en":"The `fieldset` has a `legend`"}},{"sel":"fieldset input[type=\\"radio\\"][name=\\"piano\\"]","text":"","label":{"it":"C’è un `radio` «piano»","en":"There is a “piano” `radio`"}},{"sel":"fieldset input[type=\\"radio\\"][name=\\"piano\\"] ~ input[type=\\"radio\\"][name=\\"piano\\"], fieldset label ~ label input[type=\\"radio\\"][name=\\"piano\\"]","text":"","label":{"it":"Ce ne sono due","en":"There are two of them"}}],"hint":"<fieldset>\\n  <legend>Piano</legend>\\n  <label><input type=\\"radio\\" name=\\"piano\\"> A</label>\\n  <label><input type=\\"radio\\" name=\\"piano\\"> B</label>\\n</fieldset>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','media',3,2,'published','{"it":"Immagini responsive, audio e video","en":"Responsive images, audio and video"}','[{"t":"p","text":{"it":"`<picture>` e `srcset` fanno scegliere al browser il file più adatto allo schermo: si scaricano meno dati sui telefoni.","en":"`<picture>` and `srcset` let the browser choose the best file for the screen: phones download less data."}},{"t":"code","code":"<picture>\\n  <source srcset=\\"foto.avif\\" type=\\"image/avif\\">\\n  <img src=\\"foto.jpg\\" alt=\\"Il porto al tramonto\\"\\n       width=\\"800\\" height=\\"600\\" loading=\\"lazy\\">\\n</picture>\\n\\n<video src=\\"corso.mp4\\" controls poster=\\"anteprima.jpg\\">\\n  <track kind=\\"captions\\" src=\\"sottotitoli.vtt\\" srclang=\\"it\\">\\n</video>","lang":"html"},{"t":"p","text":{"it":"`width` e `height` riservano lo spazio ed evitano che la pagina salti durante il caricamento. `loading=\\"lazy\\"` rimanda le immagini lontane dallo schermo. In `<video>` e `<audio>` l’attributo `controls` mostra i comandi.","en":"`width` and `height` reserve the space and stop the page jumping while it loads. `loading=\\"lazy\\"` delays images far from the screen. In `<video>` and `<audio>` the `controls` attribute shows the player buttons."}}]','{"lang":"html","prompt":{"it":"Inserisci un `video` con i `controls` e un’immagine con `loading=\\"lazy\\"` e `alt`.","en":"Add a `video` with `controls` and an image with `loading=\\"lazy\\"` and `alt`."},"start":"","html":"","checks":[{"sel":"video[controls]","text":"","label":{"it":"Il video ha i comandi","en":"The video has controls"}},{"sel":"img[loading=\\"lazy\\"]","text":"","label":{"it":"L’immagine è lazy","en":"The image is lazy"}},{"sel":"img[alt]:not([alt=\\"\\"])","text":"","label":{"it":"L’immagine ha un `alt`","en":"The image has an `alt`"}}],"hint":"<video src=\\"v.mp4\\" controls></video>\\n<img src=\\"a.jpg\\" alt=\\"Foto\\" loading=\\"lazy\\">"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','a11y',4,2,'published','{"it":"Accessibilità","en":"Accessibility"}','[{"t":"p","text":{"it":"Una pagina accessibile funziona per tutti, anche da tastiera e con uno screen reader. La prima regola è usare il tag giusto: un `<button>` è già raggiungibile e attivabile con la tastiera, un `<div>` no.","en":"An accessible page works for everyone, keyboard and screen reader included. The first rule is using the right tag: a `<button>` can already be reached and activated with the keyboard, a `<div>` cannot."}},{"t":"code","code":"<button type=\\"button\\" aria-label=\\"Chiudi\\">✕</button>\\n\\n<nav aria-label=\\"Principale\\">…</nav>\\n\\n<p id=\\"aiuto\\">Almeno 8 caratteri</p>\\n<input type=\\"password\\" aria-describedby=\\"aiuto\\">","lang":"html"},{"t":"p","text":{"it":"Gli attributi `aria-*` aggiungono informazioni dove l’HTML non basta: `aria-label` dà un nome a un elemento senza testo, `aria-describedby` collega una descrizione. Rispetta l’ordine dei titoli, senza saltare livelli.","en":"`aria-*` attributes add information where HTML is not enough: `aria-label` names an element with no text, `aria-describedby` links a description. Keep headings in order, without skipping levels."}},{"t":"tip","text":{"it":"La regola d’oro di ARIA: se esiste un tag HTML adatto, usa quello.","en":"The golden rule of ARIA: if a suitable HTML tag exists, use it."}}]','{"lang":"html","prompt":{"it":"Sostituisci il `div` con un vero `button` e dagli un `aria-label` «Chiudi».","en":"Replace the `div` with a real `button` and give it the `aria-label` “Chiudi”."},"start":"<div onclick=\\"chiudi()\\">✕</div>","html":"","checks":[{"sel":"button","text":"","label":{"it":"C’è un `button`","en":"There is a `button`"}},{"sel":"button[aria-label=\\"Chiudi\\"]","text":"","label":{"it":"Ha l’`aria-label` giusto","en":"It has the right `aria-label`"}}],"hint":"<button aria-label=\\"Chiudi\\">✕</button>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','meta',5,3,'published','{"it":"Metadati e tag interattivi","en":"Metadata and interactive tags"}','[{"t":"p","text":{"it":"In `<head>` i metadati spiegano la pagina agli altri programmi. `viewport` è indispensabile sui telefoni, `description` è il testo che i motori di ricerca possono mostrare, i tag Open Graph definiscono l’anteprima dei link condivisi.","en":"In `<head>`, metadata explains the page to other programs. `viewport` is essential on phones, `description` is the text search engines can show, Open Graph tags define the preview of shared links."}},{"t":"code","code":"<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\">\\n<meta name=\\"description\\" content=\\"Corsi di HTML e CSS\\">\\n<meta property=\\"og:title\\" content=\\"Fucina\\">\\n<link rel=\\"stylesheet\\" href=\\"style.css\\">","lang":"html"},{"t":"p","text":{"it":"Alcuni tag sono interattivi senza JavaScript: `<details>` e `<summary>` creano una sezione apribile, `<dialog>` una finestra.","en":"Some tags are interactive with no JavaScript: `<details>` and `<summary>` create a collapsible section, `<dialog>` a window."}},{"t":"code","code":"<details>\\n  <summary>Come funziona?</summary>\\n  <p>Si apre con un tocco.</p>\\n</details>","lang":"html"}]','{"lang":"html","prompt":{"it":"Crea un `details` con un `summary` e un paragrafo.","en":"Create a `details` with a `summary` and a paragraph."},"start":"","html":"","checks":[{"sel":"details summary","text":"","label":{"it":"C’è un `summary` in `details`","en":"There is a `summary` in `details`"}},{"sel":"details p","text":"","label":{"it":"C’è un paragrafo da aprire","en":"There is a paragraph to reveal"}}],"hint":"<details>\\n  <summary>Titolo</summary>\\n  <p>Testo</p>\\n</details>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','data-attrs',6,3,'published','{"it":"Attributi data e template","en":"Data attributes and templates"}','[{"t":"p","text":{"it":"Gli attributi `data-*` conservano informazioni personalizzate su un elemento: li leggeranno CSS e JavaScript. Il nome dopo `data-` lo scegli tu.","en":"`data-*` attributes keep custom information on an element, for CSS and JavaScript to read. You choose the name after `data-`."}},{"t":"code","code":"<button data-prodotto=\\"42\\" data-colore=\\"rosso\\">Compra</button>\\n\\n<template id=\\"riga\\">\\n  <li class=\\"voce\\"></li>\\n</template>","lang":"html"},{"t":"p","text":{"it":"`<template>` contiene HTML che il browser non mostra: è uno stampo da copiare al momento giusto.","en":"`<template>` holds HTML the browser does not show: it is a mould to copy at the right moment."}}]','{"lang":"html","prompt":{"it":"Crea un `button` con l’attributo `data-prezzo` uguale a `10`.","en":"Create a `button` with the `data-prezzo` attribute equal to `10`."},"start":"","html":"","checks":[{"sel":"button[data-prezzo=\\"10\\"]","text":"","label":{"it":"Il bottone ha `data-prezzo=\\"10\\"`","en":"The button has `data-prezzo=\\"10\\"`"}}],"hint":"<button data-prezzo=\\"10\\">Compra</button>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','seo',7,3,'published','{"it":"SEO e condivisione","en":"SEO and sharing"}','[{"t":"p","text":{"it":"I motori di ricerca leggono `title` e `description`. Le reti sociali leggono i tag **Open Graph**, che decidono titolo e immagine quando condividi un link.","en":"Search engines read `title` and `description`. Social networks read **Open Graph** tags, which set the title and image when you share a link."}},{"t":"code","code":"<title>Fucina: impara il web giocando</title>\\n<meta name=\\"description\\" content=\\"Corsi a livelli di HTML e CSS.\\">\\n<meta property=\\"og:title\\" content=\\"Fucina\\">\\n<meta property=\\"og:image\\" content=\\"https://esempio.it/og.png\\">\\n<link rel=\\"canonical\\" href=\\"https://esempio.it/\\">","lang":"html"},{"t":"p","text":{"it":"`canonical` indica l’indirizzo ufficiale di una pagina raggiungibile da più URL, così i motori non la considerano un doppione.","en":"`canonical` gives the official address of a page reachable from several URLs, so engines do not treat it as a duplicate."}}]','{"lang":"html","prompt":{"it":"Aggiungi nel `head` un `meta` con `name=\\"description\\"`.","en":"Add to the `head` a `meta` with `name=\\"description\\"`."},"start":"<head>\\n  <title>Fucina</title>\\n</head>","html":"","checks":[{"re":"<meta[^>]+name=\\"description\\"","label":{"it":"C’è la description","en":"The description is there"}}],"hint":"<head>\\n  <title>Fucina</title>\\n  <meta name=\\"description\\" content=\\"Impara\\">\\n</head>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','selectors',1,1,'published','{"it":"Regole e selettori","en":"Rules and selectors"}','[{"t":"p","text":{"it":"Il CSS descrive l’**aspetto** della pagina con delle regole. Una regola ha un selettore, che sceglie gli elementi, e delle dichiarazioni `proprietà: valore`.","en":"CSS describes the **look** of the page with rules. A rule has a selector, which picks the elements, and `property: value` declarations."}},{"t":"code","code":"p { color: navy; }          /* tutti i paragrafi */\\n.nota { font-size: 14px; }  /* la classe nota */\\n#box { width: 200px; }      /* l’id box */\\nnav a { color: red; }       /* i link dentro nav */\\na:hover { color: green; }   /* il link sotto al mouse */","lang":"css"},{"t":"p","text":{"it":"Una classe si riusa quante volte vuoi, un `id` è unico nella pagina. `:hover` è una pseudo-classe: indica uno stato dell’elemento. Lo spazio tra due selettori significa «dentro».","en":"A class can be reused as often as you want, an `id` is unique in the page. `:hover` is a pseudo-class: it marks a state of the element. The space between two selectors means “inside”."}}]','{"lang":"css","prompt":{"it":"Colora i paragrafi con la classe `nota` di rosso (`red`) e imposta a `200px` la larghezza dell’id `box`.","en":"Colour the paragraphs with the `nota` class red (`red`) and set the width of the `box` id to `200px`."},"start":"/* Scrivi qui le tue regole */","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":".nota","prop":"color","value":"rgb(255, 0, 0)","label":{"it":"La nota è rossa","en":"The note is red"}},{"sel":"#box","prop":"width","value":"200px","label":{"it":"Il box è largo 200px","en":"The box is 200px wide"}}],"hint":".nota { color: red; }\\n#box { width: 200px; }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','colors',2,1,'published','{"it":"Colori e testi","en":"Colours and text"}','[{"t":"p","text":{"it":"Un colore si può scrivere in molti modi: per nome, in esadecimale, in `rgb()` o in `hsl()`. L’ultimo numero o la barra indicano la trasparenza.","en":"A colour can be written in many ways: by name, in hexadecimal, in `rgb()` or in `hsl()`. A final value after a slash sets the transparency."}},{"t":"code","code":"h1 {\\n  color: #E8590C;\\n  background-color: rgb(255 240 230);\\n  font-family: Georgia, serif;\\n  font-size: 2rem;\\n  font-weight: 700;\\n  line-height: 1.3;\\n  text-align: center;\\n}","lang":"css"},{"t":"p","text":{"it":"`font-family` indica un elenco di caratteri, dal preferito al generico. `rem` è relativo alla dimensione di base del documento: si adatta alle impostazioni dell’utente meglio di `px`.","en":"`font-family` lists fonts, from the preferred one to a generic one. `rem` is relative to the base size of the document: it respects user settings better than `px`."}},{"t":"tip","text":{"it":"Controlla sempre il contrasto: un testo poco leggibile è un testo perso.","en":"Always check the contrast: text that is hard to read is lost text."}}]','{"lang":"css","prompt":{"it":"Centra il testo di `.titolo` e rendilo di colore `#E8590C`.","en":"Centre the text of `.titolo` and give it the colour `#E8590C`."},"start":".titolo {\\n\\n}","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":".titolo","prop":"text-align","value":"center","label":{"it":"Il titolo è centrato","en":"The heading is centred"}},{"sel":".titolo","prop":"color","value":"rgb(232, 89, 12)","label":{"it":"Il colore è #E8590C","en":"The colour is #E8590C"}}],"hint":".titolo {\\n  text-align: center;\\n  color: #E8590C;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','box',3,1,'published','{"it":"Il box model","en":"The box model"}','[{"t":"p","text":{"it":"Ogni elemento è una scatola fatta di quattro strati: il **contenuto**, il `padding` (spazio interno), il `border` e il `margin` (spazio esterno).","en":"Every element is a box made of four layers: the **content**, the `padding` (inner space), the `border` and the `margin` (outer space)."}},{"t":"code","code":"* { box-sizing: border-box; }\\n\\n.card {\\n  width: 300px;\\n  padding: 16px;\\n  border: 1px solid #ccc;\\n  margin: 0 auto;\\n  border-radius: 12px;\\n}","lang":"css"},{"t":"p","text":{"it":"Con `box-sizing: border-box` la larghezza comprende padding e bordo, ed è molto più facile fare i conti. `margin: 0 auto` centra un blocco con una larghezza. Con due valori, il primo è sopra e sotto, il secondo a destra e sinistra.","en":"With `box-sizing: border-box` the width includes padding and border, which makes the maths far easier. `margin: 0 auto` centres a block with a width. With two values, the first is top and bottom, the second right and left."}}]','{"lang":"css","prompt":{"it":"Dai a `#box` un `padding` di `20px` e un `border-radius` di `12px`.","en":"Give `#box` a `padding` of `20px` and a `border-radius` of `12px`."},"start":"#box {\\n  background: #ffe8d6;\\n}","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":"#box","prop":"padding-top","value":"20px","label":{"it":"Il padding è 20px","en":"The padding is 20px"}},{"sel":"#box","prop":"border-top-left-radius","value":"12px","label":{"it":"Gli angoli sono arrotondati","en":"The corners are rounded"}}],"hint":"padding: 20px;\\nborder-radius: 12px;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','display',4,1,'published','{"it":"Display: blocchi e righe","en":"Display: blocks and inlines"}','[{"t":"p","text":{"it":"`display` decide come si comporta la scatola. Un elemento `block` occupa tutta la riga, come `<p>` e `<div>`. Un elemento `inline` scorre nel testo, come `<a>` e `<strong>`, e ignora `width` e `height`.","en":"`display` decides how the box behaves. A `block` element takes the whole line, like `<p>` and `<div>`. An `inline` element flows in the text, like `<a>` and `<strong>`, and ignores `width` and `height`."}},{"t":"code","code":"a.bottone { display: inline-block; padding: 8px 16px; }\\n.nascosto { display: none; }\\n.invisibile { visibility: hidden; }","lang":"css"},{"t":"p","text":{"it":"`inline-block` scorre nel testo ma accetta le dimensioni. `display: none` toglie l’elemento dalla pagina, mentre `visibility: hidden` lo nasconde lasciando il suo spazio.","en":"`inline-block` flows in the text but accepts sizes. `display: none` takes the element off the page, while `visibility: hidden` hides it and leaves its space."}}]','{"lang":"css","prompt":{"it":"Fai diventare il link un `inline-block` con `padding` di `10px`, e nascondi `.nota` con `display: none`.","en":"Turn the link into an `inline-block` with `10px` of `padding`, and hide `.nota` with `display: none`."},"start":"","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":"a","prop":"display","value":"inline-block","label":{"it":"Il link è inline-block","en":"The link is inline-block"}},{"sel":"a","prop":"padding-left","value":"10px","label":{"it":"Il link ha 10px di padding","en":"The link has 10px of padding"}},{"sel":".nota","prop":"display","value":"none","label":{"it":"La nota è nascosta","en":"The note is hidden"}}],"hint":"a { display: inline-block; padding: 10px; }\\n.nota { display: none; }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','position',5,2,'published','{"it":"Il posizionamento","en":"Positioning"}','[{"t":"p","text":{"it":"`position` sposta gli elementi fuori dal flusso normale. Il valore predefinito è `static`. Con `relative` l’elemento resta al suo posto e fa da riferimento per i figli `absolute`.","en":"`position` moves elements out of the normal flow. The default value is `static`. With `relative` the element stays in place and acts as a reference for `absolute` children."}},{"t":"code","code":".card { position: relative; }\\n.etichetta { position: absolute; top: 8px; right: 8px; }\\n.barra { position: sticky; top: 0; }\\n.chat { position: fixed; bottom: 16px; right: 16px; z-index: 10; }","lang":"css"},{"t":"p","text":{"it":"`fixed` resta fermo rispetto allo schermo, `sticky` scorre e poi si ferma alla soglia indicata. `z-index` decide chi sta sopra tra gli elementi posizionati.","en":"`fixed` stays still relative to the screen, `sticky` scrolls and then stops at the given threshold. `z-index` decides who is on top among positioned elements."}}]','{"lang":"css","prompt":{"it":"Rendi `#box` `relative` e sposta `.nota` in `absolute` con `top: 0`.","en":"Make `#box` `relative` and move `.nota` to `absolute` with `top: 0`."},"start":"","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":"#box","prop":"position","value":"relative","label":{"it":"Il box è relative","en":"The box is relative"}},{"sel":".nota","prop":"position","value":"absolute","label":{"it":"La nota è absolute","en":"The note is absolute"}},{"sel":".nota","prop":"top","value":"0px","label":{"it":"La nota è in alto","en":"The note is at the top"}}],"hint":"#box { position: relative; }\\n.nota { position: absolute; top: 0; }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','cascade',6,2,'published','{"it":"Cascata e specificità","en":"Cascade and specificity"}','[{"t":"p","text":{"it":"Quando più regole riguardano lo stesso elemento, vince quella con la **specificità** maggiore. L’`id` batte la classe, la classe batte il tag. A parità di specificità vince l’ultima scritta.","en":"When several rules target the same element, the one with the higher **specificity** wins. An `id` beats a class, a class beats a tag. With equal specificity the last one written wins."}},{"t":"code","code":"p { color: black; }        /* 0,0,1 */\\n.nota { color: blue; }     /* 0,1,0 → vince */\\np.nota { color: green; }   /* 0,1,1 → vince ancora */\\n#box { color: red; }       /* 1,0,0 → batte tutte */","lang":"css"},{"t":"p","text":{"it":"Alcune proprietà, come `color` e `font-family`, si **ereditano** dai genitori; altre, come `margin` e `border`, no. `!important` scavalca tutto: evitalo, perché rende il CSS difficile da correggere.","en":"Some properties, like `color` and `font-family`, are **inherited** from parents; others, like `margin` and `border`, are not. `!important` overrides everything: avoid it, because it makes CSS hard to fix."}}]','{"lang":"css","prompt":{"it":"Rendi blu (`blue`) il testo di `p.nota` senza toccare la regola esistente e senza `!important`.","en":"Make the text of `p.nota` blue (`blue`) without touching the existing rule and without `!important`."},"start":".nota { color: red; }","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":"p.nota","prop":"color","value":"rgb(0, 0, 255)","label":{"it":"La nota è blu","en":"The note is blue"}},{"re":"^(?![\\\\s\\\\S]*!important)","label":{"it":"Niente `!important`","en":"No `!important`"}}],"hint":"p.nota { color: blue; }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','backgrounds',7,2,'published','{"it":"Sfondi e ombre","en":"Backgrounds and shadows"}','[{"t":"p","text":{"it":"`background` può essere un colore, un’immagine o una sfumatura. `box-shadow` aggiunge un’ombra alla scatola, `text-shadow` al testo.","en":"`background` can be a colour, an image or a gradient. `box-shadow` adds a shadow to the box, `text-shadow` to the text."}},{"t":"code","code":".card {\\n  background: linear-gradient(135deg, #FF5B2E, #FFC53D);\\n  box-shadow: 0 4px 12px rgb(0 0 0 / .25);\\n}","lang":"css"},{"t":"p","text":{"it":"I valori di `box-shadow` sono: spostamento orizzontale, verticale, sfocatura e colore.","en":"The values of `box-shadow` are: horizontal offset, vertical offset, blur and colour."}}]','{"lang":"css","prompt":{"it":"Dai a `#box` lo sfondo `rgb(255, 197, 61)` e angoli da `16px`.","en":"Give `#box` the background `rgb(255, 197, 61)` and `16px` corners."},"start":"#box {\\n\\n}","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":"#box","prop":"background-color","value":"rgb(255, 197, 61)","label":{"it":"Lo sfondo è giusto","en":"The background is right"}},{"sel":"#box","prop":"border-top-left-radius","value":"16px","label":{"it":"Gli angoli sono arrotondati","en":"The corners are rounded"}}],"hint":"#box {\\n  background: rgb(255, 197, 61);\\n  border-radius: 16px;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','units',8,2,'published','{"it":"Unità di misura","en":"Units"}','[{"t":"p","text":{"it":"`px` è fisso, `%` dipende dal contenitore, `em` dalla dimensione del testo dell’elemento, `rem` da quella della radice, `vw` e `vh` dallo schermo.","en":"`px` is fixed, `%` depends on the container, `em` on the element’s text size, `rem` on the root’s, `vw` and `vh` on the screen."}},{"t":"code","code":".box {\\n  width: 50%;       /* metà del contenitore */\\n  padding: 1.5rem;  /* 24px con base 16px */\\n  height: 100vh;    /* tutta l’altezza dello schermo */\\n}","lang":"css"},{"t":"tip","text":{"it":"Per i testi preferisci `rem`: rispetta le impostazioni di chi legge.","en":"For text prefer `rem`: it respects the reader’s settings."}}]','{"lang":"css","prompt":{"it":"Imposta `#box` a una larghezza di `50%` e un `padding` di `1rem`.","en":"Set `#box` to a width of `50%` and a `padding` of `1rem`."},"start":"#box {\\n\\n}","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"re":"width\\\\s*:\\\\s*50%","label":{"it":"La larghezza è 50%","en":"The width is 50%"}},{"re":"padding\\\\s*:\\\\s*1rem","label":{"it":"Il padding è 1rem","en":"The padding is 1rem"}}],"hint":"#box {\\n  width: 50%;\\n  padding: 1rem;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-intermediate','combinators',1,1,'published','{"it":"Combinatori e attributi","en":"Combinators and attributes"}','[{"t":"p","text":{"it":"I combinatori legano due selettori: lo spazio significa «dentro», `>` «figlio diretto», `+` «subito dopo», `~` «fratelli successivi». Con le parentesi quadre scegli in base a un attributo.","en":"Combinators link two selectors: a space means “inside”, `>` “direct child”, `+` “right after”, `~` “following siblings”. Square brackets pick by attribute."}},{"t":"code","code":"ul > li { list-style: none; }\\nh1 + p { font-size: 1.2rem; }\\na[href^=\\"https\\"] { color: green; }\\ninput[type=\\"email\\"] { border-color: blue; }","lang":"css"},{"t":"p","text":{"it":"`^=` significa «inizia con», `$=` «finisce con», `*=` «contiene».","en":"`^=` means “starts with”, `$=` “ends with”, `*=` “contains”."}}]','{"lang":"css","prompt":{"it":"Togli i pallini ai figli diretti di `.lista` (`list-style-type: none`) e rendi blu (`blue`) il `.nota` subito dopo `.titolo`.","en":"Remove the bullets from the direct children of `.lista` (`list-style-type: none`) and make blue (`blue`) the `.nota` right after `.titolo`."},"start":"","html":"<nav class=\\"menu\\"><a href=\\"#\\">Home</a><a href=\\"#\\">Corsi</a></nav>\\n<h1 class=\\"titolo\\">Fucina</h1>\\n<p class=\\"nota\\">Una nota.</p>\\n<ul class=\\"lista\\"><li>Uno</li><li>Due</li><li>Tre</li></ul>\\n<button class=\\"btn\\">Inizia</button>","checks":[{"sel":".lista li","prop":"list-style-type","value":"none","label":{"it":"Niente pallini","en":"No bullets"}},{"sel":".nota","prop":"color","value":"rgb(0, 0, 255)","label":{"it":"La nota è blu","en":"The note is blue"}}],"hint":".lista > li {\\n  list-style-type: none;\\n}\\n.titolo + .nota {\\n  color: blue;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-intermediate','states',2,1,'published','{"it":"Stati e interazioni","en":"States and interactions"}','[{"t":"p","text":{"it":"Le pseudo-classi reagiscono a quello che fa l’utente: `:hover` al passaggio, `:active` alla pressione, `:focus` sul campo attivo, `:focus-visible` quando si usa la tastiera, `:disabled` sui controlli spenti.","en":"Pseudo-classes react to what the user does: `:hover` on passing over, `:active` on pressing, `:focus` on the active field, `:focus-visible` when using the keyboard, `:disabled` on switched-off controls."}},{"t":"code","code":".btn:hover { background: tomato; }\\n.btn:active { transform: translateY(2px); }\\n.btn:focus-visible { outline: 3px solid gold; }\\n.btn:disabled { opacity: .5; cursor: not-allowed; }\\ninput:invalid { border-color: red; }","lang":"css"},{"t":"tip","text":{"it":"Non togliere mai `outline` senza sostituirlo: chi usa la tastiera si perderebbe.","en":"Never remove `outline` without replacing it: keyboard users would get lost."}}]','{"lang":"css","prompt":{"it":"Scrivi `.btn:hover` con `background: tomato` e `.btn:focus-visible` con un `outline`.","en":"Write `.btn:hover` with `background: tomato` and `.btn:focus-visible` with an `outline`."},"start":"","html":"<nav class=\\"menu\\"><a href=\\"#\\">Home</a><a href=\\"#\\">Corsi</a></nav>\\n<h1 class=\\"titolo\\">Fucina</h1>\\n<p class=\\"nota\\">Una nota.</p>\\n<ul class=\\"lista\\"><li>Uno</li><li>Due</li><li>Tre</li></ul>\\n<button class=\\"btn\\">Inizia</button>","checks":[{"re":"\\\\.btn:hover\\\\s*\\\\{[^}]*tomato","label":{"it":"`:hover` è tomato","en":"`:hover` is tomato"}},{"re":"\\\\.btn:focus-visible\\\\s*\\\\{[^}]*outline","label":{"it":"`:focus-visible` ha un outline","en":"`:focus-visible` has an outline"}}],"hint":".btn:hover {\\n  background: tomato;\\n}\\n.btn:focus-visible {\\n  outline: 3px solid gold;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-intermediate','typography',3,1,'published','{"it":"Tipografia","en":"Typography"}','[{"t":"p","text":{"it":"Il testo è quasi tutto il web. `line-height` dà respiro, `letter-spacing` spazia le lettere, `text-transform` cambia maiuscole e minuscole, `font-weight` il peso. Un buon testo sta tra 45 e 75 caratteri per riga.","en":"Text is nearly all of the web. `line-height` gives room, `letter-spacing` spaces letters, `text-transform` changes case, `font-weight` the weight. Good text sits between 45 and 75 characters per line."}},{"t":"code","code":"@font-face {\\n  font-family: \\"Forgia\\";\\n  src: url(\\"forgia.woff2\\") format(\\"woff2\\");\\n  font-display: swap;\\n}\\np {\\n  font-family: \\"Forgia\\", sans-serif;\\n  line-height: 1.6;\\n  max-width: 65ch;\\n}","lang":"css"},{"t":"p","text":{"it":"`ch` è la larghezza del carattere zero: `65ch` è una riga comoda. `font-display: swap` mostra subito il testo mentre il font arriva.","en":"`ch` is the width of the zero character: `65ch` is a comfortable line. `font-display: swap` shows text at once while the font arrives."}}]','{"lang":"css","prompt":{"it":"Dai a `.nota` un `line-height` di `1.6` e `text-transform: uppercase`.","en":"Give `.nota` a `line-height` of `1.6` and `text-transform: uppercase`."},"start":".nota {\\n\\n}","html":"<nav class=\\"menu\\"><a href=\\"#\\">Home</a><a href=\\"#\\">Corsi</a></nav>\\n<h1 class=\\"titolo\\">Fucina</h1>\\n<p class=\\"nota\\">Una nota.</p>\\n<ul class=\\"lista\\"><li>Uno</li><li>Due</li><li>Tre</li></ul>\\n<button class=\\"btn\\">Inizia</button>","checks":[{"re":"line-height\\\\s*:\\\\s*1\\\\.6","label":{"it":"L’interlinea è 1.6","en":"The line height is 1.6"}},{"sel":".nota","prop":"text-transform","value":"uppercase","label":{"it":"Il testo è in maiuscolo","en":"The text is uppercase"}}],"hint":".nota {\\n  line-height: 1.6;\\n  text-transform: uppercase;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-intermediate','overflow',4,2,'published','{"it":"Overflow e livelli","en":"Overflow and layers"}','[{"t":"p","text":{"it":"Quando il contenuto è più grande della scatola, `overflow` decide che cosa fare: `visible` lo lascia uscire, `hidden` lo taglia, `auto` aggiunge le barre se servono. `z-index` sceglie chi sta sopra tra gli elementi posizionati.","en":"When content is bigger than its box, `overflow` decides what to do: `visible` lets it out, `hidden` cuts it, `auto` adds scrollbars if needed. `z-index` picks who is on top among positioned elements."}},{"t":"code","code":".riquadro {\\n  height: 120px;\\n  overflow: auto;\\n}\\n.finestra {\\n  position: fixed;\\n  z-index: 10;\\n}\\n.testo {\\n  white-space: nowrap;\\n  overflow: hidden;\\n  text-overflow: ellipsis;\\n}","lang":"css"},{"t":"p","text":{"it":"Le ultime tre regole, insieme, troncano una riga con i puntini di sospensione.","en":"The last three rules, together, cut a line with an ellipsis."}}]','{"lang":"css","prompt":{"it":"Dai a `.lista` un `height` di `40px` e `overflow: auto`.","en":"Give `.lista` a `height` of `40px` and `overflow: auto`."},"start":".lista {\\n\\n}","html":"<nav class=\\"menu\\"><a href=\\"#\\">Home</a><a href=\\"#\\">Corsi</a></nav>\\n<h1 class=\\"titolo\\">Fucina</h1>\\n<p class=\\"nota\\">Una nota.</p>\\n<ul class=\\"lista\\"><li>Uno</li><li>Due</li><li>Tre</li></ul>\\n<button class=\\"btn\\">Inizia</button>","checks":[{"sel":".lista","prop":"height","value":"40px","label":{"it":"L’altezza è 40px","en":"The height is 40px"}},{"sel":".lista","prop":"overflow-y","value":"auto","label":{"it":"Si scorre se serve","en":"It scrolls if needed"}}],"hint":".lista {\\n  height: 40px;\\n  overflow: auto;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-intermediate','components',5,2,'published','{"it":"Bottoni e menu","en":"Buttons and menus"}','[{"t":"p","text":{"it":"Con quello che sai puoi già costruire componenti veri. Un bottone è una scatola con padding, angoli, colori e stati. Un menu è una lista di link senza pallini, con gli elementi in riga.","en":"With what you know you can already build real components. A button is a box with padding, corners, colours and states. A menu is a list of links without bullets, with items in a row."}},{"t":"code","code":".btn {\\n  display: inline-block;\\n  padding: 10px 18px;\\n  border: 0;\\n  border-radius: 12px;\\n  background: #FF5B2E;\\n  color: white;\\n  cursor: pointer;\\n}\\n.menu a {\\n  display: inline-block;\\n  padding: 8px 12px;\\n  text-decoration: none;\\n}","lang":"css"},{"t":"tip","text":{"it":"Un bottone deve essere facile da toccare: almeno 44 pixel di altezza su telefono.","en":"A button must be easy to tap: at least 44 pixels high on phones."}}]','{"lang":"css","prompt":{"it":"Stila `.btn`: `padding` di `12px`, `border-radius` di `12px`, `cursor: pointer`.","en":"Style `.btn`: `padding` of `12px`, `border-radius` of `12px`, `cursor: pointer`."},"start":".btn {\\n\\n}","html":"<nav class=\\"menu\\"><a href=\\"#\\">Home</a><a href=\\"#\\">Corsi</a></nav>\\n<h1 class=\\"titolo\\">Fucina</h1>\\n<p class=\\"nota\\">Una nota.</p>\\n<ul class=\\"lista\\"><li>Uno</li><li>Due</li><li>Tre</li></ul>\\n<button class=\\"btn\\">Inizia</button>","checks":[{"sel":".btn","prop":"padding-top","value":"12px","label":{"it":"Il padding è 12px","en":"The padding is 12px"}},{"sel":".btn","prop":"border-top-left-radius","value":"12px","label":{"it":"Gli angoli sono tondi","en":"The corners are round"}},{"sel":".btn","prop":"cursor","value":"pointer","label":{"it":"Il cursore è giusto","en":"The cursor is right"}}],"hint":".btn {\\n  padding: 12px;\\n  border-radius: 12px;\\n  cursor: pointer;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','flex',1,2,'published','{"it":"Flexbox","en":"Flexbox"}','[{"t":"p","text":{"it":"Flexbox dispone i figli lungo **una dimensione**. Si attiva sul contenitore con `display: flex`.","en":"Flexbox lays out children along **one dimension**. You turn it on for the container with `display: flex`."}},{"t":"code","code":".lista {\\n  display: flex;\\n  flex-direction: row;\\n  justify-content: space-between; /* asse principale */\\n  align-items: center;            /* asse trasversale */\\n  gap: 16px;\\n  flex-wrap: wrap;\\n}\\n.card { flex: 1; }","lang":"css"},{"t":"p","text":{"it":"`justify-content` distribuisce lungo l’asse principale, `align-items` lungo quello perpendicolare. `gap` è lo spazio tra i figli. `flex: 1` su un figlio gli fa prendere lo spazio libero.","en":"`justify-content` distributes along the main axis, `align-items` along the cross axis. `gap` is the space between children. `flex: 1` on a child makes it take the free space."}},{"t":"tip","text":{"it":"Con `flex-direction: column` gli assi si scambiano: `justify-content` lavora in verticale.","en":"With `flex-direction: column` the axes swap: `justify-content` works vertically."}}]','{"lang":"css","prompt":{"it":"Disponi `.lista` in flex, con `gap` di `16px` e `justify-content: space-between`.","en":"Lay out `.lista` with flex, with a `gap` of `16px` and `justify-content: space-between`."},"start":".card { background: #ffe8d6; padding: 12px; }\\n\\n.lista {\\n\\n}","html":"<div class=\\"lista\\">\\n  <div class=\\"card\\">Uno</div>\\n  <div class=\\"card\\">Due</div>\\n  <div class=\\"card\\">Tre</div>\\n</div>","checks":[{"sel":".lista","prop":"display","value":"flex","label":{"it":"La lista è flex","en":"The list is flex"}},{"sel":".lista","prop":"row-gap","value":"16px","label":{"it":"Il gap è 16px","en":"The gap is 16px"}},{"sel":".lista","prop":"justify-content","value":"space-between","label":{"it":"I figli sono distribuiti","en":"The children are distributed"}}],"hint":"display: flex;\\ngap: 16px;\\njustify-content: space-between;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','grid',2,2,'published','{"it":"CSS Grid","en":"CSS Grid"}','[{"t":"p","text":{"it":"Grid dispone gli elementi in **due dimensioni**: righe e colonne insieme. L’unità `fr` è una frazione dello spazio libero.","en":"Grid lays out elements in **two dimensions**: rows and columns together. The `fr` unit is a fraction of the free space."}},{"t":"code","code":".lista {\\n  display: grid;\\n  grid-template-columns: 200px 1fr 1fr;\\n  gap: 12px;\\n}\\n.hero { grid-column: 1 / 3; } /* dalla linea 1 alla 3 */\\n\\n/* Colonne che si adattano da sole */\\n.galleria {\\n  display: grid;\\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\\n}","lang":"css"},{"t":"p","text":{"it":"`repeat(3, 1fr)` crea tre colonne uguali. `minmax()` fissa un minimo e un massimo: insieme a `auto-fit` ottieni una griglia responsive senza media query.","en":"`repeat(3, 1fr)` creates three equal columns. `minmax()` sets a minimum and a maximum: together with `auto-fit` you get a responsive grid with no media queries."}},{"t":"tip","text":{"it":"Flexbox per una riga di elementi, Grid per una vera impaginazione a righe e colonne.","en":"Flexbox for a row of items, Grid for a real layout of rows and columns."}}]','{"lang":"css","prompt":{"it":"Trasforma `.lista` in una griglia di tre colonne uguali con `gap` di `12px`.","en":"Turn `.lista` into a grid of three equal columns with a `gap` of `12px`."},"start":".card { background: #ffe8d6; padding: 12px; }","html":"<div class=\\"lista\\">\\n  <div class=\\"card\\">Uno</div>\\n  <div class=\\"card\\">Due</div>\\n  <div class=\\"card\\">Tre</div>\\n</div>","checks":[{"sel":".lista","prop":"display","value":"grid","label":{"it":"La lista è una griglia","en":"The list is a grid"}},{"sel":".lista","prop":"row-gap","value":"12px","label":{"it":"Il gap è 12px","en":"The gap is 12px"}},{"re":"grid-template-columns\\\\s*:\\\\s*(repeat\\\\(\\\\s*3\\\\s*,\\\\s*1fr\\\\s*\\\\)|1fr\\\\s+1fr\\\\s+1fr)","label":{"it":"Ci sono tre colonne uguali","en":"There are three equal columns"}}],"hint":".lista {\\n  display: grid;\\n  grid-template-columns: repeat(3, 1fr);\\n  gap: 12px;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','responsive',3,2,'published','{"it":"Responsive design","en":"Responsive design"}','[{"t":"p","text":{"it":"Una pagina responsive si adatta a ogni schermo. Si parte dal telefono e con le **media query** si aggiungono regole per gli schermi più grandi: è il metodo *mobile first*.","en":"A responsive page adapts to every screen. You start from the phone and add rules for larger screens with **media queries**: that is the *mobile first* method."}},{"t":"code","code":".lista { display: grid; gap: 12px; }\\n\\n@media (min-width: 700px) {\\n  .lista { grid-template-columns: 1fr 1fr; }\\n}\\n\\nimg { max-width: 100%; height: auto; }\\nh1 { font-size: clamp(1.5rem, 5vw, 3rem); }","lang":"css"},{"t":"p","text":{"it":"`clamp(min, ideale, max)` fa crescere un valore entro due limiti. `vw` è l’1% della larghezza dello schermo. `max-width: 100%` impedisce alle immagini di uscire dal contenitore.","en":"`clamp(min, ideal, max)` grows a value within two limits. `vw` is 1% of the screen width. `max-width: 100%` stops images overflowing their container."}}]','{"lang":"css","prompt":{"it":"Scrivi una media query `min-width: 700px` che metta `.lista` in `display: flex`.","en":"Write a `min-width: 700px` media query that sets `.lista` to `display: flex`."},"start":"","html":"<div class=\\"lista\\">\\n  <div class=\\"card\\">Uno</div>\\n  <div class=\\"card\\">Due</div>\\n  <div class=\\"card\\">Tre</div>\\n</div>","checks":[{"re":"@media[^{]*min-width\\\\s*:\\\\s*700px","label":{"it":"C’è la media query","en":"The media query is there"}},{"re":"@media[^{]*\\\\{[^}]*\\\\.lista\\\\s*\\\\{[^}]*display\\\\s*:\\\\s*flex","label":{"it":"Dentro c’è `.lista` in flex","en":"`.lista` is flex inside it"}}],"hint":"@media (min-width: 700px) {\\n  .lista { display: flex; }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','variables',4,2,'published','{"it":"Variabili e funzioni CSS","en":"CSS variables and functions"}','[{"t":"p","text":{"it":"Le **proprietà personalizzate** iniziano con `--` e si leggono con `var()`. A differenza delle variabili di Sass esistono nel browser, quindi si possono cambiare dal vivo, ad esempio per il tema scuro.","en":"**Custom properties** start with `--` and are read with `var()`. Unlike Sass variables they exist in the browser, so they can change live, for a dark theme for example."}},{"t":"code","code":":root { --brand: #E8590C; --spazio: 16px; }\\n\\n.card {\\n  color: var(--brand);\\n  padding: calc(var(--spazio) * 2);\\n  border-color: var(--bordo, #ccc); /* valore di riserva */\\n}\\n\\n@media (prefers-color-scheme: dark) {\\n  :root { --brand: #FFA94D; }\\n}","lang":"css"},{"t":"p","text":{"it":"`calc()` fa i conti anche tra unità diverse, come `calc(100% - 40px)`. Il secondo argomento di `var()` è il valore di riserva, usato se la variabile non esiste.","en":"`calc()` does maths even between different units, as in `calc(100% - 40px)`. The second argument of `var()` is the fallback, used if the variable does not exist."}}]','{"lang":"css","prompt":{"it":"Dichiara `--brand: #E8590C` in `:root` e usala come `color` di `.card`.","en":"Declare `--brand: #E8590C` in `:root` and use it as the `color` of `.card`."},"start":"","html":"<div class=\\"lista\\">\\n  <div class=\\"card\\">Uno</div>\\n  <div class=\\"card\\">Due</div>\\n  <div class=\\"card\\">Tre</div>\\n</div>","checks":[{"re":":root\\\\s*\\\\{[^}]*--brand\\\\s*:\\\\s*#e8590c","label":{"it":"La variabile è dichiarata","en":"The variable is declared"}},{"re":"\\\\.card\\\\s*\\\\{[^}]*color\\\\s*:\\\\s*var\\\\(\\\\s*--brand","label":{"it":"`.card` usa `var(--brand)`","en":"`.card` uses `var(--brand)`"}},{"sel":".card","prop":"color","value":"rgb(232, 89, 12)","label":{"it":"Il colore è applicato","en":"The colour is applied"}}],"hint":":root { --brand: #E8590C; }\\n.card { color: var(--brand); }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','motion',5,3,'published','{"it":"Transizioni e animazioni","en":"Transitions and animations"}','[{"t":"p","text":{"it":"`transition` anima il passaggio tra due stati. `transform` sposta, ruota e ingrandisce senza disturbare l’impaginazione, ed è molto fluido.","en":"`transition` animates the change between two states. `transform` moves, rotates and scales without disturbing the layout, and is very smooth."}},{"t":"code","code":".card { transition: transform .2s ease; }\\n.card:hover { transform: translateY(-4px) scale(1.02); }\\n\\n@keyframes pulsa {\\n  from { opacity: 1; }\\n  to   { opacity: .4; }\\n}\\n.scintilla { animation: pulsa 1s infinite alternate; }","lang":"css"},{"t":"p","text":{"it":"`@keyframes` definisce i passaggi di un’animazione e `animation` la applica. Rispetta chi chiede meno movimento con la media query `prefers-reduced-motion`.","en":"`@keyframes` defines the steps of an animation and `animation` applies it. Respect those who ask for less motion with the `prefers-reduced-motion` media query."}},{"t":"tip","text":{"it":"Anima `transform` e `opacity`: sono le proprietà più leggere per il browser.","en":"Animate `transform` and `opacity`: they are the lightest properties for the browser."}}]','{"lang":"css","prompt":{"it":"Aggiungi a `.card` una `transition` su `transform` e su `.card:hover` un `transform` a piacere.","en":"Add a `transition` on `transform` to `.card` and any `transform` on `.card:hover`."},"start":".card { background: #ffe8d6; padding: 12px; }","html":"<div class=\\"lista\\">\\n  <div class=\\"card\\">Uno</div>\\n  <div class=\\"card\\">Due</div>\\n  <div class=\\"card\\">Tre</div>\\n</div>","checks":[{"re":"transition\\\\s*:[^;}]*transform","label":{"it":"C’è la transizione","en":"The transition is there"}},{"re":"\\\\.card:hover\\\\s*\\\\{[^}]*transform\\\\s*:","label":{"it":"C’è il `transform` su hover","en":"There is a `transform` on hover"}}],"hint":".card { transition: transform .2s; }\\n.card:hover { transform: scale(1.05); }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','pseudo',6,3,'published','{"it":"Pseudo-elementi","en":"Pseudo-elements"}','[{"t":"p","text":{"it":"`::before` e `::after` creano un elemento finto dentro quello scelto, senza toccare l’HTML. Hanno sempre bisogno di `content`.","en":"`::before` and `::after` create a fake element inside the chosen one, without touching the HTML. They always need `content`."}},{"t":"code","code":".nuovo::before {\\n  content: \\"★ \\";\\n  color: gold;\\n}\\nli:nth-child(odd) { background: #eee; }\\np:first-child { font-weight: 700; }","lang":"css"},{"t":"p","text":{"it":"Le pseudo-classi strutturali come `:nth-child()` scelgono gli elementi in base alla posizione: `odd`, `even` o una formula.","en":"Structural pseudo-classes like `:nth-child()` pick elements by position: `odd`, `even` or a formula."}}]','{"lang":"css","prompt":{"it":"Aggiungi prima di `.nota` il testo `\\"→ \\"` con `::before`.","en":"Add the text `\\"→ \\"` before `.nota` using `::before`."},"start":"","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"re":"\\\\.nota::before","label":{"it":"Usi `.nota::before`","en":"You use `.nota::before`"}},{"re":"content\\\\s*:","label":{"it":"C’è `content`","en":"`content` is there"}}],"hint":".nota::before {\\n  content: \\"→ \\";\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','modern',7,3,'published','{"it":"CSS moderno","en":"Modern CSS"}','[{"t":"p","text":{"it":"Il CSS di oggi sa annidare le regole, scegliere un genitore con `:has()` e adattare un componente al suo contenitore con le **container query**.","en":"Today’s CSS can nest rules, pick a parent with `:has()` and adapt a component to its container with **container queries**."}},{"t":"code","code":".card {\\n  container-type: inline-size;\\n  &:hover { outline: 2px solid; }\\n}\\n.card:has(img) { padding: 0; }\\n@container (min-width: 400px) {\\n  .titolo { font-size: 2rem; }\\n}","lang":"css"},{"t":"p","text":{"it":"`:has()` è il «selettore genitore» atteso per anni: sceglie un elemento in base a ciò che contiene.","en":"`:has()` is the long-awaited “parent selector”: it picks an element by what it contains."}}]','{"lang":"css","prompt":{"it":"Con `:has()`, scrivi la regola `.card:has(img)` con `padding: 0`.","en":"Using `:has()`, write the rule `.card:has(img)` with `padding: 0`."},"start":"","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"re":"\\\\.card:has\\\\(img\\\\)","label":{"it":"Usi `:has(img)`","en":"You use `:has(img)`"}},{"re":"padding\\\\s*:\\\\s*0","label":{"it":"Il padding è 0","en":"The padding is 0"}}],"hint":".card:has(img) {\\n  padding: 0;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-animations','transitions',1,2,'published','{"it":"Transizioni","en":"Transitions"}','[{"t":"p","text":{"it":"Una **transizione** rende graduale un cambiamento. Indichi la proprietà, la durata e, se vuoi, la curva e il ritardo.","en":"A **transition** makes a change gradual. You give the property, the duration and, if you want, the curve and the delay."}},{"t":"code","code":".btn {\\n  background: tomato;\\n  transition: background-color .3s ease, transform .2s;\\n}\\n.btn:hover {\\n  background: gold;\\n  transform: scale(1.05);\\n}","lang":"css"},{"t":"p","text":{"it":"Si scrive sullo stato normale, non su `:hover`: così vale sia all’andata che al ritorno.","en":"It goes on the normal state, not on `:hover`: so it works both ways."}}]','{"lang":"css","prompt":{"it":"Dai a `.btn` una `transition` su `transform` di `.2s`, e su `:hover` un `transform: scale(1.1)`.","en":"Give `.btn` a `transition` on `transform` of `.2s`, and on `:hover` a `transform: scale(1.1)`."},"start":"","html":"<div class=\\"card\\">Una card</div>\\n<button class=\\"btn\\">Inizia</button>\\n<div class=\\"palla\\"></div>","checks":[{"re":"\\\\.btn\\\\s*\\\\{[^}]*transition\\\\s*:\\\\s*transform\\\\s+\\\\.?0?\\\\.2s","label":{"it":"La transizione è giusta","en":"The transition is right"}},{"re":"\\\\.btn:hover\\\\s*\\\\{[^}]*scale\\\\(1\\\\.1\\\\)","label":{"it":"Si ingrandisce al passaggio","en":"It grows on hover"}}],"hint":".btn {\\n  transition: transform .2s;\\n}\\n.btn:hover {\\n  transform: scale(1.1);\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-animations','transforms',2,2,'published','{"it":"Trasformazioni","en":"Transforms"}','[{"t":"p","text":{"it":"`transform` sposta, ruota, ingrandisce e inclina un elemento senza disturbare gli altri. È anche la proprietà più veloce da animare.","en":"`transform` moves, rotates, scales and skews an element without disturbing the others. It is also the fastest property to animate."}},{"t":"code","code":".card {\\n  transform: translateX(20px) rotate(5deg) scale(1.1);\\n  transform-origin: top left;\\n}","lang":"css"},{"t":"p","text":{"it":"L’ordine conta: ogni funzione agisce sul risultato della precedente. `transform-origin` sceglie il punto attorno a cui avviene tutto.","en":"Order matters: each function acts on the result of the previous one. `transform-origin` picks the point everything happens around."}}]','{"lang":"css","prompt":{"it":"Ruota `.card` di `45deg` e spostala di `20px` a destra.","en":"Rotate `.card` by `45deg` and move it `20px` to the right."},"start":".card {\\n\\n}","html":"<div class=\\"card\\">Una card</div>\\n<button class=\\"btn\\">Inizia</button>\\n<div class=\\"palla\\"></div>","checks":[{"re":"rotate\\\\(45deg\\\\)","label":{"it":"Ruota di 45 gradi","en":"It rotates by 45 degrees"}},{"re":"translateX\\\\(20px\\\\)|translate\\\\(20px","label":{"it":"Si sposta di 20px","en":"It moves by 20px"}}],"hint":".card {\\n  transform: translateX(20px) rotate(45deg);\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-animations','keyframes',3,2,'published','{"it":"Keyframes","en":"Keyframes"}','[{"t":"p","text":{"it":"Le transizioni vanno da A a B. Con `@keyframes` disegni una storia a più tappe, che può ripetersi da sola, senza bisogno di un `:hover`.","en":"Transitions go from A to B. With `@keyframes` you draw a story of several stages, which can repeat by itself, with no `:hover` needed."}},{"t":"code","code":"@keyframes rimbalzo {\\n  0%   { transform: translateY(0); }\\n  50%  { transform: translateY(-30px); }\\n  100% { transform: translateY(0); }\\n}\\n.palla {\\n  animation: rimbalzo 1s ease-in-out infinite;\\n}","lang":"css"},{"t":"p","text":{"it":"`animation` riassume nome, durata, curva e ripetizioni. `infinite` non si ferma mai, `alternate` torna indietro ogni due giri.","en":"`animation` sums up name, duration, curve and repeats. `infinite` never stops, `alternate` goes back every second round."}}]','{"lang":"css","prompt":{"it":"Crea `@keyframes pulsa` e applicalo a `.palla` con `animation: pulsa 1s infinite`.","en":"Create `@keyframes pulsa` and apply it to `.palla` with `animation: pulsa 1s infinite`."},"start":"","html":"<div class=\\"card\\">Una card</div>\\n<button class=\\"btn\\">Inizia</button>\\n<div class=\\"palla\\"></div>","checks":[{"re":"@keyframes\\\\s+pulsa","label":{"it":"I keyframes esistono","en":"The keyframes exist"}},{"re":"\\\\.palla\\\\s*\\\\{[^}]*animation\\\\s*:\\\\s*pulsa\\\\s+1s\\\\s+infinite","label":{"it":"La palla pulsa","en":"The ball pulses"}}],"hint":"@keyframes pulsa {\\n  from { opacity: 1; }\\n  to { opacity: .4; }\\n}\\n.palla {\\n  animation: pulsa 1s infinite;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-animations','timing',4,3,'published','{"it":"Tempi e curve","en":"Timing and curves"}','[{"t":"p","text":{"it":"La stessa animazione cambia carattere con la curva: `linear` è meccanica, `ease-out` frena alla fine, `ease-in` parte piano. Con `cubic-bezier()` crei la tua, anche con un rimbalzo.","en":"The same animation changes character with its curve: `linear` is mechanical, `ease-out` brakes at the end, `ease-in` starts slowly. With `cubic-bezier()` you make your own, even with a bounce."}},{"t":"code","code":".card {\\n  animation-name: entra;\\n  animation-duration: .4s;\\n  animation-delay: .1s;\\n  animation-timing-function: cubic-bezier(.3, 1.5, .5, 1);\\n  animation-fill-mode: backwards;\\n}","lang":"css"},{"t":"p","text":{"it":"`animation-fill-mode` decide lo stato prima e dopo: `forwards` mantiene l’ultima tappa, `backwards` applica subito la prima durante il ritardo.","en":"`animation-fill-mode` decides the state before and after: `forwards` keeps the last stage, `backwards` applies the first at once during the delay."}}]','{"lang":"css","prompt":{"it":"Dai a `.card` un `animation-delay` di `.2s` e un `animation-fill-mode` di `forwards`.","en":"Give `.card` an `animation-delay` of `.2s` and an `animation-fill-mode` of `forwards`."},"start":".card {\\n\\n}","html":"<div class=\\"card\\">Una card</div>\\n<button class=\\"btn\\">Inizia</button>\\n<div class=\\"palla\\"></div>","checks":[{"re":"animation-delay\\\\s*:\\\\s*0?\\\\.2s","label":{"it":"Il ritardo è giusto","en":"The delay is right"}},{"re":"animation-fill-mode\\\\s*:\\\\s*forwards","label":{"it":"Mantiene l’ultima tappa","en":"It keeps the last stage"}}],"hint":".card {\\n  animation-delay: .2s;\\n  animation-fill-mode: forwards;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-animations','respect',5,3,'published','{"it":"Prestazioni e rispetto","en":"Performance and respect"}','[{"t":"p","text":{"it":"Anima `transform` e `opacity`: il browser li gestisce senza ricalcolare la pagina. Animare `width` o `top` costa molto di più e può scattare.","en":"Animate `transform` and `opacity`: the browser handles them without recalculating the page. Animating `width` or `top` costs far more and can stutter."}},{"t":"code","code":"@media (prefers-reduced-motion: reduce) {\\n  * {\\n    animation: none !important;\\n    transition: none !important;\\n  }\\n}","lang":"css"},{"t":"p","text":{"it":"Alcune persone stanno male con il movimento: `prefers-reduced-motion` rispetta la loro impostazione di sistema. Un’animazione deve spiegare, non distrarre.","en":"Some people feel ill with movement: `prefers-reduced-motion` respects their system setting. An animation must explain, not distract."}}]','{"lang":"css","prompt":{"it":"Scrivi la media query `prefers-reduced-motion: reduce` che mette `animation: none` su `.palla`.","en":"Write the `prefers-reduced-motion: reduce` media query that sets `animation: none` on `.palla`."},"start":"","html":"<div class=\\"card\\">Una card</div>\\n<button class=\\"btn\\">Inizia</button>\\n<div class=\\"palla\\"></div>","checks":[{"re":"@media\\\\s*\\\\(prefers-reduced-motion:\\\\s*reduce\\\\)","label":{"it":"La media query è giusta","en":"The media query is right"}},{"re":"\\\\.palla\\\\s*\\\\{[^}]*animation\\\\s*:\\\\s*none","label":{"it":"L’animazione si ferma","en":"The animation stops"}}],"hint":"@media (prefers-reduced-motion: reduce) {\\n  .palla {\\n    animation: none;\\n  }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','intro',1,2,'published','{"it":"Variabili e compilazione","en":"Variables and compilation"}','[{"t":"p","text":{"it":"SCSS è una sintassi di **Sass**, un preprocessore: scrivi in `.scss` e un compilatore produce il normale `.css` che il browser legge. Ogni file CSS valido è anche SCSS valido.","en":"SCSS is a syntax of **Sass**, a preprocessor: you write `.scss` and a compiler produces the normal `.css` the browser reads. Every valid CSS file is also valid SCSS."}},{"t":"code","code":"$brand: #E8590C;\\n$spazio: 16px;\\n\\n.card {\\n  color: $brand;\\n  padding: $spazio * 2;\\n}","lang":"scss"},{"t":"p","text":{"it":"Le variabili iniziano con `$` e vengono sostituite durante la compilazione, quindi nel CSS finale non esistono più. Si compila con `sass stile.scss stile.css`.","en":"Variables start with `$` and are replaced during compilation, so they no longer exist in the final CSS. You compile with `sass style.scss style.css`."}},{"t":"tip","text":{"it":"Le variabili `$` non cambiano nel browser: per un tema dal vivo servono le variabili CSS.","en":"`$` variables do not change in the browser: a live theme needs CSS variables."}}]','{"lang":"scss","prompt":{"it":"Dichiara la variabile `$brand` con il valore `#E8590C` e usala come `color` di `.titolo`.","en":"Declare the `$brand` variable with the value `#E8590C` and use it as the `color` of `.titolo`."},"start":"","html":"","checks":[{"re":"\\\\$brand\\\\s*:\\\\s*#e8590c\\\\s*;","label":{"it":"La variabile è dichiarata","en":"The variable is declared"}},{"re":"\\\\.titolo\\\\s*\\\\{[^}]*color\\\\s*:\\\\s*\\\\$brand","label":{"it":"`.titolo` la usa","en":"`.titolo` uses it"}}],"hint":"$brand: #E8590C;\\n.titolo { color: $brand; }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','nesting',2,2,'published','{"it":"Annidamento e parent selector","en":"Nesting and the parent selector"}','[{"t":"p","text":{"it":"In SCSS le regole si scrivono una dentro l’altra, seguendo la struttura dell’HTML. Il simbolo `&` indica il selettore genitore.","en":"In SCSS rules are written inside one another, following the structure of the HTML. The `&` symbol stands for the parent selector."}},{"t":"code","code":".menu {\\n  padding: 8px;\\n\\n  a {\\n    color: navy;\\n\\n    &:hover { color: red; }\\n  }\\n\\n  &--aperto { display: block; }\\n}","lang":"scss"},{"t":"p","text":{"it":"Viene compilato in `.menu a`, `.menu a:hover` e `.menu--aperto`. Non annidare troppo: oltre tre livelli i selettori diventano lunghi e difficili da sovrascrivere.","en":"It compiles to `.menu a`, `.menu a:hover` and `.menu--aperto`. Do not nest too deep: past three levels selectors become long and hard to override."}}]','{"lang":"scss","prompt":{"it":"Dentro `.card` annida `a` e, con `&:hover`, cambia il `color` del link.","en":"Inside `.card` nest `a` and, with `&:hover`, change the `color` of the link."},"start":".card {\\n\\n}","html":"","checks":[{"re":"\\\\.card\\\\s*\\\\{[\\\\s\\\\S]*\\\\ba\\\\s*\\\\{","label":{"it":"`a` è annidato in `.card`","en":"`a` is nested in `.card`"}},{"re":"&:hover\\\\s*\\\\{[^}]*color\\\\s*:","label":{"it":"C’è `&:hover` con `color`","en":"There is `&:hover` with `color`"}}],"hint":"a {\\n  &:hover { color: red; }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','mixins',3,2,'published','{"it":"Mixin ed extend","en":"Mixins and extend"}','[{"t":"p","text":{"it":"Un **mixin** è un blocco di regole riutilizzabile, anche con parametri. Si definisce con `@mixin` e si inserisce con `@include`.","en":"A **mixin** is a reusable block of rules, parameters included. It is defined with `@mixin` and inserted with `@include`."}},{"t":"code","code":"@mixin centrato($direzione: row) {\\n  display: flex;\\n  flex-direction: $direzione;\\n  justify-content: center;\\n  align-items: center;\\n}\\n\\n.hero { @include centrato(column); }\\n\\n%bottone { padding: 8px 16px; border-radius: 8px; }\\n.salva { @extend %bottone; }","lang":"scss"},{"t":"p","text":{"it":"`$direzione: row` è un valore predefinito. `@extend` fa condividere lo stesso selettore; `%bottone` è un segnaposto, che non produce CSS finché qualcuno non lo estende.","en":"`$direzione: row` is a default value. `@extend` makes rules share a selector; `%bottone` is a placeholder, which produces no CSS until something extends it."}}]','{"lang":"scss","prompt":{"it":"Definisci il mixin `ombra` con un parametro `$colore` e usalo con `@include` in `.card`.","en":"Define the `ombra` mixin with a `$colore` parameter and use it with `@include` in `.card`."},"start":"","html":"","checks":[{"re":"@mixin\\\\s+ombra\\\\s*\\\\(\\\\s*\\\\$colore","label":{"it":"Il mixin ha il parametro","en":"The mixin has the parameter"}},{"re":"\\\\.card\\\\s*\\\\{[^}]*@include\\\\s+ombra\\\\s*\\\\(","label":{"it":"`.card` lo include","en":"`.card` includes it"}}],"hint":"@mixin ombra($colore) {\\n  box-shadow: 0 2px 8px $colore;\\n}\\n.card { @include ombra(gray); }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','modules',4,3,'published','{"it":"Moduli, mappe e cicli","en":"Modules, maps and loops"}','[{"t":"p","text":{"it":"Il codice si divide in file chiamati **partial**, con il nome che inizia per `_`. Si caricano con `@use`, che dà a ogni file il suo spazio dei nomi. `@import` è deprecato.","en":"Code is split into files called **partials**, whose name starts with `_`. They are loaded with `@use`, which gives each file its own namespace. `@import` is deprecated."}},{"t":"code","code":"// _colori.scss\\n$brand: #E8590C;\\n\\n// stile.scss\\n@use \\"sass:color\\";\\n@use \\"colori\\";\\n\\n.card { color: colori.$brand; }\\n.scuro { color: color.adjust(colori.$brand, $lightness: -10%); }\\n\\n$temi: (ok: green, errore: red);\\n\\n@each $nome, $tinta in $temi {\\n  .avviso-#{$nome} { color: $tinta; }\\n}","lang":"scss"},{"t":"p","text":{"it":"Le mappe sono coppie chiave-valore. `@each` le percorre e `#{ }` inserisce un valore dentro un nome: da poche righe nascono molte classi.","en":"Maps are key-value pairs. `@each` loops over them and `#{ }` puts a value inside a name: a few lines create many classes."}}]','{"lang":"scss","prompt":{"it":"Carica il modulo `colori` con `@use` e scrivi un `@each` sulla mappa `$temi`.","en":"Load the `colori` module with `@use` and write an `@each` over the `$temi` map."},"start":"$temi: (ok: green, errore: red);","html":"","checks":[{"re":"@use\\\\s+[\\"'']colori[\\"'']","label":{"it":"C’è `@use \\"colori\\"`","en":"There is `@use \\"colori\\"`"}},{"re":"@each\\\\s+\\\\$\\\\w+\\\\s*,\\\\s*\\\\$\\\\w+\\\\s+in\\\\s+\\\\$temi","label":{"it":"C’è l’`@each` su `$temi`","en":"There is the `@each` over `$temi`"}}],"hint":"@use \\"colori\\";\\n@each $nome, $tinta in $temi {\\n  .avviso-#{$nome} { color: $tinta; }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','functions',5,3,'published','{"it":"Funzioni e operatori","en":"Functions and operators"}','[{"t":"p","text":{"it":"SCSS sa fare i conti e offre funzioni per i colori. Con `@function` scrivi le tue: restituiscono un valore con `@return`.","en":"SCSS can do maths and has colour functions. With `@function` you write your own: they give back a value with `@return`."}},{"t":"code","code":"@use \\"sass:color\\";\\n@use \\"sass:math\\";\\n\\n@function spazio($n) {\\n  @return $n * 8px;\\n}\\n.card {\\n  padding: spazio(2);\\n  width: math.div(100%, 3);\\n  background: color.adjust(#FF5B2E, $lightness: 20%);\\n}","lang":"scss"},{"t":"p","text":{"it":"Un mixin scrive regole, una funzione restituisce un valore da usare in una proprietà.","en":"A mixin writes rules, a function gives back a value to use in a property."}}]','{"lang":"scss","prompt":{"it":"Scrivi una funzione `doppio($n)` che restituisce `$n * 2`.","en":"Write a function `doppio($n)` that gives back `$n * 2`."},"start":"","html":"","checks":[{"re":"@function\\\\s+doppio\\\\(\\\\$n\\\\)","label":{"it":"Definisci `doppio`","en":"You define `doppio`"}},{"re":"@return\\\\s+\\\\$n\\\\s*\\\\*\\\\s*2","label":{"it":"Restituisci il doppio","en":"You give back the double"}}],"hint":"@function doppio($n) {\\n  @return $n * 2;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','architecture',6,3,'published','{"it":"Organizzare i file","en":"Organising the files"}','[{"t":"p","text":{"it":"In un progetto grande lo stile si divide in **file parziali**, che iniziano con `_`, e un file principale li raccoglie con `@use`.","en":"In a large project style is split into **partial files**, starting with `_`, and a main file gathers them with `@use`."}},{"t":"code","code":"// main.scss\\n@use \\"base/reset\\";\\n@use \\"base/variabili\\";\\n@use \\"componenti/bottoni\\";\\n@use \\"pagine/home\\";","lang":"scss"},{"t":"p","text":{"it":"I file parziali non diventano CSS da soli: finiscono tutti nel file compilato. Così il browser scarica un solo foglio di stile.","en":"Partial files do not become CSS on their own: they all end up in the compiled file. So the browser downloads one stylesheet."}}]','{"lang":"scss","prompt":{"it":"In `main.scss`, importa con `@use` i parziali `reset` e `bottoni`.","en":"In `main.scss`, load the partials `reset` and `bottoni` with `@use`."},"start":"// main.scss","html":"","checks":[{"re":"@use\\\\s+\\"reset\\"","label":{"it":"Carichi `reset`","en":"You load `reset`"}},{"re":"@use\\\\s+\\"bottoni\\"","label":{"it":"Carichi `bottoni`","en":"You load `bottoni`"}}],"hint":"@use \\"reset\\";\\n@use \\"bottoni\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sass','indented',1,2,'published','{"it":"La sintassi indentata","en":"The indented syntax"}','[{"t":"p","text":{"it":"I file `.sass` usano lo stesso linguaggio di SCSS ma senza `{ }` e senza `;`. I blocchi sono definiti dal **rientro**, un po’ come in Python.","en":"`.sass` files use the same language as SCSS but with no `{ }` and no `;`. Blocks are defined by **indentation**, a bit like Python."}},{"t":"code","code":"$brand: #E8590C\\n\\n.card\\n  color: $brand\\n  padding: 16px\\n\\n  a\\n    color: navy\\n\\n    &:hover\\n      color: red","lang":"sass"},{"t":"p","text":{"it":"Ogni dichiarazione sta su una riga e il rientro deve essere coerente in tutto il file. Il risultato compilato è identico a quello di SCSS: cambia solo come si scrive.","en":"Each declaration sits on its own line and the indentation must be consistent across the file. The compiled result is identical to SCSS: only the writing changes."}}]','{"lang":"sass","prompt":{"it":"Riscrivi in Sass: `.titolo { color: red; }`","en":"Rewrite in Sass: `.titolo { color: red; }`"},"start":"","html":"","checks":[{"re":"^\\\\s*\\\\.titolo\\\\s*$","label":{"it":"Il selettore sta da solo sulla riga","en":"The selector stands alone on its line"}},{"re":"^[ \\\\t]+color:\\\\s*red\\\\s*$","label":{"it":"`color: red` è rientrato, senza `;`","en":"`color: red` is indented, with no `;`"}}],"hint":".titolo\\n  color: red"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sass','mixins',2,2,'published','{"it":"Mixin con = e +","en":"Mixins with = and +"}','[{"t":"p","text":{"it":"La sintassi indentata ha una scorciatoia: `=` definisce un mixin, come `@mixin`, e `+` lo include, come `@include`.","en":"The indented syntax has a shortcut: `=` defines a mixin, like `@mixin`, and `+` includes it, like `@include`."}},{"t":"code","code":"=centrato($direzione: row)\\n  display: flex\\n  flex-direction: $direzione\\n  justify-content: center\\n\\n.hero\\n  +centrato(column)","lang":"sass"},{"t":"p","text":{"it":"Anche le forme lunghe `@mixin` e `@include` funzionano, ma le scorciatoie sono l’uso più comune. Le altre regole, come `@use`, `@each` e `@if`, si scrivono come in SCSS, senza graffe.","en":"The long forms `@mixin` and `@include` work too, but the shortcuts are the more common use. Other rules, such as `@use`, `@each` and `@if`, are written as in SCSS, with no braces."}}]','{"lang":"sass","prompt":{"it":"Definisci con `=` il mixin `tondo` con `border-radius: 50%` e includilo con `+` in `.avatar`.","en":"Define the `tondo` mixin with `=`, with `border-radius: 50%`, and include it with `+` in `.avatar`."},"start":"","html":"","checks":[{"re":"^=tondo\\\\b","label":{"it":"Il mixin è definito con `=`","en":"The mixin is defined with `=`"}},{"re":"^[ \\\\t]+border-radius:\\\\s*50%\\\\s*$","label":{"it":"Ha `border-radius: 50%`","en":"It has `border-radius: 50%`"}},{"re":"^\\\\.avatar\\\\s*\\\\n[ \\\\t]+\\\\+tondo","label":{"it":"`.avatar` lo include con `+`","en":"`.avatar` includes it with `+`"}}],"hint":"=tondo\\n  border-radius: 50%\\n\\n.avatar\\n  +tondo"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sass','choose',3,2,'published','{"it":"Sass o SCSS?","en":"Sass or SCSS?"}','[{"t":"p","text":{"it":"I due formati fanno le stesse cose. SCSS è il più diffuso perché è un’estensione del CSS: si copia del CSS esistente e funziona. Sass è più sintetico, ma non accetta il CSS così com’è.","en":"The two formats do the same things. SCSS is more common because it extends CSS: paste existing CSS and it works. Sass is more concise, but it does not accept CSS as it is."}},{"t":"code","code":"sass --watch stile.sass:stile.css\\nsass-convert stile.scss stile.sass   # vecchi strumenti\\nsass --style=compressed stile.scss stile.css","lang":"bash"},{"t":"p","text":{"it":"Con `--watch` il compilatore ricompila a ogni salvataggio; con `--style=compressed` il CSS esce minimizzato per la pubblicazione. In un progetto si sceglie un solo formato, anche se Sass può caricare file di entrambi i tipi.","en":"With `--watch` the compiler rebuilds on every save; with `--style=compressed` the CSS comes out minified for publishing. In a project you pick one format, although Sass can load files of both kinds."}},{"t":"tip","text":{"it":"In un team conviene SCSS, salvo una preferenza chiara: chi conosce il CSS lo legge subito.","en":"In a team SCSS is the safer choice, unless there is a clear preference: anyone who knows CSS reads it at once."}}]',NULL);
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sass','maps-sass',4,3,'published','{"it":"Variabili e mappe in Sass","en":"Variables and maps in Sass"}','[{"t":"p","text":{"it":"Nella sintassi indentata variabili e mappe funzionano come in SCSS: cambiano solo graffe e punti e virgola.","en":"In the indented syntax variables and maps work as in SCSS: only braces and semicolons change."}},{"t":"code","code":"$temi: (ok: green, ko: red)\\n\\n@each $nome, $tinta in $temi\\n  .avviso-#{$nome}\\n    color: $tinta","lang":"sass"},{"t":"p","text":{"it":"Una mappa si scrive su una riga sola: nella sintassi indentata andare a capo ha un significato.","en":"A map is written on one line: in the indented syntax a line break has a meaning."}}]','{"lang":"sass","prompt":{"it":"Definisci `$brand: orange` e usalo come `color` di `.titolo`.","en":"Define `$brand: orange` and use it as the `color` of `.titolo`."},"start":"","html":"","checks":[{"re":"^\\\\$brand:\\\\s*orange","label":{"it":"Definisci `$brand`","en":"You define `$brand`"}},{"re":"^\\\\s+color:\\\\s*\\\\$brand\\\\s*$","label":{"it":"Lo usi, senza punto e virgola","en":"You use it, with no semicolon"}}],"hint":"$brand: orange\\n.titolo\\n  color: $brand"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sass','convert',5,3,'published','{"it":"Da SCSS a Sass","en":"From SCSS to Sass"}','[{"t":"p","text":{"it":"Passare da una sintassi all’altra è meccanico: togli graffe e punti e virgola, usa `=` al posto di `@mixin` e `+` al posto di `@include` se vuoi la forma breve.","en":"Moving between syntaxes is mechanical: remove braces and semicolons, use `=` for `@mixin` and `+` for `@include` if you want the short form."}},{"t":"code","code":"// SCSS\\n.card { color: red; .titolo { margin: 0; } }\\n\\n// Sass\\n.card\\n  color: red\\n  .titolo\\n    margin: 0","lang":"sass"},{"t":"p","text":{"it":"Il comando `sass-convert` lo faceva da solo in passato: oggi conviene scegliere una sintassi e restare coerenti.","en":"The `sass-convert` command used to do it for you: today it is best to pick one syntax and stay consistent."}}]','{"lang":"sass","prompt":{"it":"Riscrivi in Sass: `.box { color: red; }`","en":"Rewrite in Sass: `.box { color: red; }`"},"start":"","html":"","checks":[{"re":"^\\\\.box\\\\s*$","label":{"it":"Il selettore è senza graffa","en":"The selector has no brace"}},{"re":"^\\\\s+color:\\\\s*red\\\\s*$","label":{"it":"La proprietà è rientrata e senza `;`","en":"The property is indented with no `;`"}}],"hint":".box\\n  color: red"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','variables',1,1,'published','{"it":"Variabili e tipi","en":"Variables and types"}','[{"t":"p","text":{"it":"JavaScript dà vita alle pagine. Una **variabile** è una scatola con un nome: `const` non si può riassegnare, `let` sì. I tipi di base sono numeri, stringhe, booleani, `null` e `undefined`.","en":"JavaScript brings pages to life. A **variable** is a box with a name: `const` cannot be reassigned, `let` can. The basic types are numbers, strings, booleans, `null` and `undefined`."}},{"t":"code","code":"const nome = \\"Sav\\";\\nlet punti = 10;\\npunti = punti + 5;\\nconsole.log(nome, punti); // Sav 15\\nconsole.log(typeof punti); // \\"number\\"","lang":"js"},{"t":"tip","text":{"it":"Usa `const` di partenza e passa a `let` solo se il valore deve cambiare.","en":"Start with `const` and move to `let` only if the value must change."}}]','{"lang":"js","prompt":{"it":"Crea una costante `nome` con il tuo nome e una variabile `punti` con `let`, uguale a `0`.","en":"Create a constant `nome` with your name and a variable `punti` with `let`, equal to `0`."},"start":"","html":"","checks":[{"re":"const\\\\s+nome\\\\s*=\\\\s*[\\"'']","label":{"it":"`nome` è una costante stringa","en":"`nome` is a string constant"}},{"re":"let\\\\s+punti\\\\s*=\\\\s*0","label":{"it":"`punti` parte da 0","en":"`punti` starts from 0"}}],"hint":"const nome = \\"Sav\\";\\nlet punti = 0;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','operators',2,1,'published','{"it":"Operatori e stringhe","en":"Operators and strings"}','[{"t":"p","text":{"it":"Con i numeri usi `+ - * / %`. Il `%` dà il resto di una divisione. Per i confronti usa sempre `===`, che controlla anche il tipo. Le stringhe si uniscono con i **template literal**, tra apici inversi.","en":"With numbers you use `+ - * / %`. `%` gives the remainder of a division. For comparisons always use `===`, which also checks the type. Strings join with **template literals**, between backticks."}},{"t":"code","code":"const a = 7 % 2;      // 1\\n5 === \\"5\\";            // false\\n5 == \\"5\\";             // true: da evitare\\nconst nome = \\"Sav\\";\\nconst saluto = `Ciao ${nome}!`;\\nsaluto.length;        // 9\\nsaluto.toUpperCase(); // \\"CIAO SAV!\\"","lang":"js"},{"t":"p","text":{"it":"`&&` significa «e», `||` «oppure», `!` «non».","en":"`&&` means “and”, `||` “or”, `!` “not”."}}]','{"lang":"js","prompt":{"it":"Crea `saluto` con un template literal che contenga `${nome}`.","en":"Create `saluto` with a template literal containing `${nome}`."},"start":"const nome = \\"Sav\\";","html":"","checks":[{"re":"saluto\\\\s*=\\\\s*`[^`]*\\\\$\\\\{nome\\\\}[^`]*`","label":{"it":"Il template contiene `${nome}`","en":"The template contains `${nome}`"}}],"hint":"const nome = \\"Sav\\";\\nconst saluto = `Ciao ${nome}!`;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','conditions',3,1,'published','{"it":"Condizioni","en":"Conditions"}','[{"t":"p","text":{"it":"`if` esegue un blocco solo se una condizione è vera. `else` copre il caso contrario. Il **ternario** è la versione breve, utile per scegliere un valore.","en":"`if` runs a block only if a condition is true. `else` covers the opposite case. The **ternary** is the short version, handy for choosing a value."}},{"t":"code","code":"if (punti >= 100) {\\n  console.log(\\"Grande!\\");\\n} else if (punti >= 50) {\\n  console.log(\\"Bene\\");\\n} else {\\n  console.log(\\"Continua\\");\\n}\\nconst stato = punti > 0 ? \\"attivo\\" : \\"fermo\\";","lang":"js"},{"t":"p","text":{"it":"Alcuni valori contano come falsi: `0`, `\\"\\"`, `null`, `undefined`, `NaN`, `false`. Tutti gli altri contano come veri.","en":"Some values count as false: `0`, `\\"\\"`, `null`, `undefined`, `NaN`, `false`. All the others count as true."}}]','{"lang":"js","prompt":{"it":"Scrivi un `if` che con `punti >= 10` assegna `premio = true`, altrimenti `premio = false`.","en":"Write an `if` that with `punti >= 10` sets `premio = true`, otherwise `premio = false`."},"start":"let premio;","html":"","checks":[{"re":"if\\\\s*\\\\(\\\\s*punti\\\\s*>=\\\\s*10\\\\s*\\\\)","label":{"it":"La condizione è giusta","en":"The condition is right"}},{"re":"else","label":{"it":"C’è `else`","en":"`else` is there"}},{"re":"premio\\\\s*=\\\\s*true","label":{"it":"Assegni true","en":"You set true"}}],"hint":"let premio;\\nif (punti >= 10) {\\n  premio = true;\\n} else {\\n  premio = false;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','loops',4,1,'published','{"it":"Cicli","en":"Loops"}','[{"t":"p","text":{"it":"Un **ciclo** ripete un blocco. `for` conta, `while` continua finché una condizione è vera, `for…of` scorre gli elementi di una lista.","en":"A **loop** repeats a block. `for` counts, `while` goes on while a condition is true, `for…of` walks the items of a list."}},{"t":"code","code":"for (let i = 0; i < 3; i++) {\\n  console.log(i); // 0, 1, 2\\n}\\nlet n = 3;\\nwhile (n > 0) {\\n  n--;\\n}\\nfor (const nome of [\\"Ada\\", \\"Sav\\"]) {\\n  console.log(nome);\\n}","lang":"js"},{"t":"p","text":{"it":"`break` esce dal ciclo, `continue` salta al giro dopo. Attenzione ai cicli che non finiscono mai: bloccano la pagina.","en":"`break` leaves the loop, `continue` jumps to the next round. Watch out for loops that never end: they freeze the page."}}]','{"lang":"js","prompt":{"it":"Scrivi un ciclo `for` che somma in `totale` i numeri da 1 a 5.","en":"Write a `for` loop that adds the numbers from 1 to 5 into `totale`."},"start":"let totale = 0;","html":"","checks":[{"re":"for\\\\s*\\\\(\\\\s*let\\\\s+i\\\\s*=\\\\s*1\\\\s*;\\\\s*i\\\\s*<=\\\\s*5\\\\s*;\\\\s*i\\\\+\\\\+\\\\s*\\\\)","label":{"it":"Il ciclo va da 1 a 5","en":"The loop goes from 1 to 5"}},{"re":"totale\\\\s*(\\\\+=\\\\s*i|=\\\\s*totale\\\\s*\\\\+\\\\s*i)","label":{"it":"Sommi `i` a `totale`","en":"You add `i` to `totale`"}}],"hint":"let totale = 0;\\nfor (let i = 1; i <= 5; i++) {\\n  totale += i;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','functions',5,2,'published','{"it":"Funzioni","en":"Functions"}','[{"t":"p","text":{"it":"Una **funzione** è un pezzo di codice con un nome, da riusare. Riceve dei **parametri** e con `return` restituisce un risultato. Le **arrow function** sono la forma breve.","en":"A **function** is a named piece of code to reuse. It takes **parameters** and with `return` gives back a result. **Arrow functions** are the short form."}},{"t":"code","code":"function somma(a, b) {\\n  return a + b;\\n}\\nconst doppio = n => n * 2;\\nconst saluta = (nome = \\"amico\\") => `Ciao ${nome}`;\\n\\nsomma(2, 3);   // 5\\ndoppio(4);     // 8\\nsaluta();      // \\"Ciao amico\\"","lang":"js"},{"t":"p","text":{"it":"Dopo `return` la funzione finisce. Senza `return` restituisce `undefined`. Le variabili create dentro non si vedono da fuori.","en":"After `return` the function ends. Without `return` it gives back `undefined`. Variables created inside cannot be seen from outside."}}]','{"lang":"js","prompt":{"it":"Scrivi una funzione `area(b, h)` che restituisce `b * h`.","en":"Write a function `area(b, h)` that gives back `b * h`."},"start":"","html":"","checks":[{"re":"(function\\\\s+area\\\\s*\\\\(\\\\s*b\\\\s*,\\\\s*h\\\\s*\\\\)|area\\\\s*=\\\\s*\\\\(\\\\s*b\\\\s*,\\\\s*h\\\\s*\\\\)\\\\s*=>)","label":{"it":"`area` riceve `b` e `h`","en":"`area` takes `b` and `h`"}},{"re":"(return\\\\s+b\\\\s*\\\\*\\\\s*h|=>\\\\s*b\\\\s*\\\\*\\\\s*h)","label":{"it":"Restituisce il prodotto","en":"It gives back the product"}}],"hint":"function area(b, h) {\\n  return b * h;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','arrays',6,2,'published','{"it":"Array","en":"Arrays"}','[{"t":"p","text":{"it":"Un **array** è una lista ordinata. Si parte a contare da `0`. `push` aggiunge in fondo, `pop` toglie l’ultimo, `length` dice quanti sono.","en":"An **array** is an ordered list. Counting starts at `0`. `push` adds to the end, `pop` removes the last, `length` says how many."}},{"t":"code","code":"const corsi = [\\"HTML\\", \\"CSS\\"];\\ncorsi.push(\\"JS\\");\\ncorsi[0];        // \\"HTML\\"\\ncorsi.length;    // 3\\ncorsi.includes(\\"CSS\\"); // true\\ncorsi.indexOf(\\"JS\\");   // 2","lang":"js"},{"t":"p","text":{"it":"Anche se `const`, un array può cambiare contenuto: `const` blocca solo la riassegnazione della variabile.","en":"Even if `const`, an array can change its content: `const` only blocks reassigning the variable."}}]','{"lang":"js","prompt":{"it":"Crea l’array `frutti` con due elementi e aggiungine un terzo con `push`.","en":"Create the array `frutti` with two items and add a third with `push`."},"start":"","html":"","checks":[{"re":"frutti\\\\s*=\\\\s*\\\\[[^\\\\]]+,[^\\\\]]+\\\\]","label":{"it":"L’array ha due elementi","en":"The array has two items"}},{"re":"frutti\\\\.push\\\\(","label":{"it":"Usi `push`","en":"You use `push`"}}],"hint":"const frutti = [\\"mela\\", \\"pera\\"];\\nfrutti.push(\\"uva\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','objects',7,2,'published','{"it":"Oggetti","en":"Objects"}','[{"t":"p","text":{"it":"Un **oggetto** raggruppa dati con un nome: coppie chiave e valore. Si legge con il punto, oppure con le parentesi quadre se il nome è in una variabile.","en":"An **object** groups named data: key and value pairs. You read it with a dot, or with square brackets if the name is in a variable."}},{"t":"code","code":"const utente = {\\n  nome: \\"Sav\\",\\n  punti: 10,\\n  saluta() {\\n    return `Ciao ${this.nome}`;\\n  },\\n};\\nutente.punti = 20;\\nutente[\\"nome\\"];   // \\"Sav\\"\\nObject.keys(utente); // [\\"nome\\", \\"punti\\", \\"saluta\\"]","lang":"js"},{"t":"p","text":{"it":"Una funzione dentro un oggetto si chiama **metodo**: con `this` accede all’oggetto stesso.","en":"A function inside an object is called a **method**: with `this` it reaches the object itself."}}]','{"lang":"js","prompt":{"it":"Crea l’oggetto `libro` con `titolo` e `pagine`, poi cambia `pagine` a `100`.","en":"Create the object `libro` with `titolo` and `pagine`, then change `pagine` to `100`."},"start":"","html":"","checks":[{"re":"libro\\\\s*=\\\\s*\\\\{[\\\\s\\\\S]*titolo\\\\s*:[\\\\s\\\\S]*pagine\\\\s*:","label":{"it":"L’oggetto ha le due chiavi","en":"The object has both keys"}},{"re":"libro\\\\.pagine\\\\s*=\\\\s*100","label":{"it":"Cambi `pagine`","en":"You change `pagine`"}}],"hint":"const libro = { titolo: \\"Fucina\\", pagine: 50 };\\nlibro.pagine = 100;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','dom',1,2,'published','{"it":"Il DOM","en":"The DOM"}','[{"t":"p","text":{"it":"Il **DOM** è la pagina vista da JavaScript: un albero di elementi. `querySelector` ne trova uno con un selettore CSS, poi puoi cambiarne testo, classi e attributi.","en":"The **DOM** is the page as JavaScript sees it: a tree of elements. `querySelector` finds one with a CSS selector, then you can change its text, classes and attributes."}},{"t":"code","code":"const titolo = document.querySelector(\\"h1\\");\\ntitolo.textContent = \\"Ciao!\\";\\ntitolo.classList.add(\\"grande\\");\\nconst voci = document.querySelectorAll(\\"li\\");\\nconst nuovo = document.createElement(\\"p\\");\\nnuovo.textContent = \\"Nuovo\\";\\ndocument.body.append(nuovo);","lang":"js"},{"t":"tip","text":{"it":"Usa `textContent` per i testi degli utenti: `innerHTML` può eseguire codice nascosto.","en":"Use `textContent` for user text: `innerHTML` can run hidden code."}}]','{"lang":"js","prompt":{"it":"Trova `h1` con `querySelector` e cambiane il testo in `Fucina`.","en":"Find `h1` with `querySelector` and change its text to `Fucina`."},"start":"","html":"","checks":[{"re":"document\\\\.querySelector\\\\(\\\\s*[\\"'']h1[\\"'']\\\\s*\\\\)","label":{"it":"Trovi il titolo","en":"You find the heading"}},{"re":"\\\\.textContent\\\\s*=\\\\s*[\\"'']Fucina[\\"'']","label":{"it":"Cambi il testo","en":"You change the text"}}],"hint":"const t = document.querySelector(\\"h1\\");\\nt.textContent = \\"Fucina\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','events',2,2,'published','{"it":"Eventi","en":"Events"}','[{"t":"p","text":{"it":"Un **evento** è qualcosa che succede: un click, un tasto, un invio. Con `addEventListener` dici che cosa fare quando accade.","en":"An **event** is something that happens: a click, a key, a submit. With `addEventListener` you say what to do when it occurs."}},{"t":"code","code":"const btn = document.querySelector(\\"button\\");\\nbtn.addEventListener(\\"click\\", () => {\\n  btn.textContent = \\"Fatto!\\";\\n});\\n\\nconst form = document.querySelector(\\"form\\");\\nform.addEventListener(\\"submit\\", e => {\\n  e.preventDefault();\\n  console.log(new FormData(form).get(\\"email\\"));\\n});","lang":"js"},{"t":"p","text":{"it":"La funzione riceve un oggetto evento: `e.target` è l’elemento coinvolto, `e.preventDefault()` ferma il comportamento normale, come il ricaricamento di un modulo.","en":"The function gets an event object: `e.target` is the element involved, `e.preventDefault()` stops the normal behaviour, like a form reloading."}}]','{"lang":"js","prompt":{"it":"Aggiungi a `btn` un ascoltatore di `click` che esegue `conta++`.","en":"Add to `btn` a `click` listener that runs `conta++`."},"start":"let conta = 0;","html":"","checks":[{"re":"btn\\\\.addEventListener\\\\(\\\\s*[\\"'']click[\\"'']","label":{"it":"Ascolti il click","en":"You listen to the click"}},{"re":"conta\\\\+\\\\+","label":{"it":"Il contatore sale","en":"The counter goes up"}}],"hint":"let conta = 0;\\nbtn.addEventListener(\\"click\\", () => {\\n  conta++;\\n});"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','array-methods',3,2,'published','{"it":"map, filter e reduce","en":"map, filter and reduce"}','[{"t":"p","text":{"it":"Gli array hanno metodi potenti. `map` trasforma ogni elemento, `filter` tiene quelli che superano una prova, `find` restituisce il primo adatto, `reduce` riduce tutto a un valore.","en":"Arrays have powerful methods. `map` transforms each item, `filter` keeps those passing a test, `find` gives back the first match, `reduce` boils it all down to one value."}},{"t":"code","code":"const n = [1, 2, 3, 4];\\nn.map(x => x * 2);        // [2, 4, 6, 8]\\nn.filter(x => x % 2 === 0); // [2, 4]\\nn.find(x => x > 2);       // 3\\nn.reduce((a, x) => a + x, 0); // 10\\nn.some(x => x > 3);       // true","lang":"js"},{"t":"p","text":{"it":"`map` e `filter` creano un nuovo array e non toccano l’originale. Si possono concatenare.","en":"`map` and `filter` create a new array and leave the original alone. They can be chained."}}]','{"lang":"js","prompt":{"it":"Da `prezzi`, crea `cari` con `filter` tenendo quelli sopra `10`.","en":"From `prezzi`, create `cari` with `filter`, keeping those above `10`."},"start":"const prezzi = [5, 12, 30];","html":"","checks":[{"re":"cari\\\\s*=\\\\s*prezzi\\\\.filter\\\\(","label":{"it":"Usi `filter`","en":"You use `filter`"}},{"re":">\\\\s*10","label":{"it":"Il limite è 10","en":"The limit is 10"}}],"hint":"const prezzi = [5, 12, 30];\\nconst cari = prezzi.filter(p => p > 10);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','modern-syntax',4,3,'published','{"it":"Sintassi moderna","en":"Modern syntax"}','[{"t":"p","text":{"it":"La **destrutturazione** estrae valori in un colpo. Lo **spread** `...` copia e unisce. `?.` legge in sicurezza una proprietà che può mancare, `??` dà un valore di riserva.","en":"**Destructuring** pulls out values in one go. **Spread** `...` copies and merges. `?.` safely reads a property that may be missing, `??` gives a fallback value."}},{"t":"code","code":"const utente = { nome: \\"Sav\\", punti: 10 };\\nconst { nome, punti } = utente;\\nconst [primo, secondo] = [\\"a\\", \\"b\\"];\\n\\nconst copia = { ...utente, punti: 20 };\\nconst tutti = [...listaA, ...listaB];\\n\\nutente.indirizzo?.via;     // undefined, nessun errore\\nconst n = utente.vite ?? 3; // 3","lang":"js"},{"t":"p","text":{"it":"`??` scatta solo con `null` e `undefined`: a differenza di `||` non scarta `0` e `\\"\\"`.","en":"`??` only fires on `null` and `undefined`: unlike `||` it does not discard `0` and `\\"\\"`."}}]','{"lang":"js","prompt":{"it":"Estrai `titolo` da `libro` con la destrutturazione.","en":"Pull `titolo` out of `libro` with destructuring."},"start":"const libro = { titolo: \\"Fucina\\", pagine: 50 };","html":"","checks":[{"re":"const\\\\s*\\\\{\\\\s*titolo[^}]*\\\\}\\\\s*=\\\\s*libro","label":{"it":"Destrutturi `libro`","en":"You destructure `libro`"}}],"hint":"const libro = { titolo: \\"Fucina\\", pagine: 50 };\\nconst { titolo } = libro;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','json-storage',5,3,'published','{"it":"JSON e localStorage","en":"JSON and localStorage"}','[{"t":"p","text":{"it":"**JSON** è il formato di testo con cui viaggiano i dati. `JSON.stringify` trasforma un valore in testo, `JSON.parse` fa il contrario. `localStorage` conserva testi nel browser, anche dopo la chiusura.","en":"**JSON** is the text format data travels in. `JSON.stringify` turns a value into text, `JSON.parse` does the opposite. `localStorage` keeps text in the browser, even after closing."}},{"t":"code","code":"const dati = { punti: 10 };\\nconst testo = JSON.stringify(dati); // ''{\\"punti\\":10}''\\nlocalStorage.setItem(\\"gioco\\", testo);\\n\\nconst salvato = localStorage.getItem(\\"gioco\\");\\nconst letto = salvato ? JSON.parse(salvato) : null;","lang":"js"},{"t":"tip","text":{"it":"`localStorage` è visibile a tutti gli script della pagina: mai password o token.","en":"`localStorage` is visible to all the scripts on the page: never passwords or tokens."}}]','{"lang":"js","prompt":{"it":"Salva `dati` in `localStorage` con la chiave `gioco`, usando `JSON.stringify`.","en":"Save `dati` in `localStorage` with the key `gioco`, using `JSON.stringify`."},"start":"const dati = { punti: 10 };","html":"","checks":[{"re":"localStorage\\\\.setItem\\\\(\\\\s*[\\"'']gioco[\\"'']","label":{"it":"Usi la chiave giusta","en":"You use the right key"}},{"re":"JSON\\\\.stringify\\\\(\\\\s*dati\\\\s*\\\\)","label":{"it":"Converti in testo","en":"You convert to text"}}],"hint":"const dati = { punti: 10 };\\nlocalStorage.setItem(\\"gioco\\", JSON.stringify(dati));"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','dates-errors',6,3,'published','{"it":"Date, timer ed errori","en":"Dates, timers and errors"}','[{"t":"p","text":{"it":"`Date` lavora con date e orari. `setTimeout` esegue qualcosa dopo un’attesa, `setInterval` a intervalli. `try…catch` gestisce gli errori senza fermare tutto il programma.","en":"`Date` works with dates and times. `setTimeout` runs something after a wait, `setInterval` at intervals. `try…catch` handles errors without stopping the whole program."}},{"t":"code","code":"const ora = new Date();\\nora.getFullYear();\\n\\nsetTimeout(() => console.log(\\"Dopo 1 secondo\\"), 1000);\\nconst id = setInterval(tick, 500);\\nclearInterval(id);\\n\\ntry {\\n  JSON.parse(\\"rotto\\");\\n} catch (errore) {\\n  console.log(\\"Dati non validi\\");\\n}","lang":"js"},{"t":"p","text":{"it":"I tempi si indicano in millisecondi. Conserva l’id di `setInterval` per poterlo fermare.","en":"Times are given in milliseconds. Keep the id of `setInterval` so you can stop it."}}]','{"lang":"js","prompt":{"it":"Con `setTimeout`, esegui `fine()` dopo `2000` millisecondi.","en":"With `setTimeout`, run `fine()` after `2000` milliseconds."},"start":"","html":"","checks":[{"re":"setTimeout\\\\(","label":{"it":"Usi `setTimeout`","en":"You use `setTimeout`"}},{"re":"fine","label":{"it":"Chiami `fine`","en":"You call `fine`"}},{"re":"2000","label":{"it":"Aspetti 2 secondi","en":"You wait 2 seconds"}}],"hint":"setTimeout(fine, 2000);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','promises',1,2,'published','{"it":"Promise","en":"Promises"}','[{"t":"p","text":{"it":"Una **Promise** rappresenta un risultato che arriverà: può riuscire o fallire. Con `then` dici che cosa fare col valore, con `catch` come gestire l’errore.","en":"A **Promise** stands for a result yet to come: it can succeed or fail. With `then` you say what to do with the value, with `catch` how to handle the error."}},{"t":"code","code":"function attendi(ms) {\\n  return new Promise(resolve => setTimeout(resolve, ms));\\n}\\nattendi(500)\\n  .then(() => \\"fatto\\")\\n  .then(testo => console.log(testo))\\n  .catch(errore => console.error(errore))\\n  .finally(() => console.log(\\"fine\\"));\\n\\nPromise.all([a(), b()]).then(([x, y]) => usa(x, y));","lang":"js"},{"t":"p","text":{"it":"`Promise.all` aspetta più operazioni insieme e fallisce se ne fallisce una. Ogni `then` riceve quello restituito dal precedente.","en":"`Promise.all` waits for several operations together and fails if one fails. Each `then` gets what the previous one gave back."}}]','{"lang":"js","prompt":{"it":"Sulla promise `carica()`, stampa il risultato con `then` e gestisci gli errori con `catch`.","en":"On the promise `carica()`, print the result with `then` and handle errors with `catch`."},"start":"","html":"","checks":[{"re":"carica\\\\(\\\\)\\\\s*\\\\.then\\\\(","label":{"it":"Usi `then`","en":"You use `then`"}},{"re":"\\\\.catch\\\\(","label":{"it":"Usi `catch`","en":"You use `catch`"}}],"hint":"carica()\\n  .then(r => console.log(r))\\n  .catch(e => console.error(e));"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','async',2,2,'published','{"it":"async e await","en":"async and await"}','[{"t":"p","text":{"it":"`async` e `await` fanno sembrare lineare il codice asincrono. `await` aspetta una Promise senza bloccare la pagina, e si scrive solo dentro una funzione `async`.","en":"`async` and `await` make asynchronous code look linear. `await` waits for a Promise without freezing the page, and goes only inside an `async` function."}},{"t":"code","code":"async function profilo(id) {\\n  try {\\n    const utente = await carica(id);\\n    const punti = await caricaPunti(utente);\\n    return { utente, punti };\\n  } catch (e) {\\n    console.error(e);\\n    return null;\\n  }\\n}\\nconst [a, b] = await Promise.all([x(), y()]);","lang":"js"},{"t":"p","text":{"it":"Una funzione `async` restituisce sempre una Promise. Se due operazioni non dipendono l’una dall’altra, lanciale insieme con `Promise.all`: è più veloce.","en":"An `async` function always gives back a Promise. If two operations do not depend on each other, start them together with `Promise.all`: it is faster."}}]','{"lang":"js","prompt":{"it":"Scrivi `async function leggi()` che fa `await carica()` e restituisce il risultato.","en":"Write `async function leggi()` that does `await carica()` and gives back the result."},"start":"","html":"","checks":[{"re":"async\\\\s+function\\\\s+leggi\\\\s*\\\\(","label":{"it":"La funzione è `async`","en":"The function is `async`"}},{"re":"await\\\\s+carica\\\\(\\\\)","label":{"it":"Aspetti il risultato","en":"You wait for the result"}},{"re":"return","label":{"it":"Lo restituisci","en":"You give it back"}}],"hint":"async function leggi() {\\n  const r = await carica();\\n  return r;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','fetch',3,2,'published','{"it":"Fetch e API","en":"Fetch and APIs"}','[{"t":"p","text":{"it":"`fetch` parla con un server. Restituisce una risposta: controlla `ok`, poi leggi il corpo con `json()`. Per inviare dati usi `POST` con un corpo in JSON.","en":"`fetch` talks to a server. It gives back a response: check `ok`, then read the body with `json()`. To send data you use `POST` with a JSON body."}},{"t":"code","code":"const r = await fetch(\\"/api/punti\\");\\nif (!r.ok) throw new Error(`Errore ${r.status}`);\\nconst dati = await r.json();\\n\\nawait fetch(\\"/api/punti\\", {\\n  method: \\"POST\\",\\n  headers: { \\"Content-Type\\": \\"application/json\\" },\\n  body: JSON.stringify({ punti: 10 }),\\n});","lang":"js"},{"t":"p","text":{"it":"Attenzione: `fetch` non fallisce su un errore 404 o 500, solo su problemi di rete. Per questo va controllato `r.ok`.","en":"Careful: `fetch` does not fail on a 404 or 500, only on network problems. That is why you check `r.ok`."}}]','{"lang":"js","prompt":{"it":"In una funzione `async`, fai `fetch(\\"/api/corsi\\")`, controlla `r.ok` e leggi `r.json()`.","en":"In an `async` function, do `fetch(\\"/api/corsi\\")`, check `r.ok` and read `r.json()`."},"start":"","html":"","checks":[{"re":"await\\\\s+fetch\\\\(\\\\s*[\\"'']\\\\/api\\\\/corsi[\\"'']\\\\s*\\\\)","label":{"it":"Chiami l’API","en":"You call the API"}},{"re":"r\\\\.ok","label":{"it":"Controlli `ok`","en":"You check `ok`"}},{"re":"await\\\\s+r\\\\.json\\\\(\\\\)","label":{"it":"Leggi il JSON","en":"You read the JSON"}}],"hint":"async function corsi() {\\n  const r = await fetch(\\"/api/corsi\\");\\n  if (!r.ok) throw new Error(\\"Errore\\");\\n  return await r.json();\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','modules',4,3,'published','{"it":"Moduli","en":"Modules"}','[{"t":"p","text":{"it":"I **moduli** dividono il codice in file. `export` rende disponibile qualcosa, `import` lo usa. Nella pagina si caricano con `type=\\"module\\"`.","en":"**Modules** split code into files. `export` makes something available, `import` uses it. In the page they load with `type=\\"module\\"`."}},{"t":"code","code":"// punti.js\\nexport const MAX = 100;\\nexport function somma(a, b) { return a + b; }\\nexport default class Gioco {}\\n\\n// app.js\\nimport Gioco, { MAX, somma } from \\"./punti.js\\";\\nconst pesante = await import(\\"./grafici.js\\");","lang":"js"},{"t":"p","text":{"it":"Ogni modulo ha il suo ambito: le variabili non finiscono più nello spazio globale. `import()` come funzione carica un modulo solo quando serve.","en":"Each module has its own scope: variables no longer end up in the global space. `import()` as a function loads a module only when needed."}}]','{"lang":"js","prompt":{"it":"Esporta la funzione `doppio` e la costante `MAX`.","en":"Export the function `doppio` and the constant `MAX`."},"start":"","html":"","checks":[{"re":"export\\\\s+function\\\\s+doppio","label":{"it":"Esporti `doppio`","en":"You export `doppio`"}},{"re":"export\\\\s+const\\\\s+MAX","label":{"it":"Esporti `MAX`","en":"You export `MAX`"}}],"hint":"export function doppio(n) {\\n  return n * 2;\\n}\\nexport const MAX = 100;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','classes',5,3,'published','{"it":"Classi","en":"Classes"}','[{"t":"p","text":{"it":"Una **classe** è lo stampo di oggetti simili. `constructor` li prepara, i metodi definiscono che cosa sanno fare, `extends` eredita da un’altra classe.","en":"A **class** is the mould for similar objects. `constructor` prepares them, methods define what they can do, `extends` inherits from another class."}},{"t":"code","code":"class Eroe {\\n  #vite = 3;\\n  constructor(nome) {\\n    this.nome = nome;\\n  }\\n  get vite() { return this.#vite; }\\n  colpisci() { this.#vite--; }\\n}\\nclass Mago extends Eroe {\\n  constructor(nome) {\\n    super(nome);\\n    this.magia = 10;\\n  }\\n}\\nconst m = new Mago(\\"Ada\\");","lang":"js"},{"t":"p","text":{"it":"`#` rende un campo privato: da fuori non si tocca. Nel costruttore di una sottoclasse `super()` va chiamato prima di usare `this`.","en":"`#` makes a field private: it cannot be touched from outside. In a subclass constructor `super()` must be called before using `this`."}}]','{"lang":"js","prompt":{"it":"Crea la classe `Gatto` con un `constructor(nome)` e un metodo `miagola()`.","en":"Create the class `Gatto` with a `constructor(nome)` and a `miagola()` method."},"start":"","html":"","checks":[{"re":"class\\\\s+Gatto","label":{"it":"La classe esiste","en":"The class exists"}},{"re":"constructor\\\\s*\\\\(\\\\s*nome\\\\s*\\\\)","label":{"it":"Ha il costruttore","en":"It has the constructor"}},{"re":"miagola\\\\s*\\\\(\\\\s*\\\\)\\\\s*\\\\{","label":{"it":"Ha il metodo","en":"It has the method"}}],"hint":"class Gatto {\\n  constructor(nome) {\\n    this.nome = nome;\\n  }\\n  miagola() {\\n    return \\"Miao\\";\\n  }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','closures',6,3,'published','{"it":"Closure e ciclo degli eventi","en":"Closures and the event loop"}','[{"t":"p","text":{"it":"Una **closure** è una funzione che ricorda le variabili di dove è nata, anche dopo. JavaScript esegue una cosa alla volta: il **ciclo degli eventi** prende dalle code i compiti in attesa quando il codice in corso è finito.","en":"A **closure** is a function that remembers the variables of where it was born, even later. JavaScript runs one thing at a time: the **event loop** takes waiting jobs from the queues when the running code has finished."}},{"t":"code","code":"function contatore() {\\n  let n = 0;\\n  return () => ++n;\\n}\\nconst conta = contatore();\\nconta(); // 1\\nconta(); // 2\\n\\nconsole.log(\\"A\\");\\nsetTimeout(() => console.log(\\"B\\"), 0);\\nPromise.resolve().then(() => console.log(\\"C\\"));\\nconsole.log(\\"D\\");\\n// A D C B","lang":"js"},{"t":"p","text":{"it":"Le Promise (microtask) passano prima dei timer: per questo `C` arriva prima di `B`, anche con attesa zero.","en":"Promises (microtasks) go before timers: that is why `C` comes before `B`, even with a zero wait."}}]','{"lang":"js","prompt":{"it":"Scrivi `creaContatore()` che restituisce una funzione: a ogni chiamata fa `++n`.","en":"Write `creaContatore()` that gives back a function: each call does `++n`."},"start":"","html":"","checks":[{"re":"function\\\\s+creaContatore","label":{"it":"La funzione esiste","en":"The function exists"}},{"re":"let\\\\s+n\\\\s*=\\\\s*0","label":{"it":"`n` sta nella funzione esterna","en":"`n` lives in the outer function"}},{"re":"return\\\\s+(\\\\(\\\\)\\\\s*=>|function)","label":{"it":"Restituisci una funzione","en":"You give back a function"}},{"re":"\\\\+\\\\+n|n\\\\+\\\\+","label":{"it":"`n` cresce","en":"`n` grows"}}],"hint":"function creaContatore() {\\n  let n = 0;\\n  return () => ++n;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','types',1,2,'published','{"it":"Perché i tipi","en":"Why types"}','[{"t":"p","text":{"it":"**TypeScript** è JavaScript con i tipi. Dici che cosa contiene una variabile e il compilatore segnala gli errori prima ancora di eseguire. Il browser non lo legge: viene compilato in JavaScript.","en":"**TypeScript** is JavaScript with types. You say what a variable holds and the compiler flags errors before anything runs. The browser does not read it: it is compiled to JavaScript."}},{"t":"code","code":"let nome: string = \\"Sav\\";\\nlet punti: number = 10;\\nlet attivo: boolean = true;\\nlet voti: number[] = [7, 8];\\n\\npunti = \\"tanti\\"; // Errore: non è un number\\nlet vite = 3;    // tipo dedotto: number","lang":"ts"},{"t":"p","text":{"it":"Spesso il tipo non serve scriverlo: TypeScript lo **deduce** dal valore. `any` spegne i controlli: evitalo.","en":"Often you need not write the type: TypeScript **infers** it from the value. `any` switches checks off: avoid it."}}]','{"lang":"ts","prompt":{"it":"Dichiara `nome` di tipo `string` e `voti` come array di `number`.","en":"Declare `nome` of type `string` and `voti` as an array of `number`."},"start":"","html":"","checks":[{"re":"nome\\\\s*:\\\\s*string","label":{"it":"`nome` è una stringa","en":"`nome` is a string"}},{"re":"voti\\\\s*:\\\\s*number\\\\[\\\\]","label":{"it":"`voti` è un array di numeri","en":"`voti` is an array of numbers"}}],"hint":"let nome: string = \\"Sav\\";\\nlet voti: number[] = [7, 8];"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','functions',2,2,'published','{"it":"Funzioni tipizzate","en":"Typed functions"}','[{"t":"p","text":{"it":"Si tipizzano parametri e risultato. Un parametro con `?` è facoltativo, uno con `=` ha un valore di default. `void` indica che una funzione non restituisce nulla.","en":"You type parameters and the result. A parameter with `?` is optional, one with `=` has a default value. `void` means a function gives back nothing."}},{"t":"code","code":"function somma(a: number, b: number): number {\\n  return a + b;\\n}\\nfunction saluta(nome: string, titolo?: string): string {\\n  return titolo ? `${titolo} ${nome}` : nome;\\n}\\nconst log = (testo: string): void => console.log(testo);","lang":"ts"},{"t":"p","text":{"it":"Il tipo del risultato si può dedurre, ma scriverlo è una buona abitudine: è un piccolo contratto.","en":"The result type can be inferred, but writing it is a good habit: it is a small contract."}}]','{"lang":"ts","prompt":{"it":"Scrivi `doppio(n: number): number` che restituisce `n * 2`.","en":"Write `doppio(n: number): number` that gives back `n * 2`."},"start":"","html":"","checks":[{"re":"doppio\\\\s*\\\\(\\\\s*n\\\\s*:\\\\s*number\\\\s*\\\\)\\\\s*:\\\\s*number","label":{"it":"Parametro e risultato hanno un tipo","en":"Parameter and result have a type"}},{"re":"return\\\\s+n\\\\s*\\\\*\\\\s*2","label":{"it":"Restituisci il doppio","en":"You give back the double"}}],"hint":"function doppio(n: number): number {\\n  return n * 2;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','interfaces',3,2,'published','{"it":"Interfacce e type","en":"Interfaces and type"}','[{"t":"p","text":{"it":"Un’**interfaccia** descrive la forma di un oggetto. `?` rende una proprietà facoltativa, `readonly` la blocca. `type` dà un nome a un tipo qualsiasi.","en":"An **interface** describes the shape of an object. `?` makes a property optional, `readonly` locks it. `type` gives a name to any type."}},{"t":"code","code":"interface Utente {\\n  readonly id: number;\\n  nome: string;\\n  email?: string;\\n}\\ntype Punti = number;\\nconst u: Utente = { id: 1, nome: \\"Sav\\" };\\n\\ninterface Admin extends Utente {\\n  ruolo: string;\\n}","lang":"ts"},{"t":"p","text":{"it":"Se manca una proprietà obbligatoria o ne scrivi una sbagliata, l’errore appare subito, e l’editor completa i nomi per te.","en":"If a required property is missing or you write a wrong one, the error appears at once, and the editor completes the names for you."}}]','{"lang":"ts","prompt":{"it":"Crea l’interfaccia `Corso` con `titolo: string` e `livelli: number`.","en":"Create the interface `Corso` with `titolo: string` and `livelli: number`."},"start":"","html":"","checks":[{"re":"interface\\\\s+Corso","label":{"it":"L’interfaccia esiste","en":"The interface exists"}},{"re":"titolo\\\\s*:\\\\s*string","label":{"it":"`titolo` è una stringa","en":"`titolo` is a string"}},{"re":"livelli\\\\s*:\\\\s*number","label":{"it":"`livelli` è un numero","en":"`livelli` is a number"}}],"hint":"interface Corso {\\n  titolo: string;\\n  livelli: number;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','unions',4,3,'published','{"it":"Unioni e restringimento","en":"Unions and narrowing"}','[{"t":"p","text":{"it":"Un’**unione** accetta più tipi: `string | number`. Le unioni di valori creano scelte precise. Il **restringimento** usa un controllo per far capire a TypeScript quale tipo hai.","en":"A **union** accepts several types: `string | number`. Unions of values create precise choices. **Narrowing** uses a check to tell TypeScript which type you have."}},{"t":"code","code":"type Stato = \\"attesa\\" | \\"fatto\\" | \\"errore\\";\\nlet s: Stato = \\"fatto\\";\\n\\nfunction lunghezza(x: string | string[]): number {\\n  if (typeof x === \\"string\\") {\\n    return x.length;  // qui x è string\\n  }\\n  return x.length;    // qui x è string[]\\n}\\nlet nome: string | null = null;","lang":"ts"},{"t":"p","text":{"it":"Con `strictNullChecks` un valore che può essere `null` va controllato prima dell’uso: sparisce il classico errore «cannot read property of null».","en":"With `strictNullChecks` a value that may be `null` must be checked before use: the classic “cannot read property of null” error disappears."}}]','{"lang":"ts","prompt":{"it":"Crea il tipo `Tema` che accetta solo `\\"chiaro\\"` o `\\"scuro\\"`.","en":"Create the type `Tema` that accepts only `\\"chiaro\\"` or `\\"scuro\\"`."},"start":"","html":"","checks":[{"re":"type\\\\s+Tema\\\\s*=","label":{"it":"Il tipo esiste","en":"The type exists"}},{"re":"\\"chiaro\\"\\\\s*\\\\|\\\\s*\\"scuro\\"","label":{"it":"Accetta i due valori","en":"It accepts both values"}}],"hint":"type Tema = \\"chiaro\\" | \\"scuro\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','generics',5,3,'published','{"it":"Generici","en":"Generics"}','[{"t":"p","text":{"it":"Un **generico** è un tipo che fa da parametro: la stessa funzione lavora con tipi diversi senza perdere la precisione. Di solito si chiama `T`.","en":"A **generic** is a type acting as a parameter: the same function works with different types without losing precision. It is usually called `T`."}},{"t":"code","code":"function primo<T>(lista: T[]): T | undefined {\\n  return lista[0];\\n}\\nconst a = primo([1, 2]);     // number\\nconst b = primo([\\"x\\"]);      // string\\n\\ninterface Scatola<T> {\\n  contenuto: T;\\n}\\nconst s: Scatola<number> = { contenuto: 5 };","lang":"ts"},{"t":"p","text":{"it":"Esistono tipi di utilità già pronti: `Partial<T>` rende tutto facoltativo, `Pick<T, K>` sceglie delle proprietà, `Record<K, V>` descrive una mappa.","en":"Ready-made utility types exist: `Partial<T>` makes everything optional, `Pick<T, K>` picks properties, `Record<K, V>` describes a map."}}]','{"lang":"ts","prompt":{"it":"Scrivi `ultimo<T>(lista: T[])` che restituisce l’ultimo elemento.","en":"Write `ultimo<T>(lista: T[])` that gives back the last item."},"start":"","html":"","checks":[{"re":"ultimo\\\\s*<\\\\s*T\\\\s*>\\\\s*\\\\(\\\\s*lista\\\\s*:\\\\s*T\\\\[\\\\]\\\\s*\\\\)","label":{"it":"La funzione è generica","en":"The function is generic"}},{"re":"lista\\\\[lista\\\\.length\\\\s*-\\\\s*1\\\\]|lista\\\\.at\\\\(-1\\\\)","label":{"it":"Restituisci l’ultimo","en":"You give back the last one"}}],"hint":"function ultimo<T>(lista: T[]): T | undefined {\\n  return lista[lista.length - 1];\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','tooling',6,3,'published','{"it":"Il compilatore e le classi","en":"The compiler and classes"}','[{"t":"p","text":{"it":"`tsconfig.json` regola il compilatore: `strict` attiva tutti i controlli. `tsc` compila. Nelle classi `private` e `public` limitano l’accesso, e un costruttore può dichiarare i campi da solo.","en":"`tsconfig.json` sets up the compiler: `strict` turns on all the checks. `tsc` compiles. In classes `private` and `public` limit access, and a constructor can declare fields by itself."}},{"t":"code","code":"// tsconfig.json\\n{\\n  \\"compilerOptions\\": {\\n    \\"target\\": \\"ES2022\\",\\n    \\"strict\\": true\\n  }\\n}\\nclass Eroe {\\n  constructor(public nome: string, private vite = 3) {}\\n  colpisci(): void { this.vite--; }\\n}","lang":"ts"},{"t":"p","text":{"it":"Per le librerie scritte in JavaScript esistono i pacchetti `@types`, che aggiungono i tipi. Un file `.d.ts` contiene solo tipi.","en":"For libraries written in JavaScript there are `@types` packages, which add the types. A `.d.ts` file holds only types."}}]','{"lang":"ts","prompt":{"it":"Scrivi una classe `Conto` con un campo `private saldo: number`.","en":"Write a class `Conto` with a `private saldo: number` field."},"start":"","html":"","checks":[{"re":"class\\\\s+Conto","label":{"it":"La classe esiste","en":"The class exists"}},{"re":"private\\\\s+saldo\\\\s*:\\\\s*number","label":{"it":"Il campo è privato","en":"The field is private"}}],"hint":"class Conto {\\n  private saldo: number = 0;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','hello',1,1,'published','{"it":"Ciao dal server","en":"Hello from the server"}','[{"t":"p","text":{"it":"**PHP** gira sul server e produce la pagina prima che arrivi al browser. Il codice sta tra `<?php` e `?>`. Le variabili iniziano con `$` e ogni istruzione finisce con `;`.","en":"**PHP** runs on the server and produces the page before it reaches the browser. Code lives between `<?php` and `?>`. Variables start with `$` and every statement ends with `;`."}},{"t":"code","code":"<?php\\n$nome = \\"Sav\\";\\n$punti = 10;\\necho \\"Ciao $nome, hai $punti punti\\";\\necho ''Virgolette singole: $nome'';\\n?>\\n<p><?= $nome ?></p>","lang":"php"},{"t":"p","text":{"it":"Tra virgolette doppie le variabili vengono sostituite, tra singole no. `<?=` è la scorciatoia per stampare un valore nell’HTML.","en":"Between double quotes variables are replaced, between single quotes they are not. `<?=` is the shortcut for printing a value in HTML."}}]','{"lang":"php","prompt":{"it":"Crea `$nome` e stampalo con `echo` dentro un saluto tra virgolette doppie.","en":"Create `$nome` and print it with `echo` inside a greeting between double quotes."},"start":"<?php","html":"","checks":[{"re":"\\\\$nome\\\\s*=","label":{"it":"Crei `$nome`","en":"You create `$nome`"}},{"re":"echo\\\\s+\\"[^\\"]*\\\\$nome","label":{"it":"Lo stampi","en":"You print it"}}],"hint":"<?php\\n$nome = \\"Sav\\";\\necho \\"Ciao $nome\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','logic',2,1,'published','{"it":"Condizioni e cicli","en":"Conditions and loops"}','[{"t":"p","text":{"it":"`if`, `else`, `for` e `while` funzionano come in JavaScript. Le stringhe si uniscono con il punto. Per confrontare usa `===`.","en":"`if`, `else`, `for` and `while` work as in JavaScript. Strings join with a dot. To compare use `===`."}},{"t":"code","code":"<?php\\n$voto = 8;\\nif ($voto >= 6) {\\n    echo \\"Promosso\\";\\n} else {\\n    echo \\"Riprova\\";\\n}\\nfor ($i = 1; $i <= 3; $i++) {\\n    echo \\"Giro \\" . $i . \\"<br>\\";\\n}\\n$esito = match (true) {\\n    $voto >= 9 => \\"Ottimo\\",\\n    default => \\"Bene\\",\\n};","lang":"php"},{"t":"p","text":{"it":"`match` è un confronto compatto che restituisce un valore. Il punto `.` unisce i testi: `+` farebbe una somma.","en":"`match` is a compact comparison that gives back a value. The dot `.` joins text: `+` would add numbers."}}]','{"lang":"php","prompt":{"it":"Con un ciclo `for`, stampa i numeri da 1 a 5.","en":"With a `for` loop, print the numbers from 1 to 5."},"start":"<?php","html":"","checks":[{"re":"for\\\\s*\\\\(\\\\s*\\\\$i\\\\s*=\\\\s*1\\\\s*;\\\\s*\\\\$i\\\\s*<=\\\\s*5\\\\s*;\\\\s*\\\\$i\\\\+\\\\+\\\\s*\\\\)","label":{"it":"Il ciclo va da 1 a 5","en":"The loop goes from 1 to 5"}},{"re":"echo\\\\s+\\\\$i","label":{"it":"Stampi `$i`","en":"You print `$i`"}}],"hint":"<?php\\nfor ($i = 1; $i <= 5; $i++) {\\n    echo $i;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','arrays',3,1,'published','{"it":"Array","en":"Arrays"}','[{"t":"p","text":{"it":"Gli array PHP fanno due lavori: liste e coppie chiave-valore. `foreach` li scorre. `count` dice quanti elementi ci sono.","en":"PHP arrays do two jobs: lists and key-value pairs. `foreach` walks them. `count` says how many items there are."}},{"t":"code","code":"<?php\\n$corsi = [\\"HTML\\", \\"CSS\\"];\\n$corsi[] = \\"PHP\\";\\n\\n$utente = [\\"nome\\" => \\"Sav\\", \\"punti\\" => 10];\\necho $utente[\\"nome\\"];\\n\\nforeach ($utente as $chiave => $valore) {\\n    echo \\"$chiave: $valore<br>\\";\\n}\\necho count($corsi); // 3\\nin_array(\\"CSS\\", $corsi); // true","lang":"php"},{"t":"p","text":{"it":"`$lista[] = x` aggiunge in fondo. `=>` lega una chiave al suo valore.","en":"`$lista[] = x` adds to the end. `=>` ties a key to its value."}}]','{"lang":"php","prompt":{"it":"Crea l’array associativo `$libro` con `titolo` e stampa il titolo.","en":"Create the associative array `$libro` with `titolo` and print the title."},"start":"<?php","html":"","checks":[{"re":"\\\\$libro\\\\s*=\\\\s*\\\\[\\\\s*[\\"'']titolo[\\"'']\\\\s*=>","label":{"it":"L’array ha la chiave","en":"The array has the key"}},{"re":"echo\\\\s+\\\\$libro\\\\[\\\\s*[\\"'']titolo[\\"'']\\\\s*\\\\]","label":{"it":"Stampi il titolo","en":"You print the title"}}],"hint":"<?php\\n$libro = [\\"titolo\\" => \\"Fucina\\"];\\necho $libro[\\"titolo\\"];"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','functions',4,2,'published','{"it":"Funzioni e stringhe","en":"Functions and strings"}','[{"t":"p","text":{"it":"Le funzioni si dichiarano con `function` e possono avere tipi per parametri e risultato. PHP offre molte funzioni pronte per i testi.","en":"Functions are declared with `function` and can have types for parameters and result. PHP offers many ready-made functions for text."}},{"t":"code","code":"<?php\\nfunction somma(int $a, int $b = 1): int {\\n    return $a + $b;\\n}\\necho somma(2, 3);\\n\\nstrlen(\\"ciao\\");          // 4\\nstrtoupper(\\"ciao\\");      // \\"CIAO\\"\\nstr_replace(\\"a\\", \\"o\\", \\"casa\\"); // \\"coso\\"\\nexplode(\\",\\", \\"a,b\\");     // [\\"a\\", \\"b\\"]\\ntrim(\\"  ciao  \\");        // \\"ciao\\"","lang":"php"},{"t":"p","text":{"it":"Le variabili esterne non si vedono dentro una funzione: si passano come parametri.","en":"Outer variables are not visible inside a function: pass them as parameters."}}]','{"lang":"php","prompt":{"it":"Scrivi `function saluta(string $nome): string` che restituisce `\\"Ciao \\" . $nome`.","en":"Write `function saluta(string $nome): string` that gives back `\\"Ciao \\" . $nome`."},"start":"<?php","html":"","checks":[{"re":"function\\\\s+saluta\\\\s*\\\\(\\\\s*string\\\\s+\\\\$nome\\\\s*\\\\)\\\\s*:\\\\s*string","label":{"it":"La firma è giusta","en":"The signature is right"}},{"re":"return\\\\s+\\"Ciao \\"\\\\s*\\\\.\\\\s*\\\\$nome","label":{"it":"Restituisci il saluto","en":"You give back the greeting"}}],"hint":"<?php\\nfunction saluta(string $nome): string {\\n    return \\"Ciao \\" . $nome;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','forms',5,2,'published','{"it":"Moduli e sicurezza","en":"Forms and security"}','[{"t":"p","text":{"it":"I dati di un modulo arrivano in `$_POST` o `$_GET`. **Non fidarti mai** di ciò che arriva: controllalo e, prima di stamparlo, proteggilo con `htmlspecialchars`.","en":"Form data arrives in `$_POST` or `$_GET`. **Never trust** what arrives: check it and, before printing it, protect it with `htmlspecialchars`."}},{"t":"code","code":"<?php\\n$nome = trim($_POST[\\"nome\\"] ?? \\"\\");\\nif ($nome === \\"\\") {\\n    echo \\"Scrivi il nome\\";\\n} else {\\n    echo \\"Ciao \\" . htmlspecialchars($nome);\\n}\\n$email = filter_var($_POST[\\"email\\"] ?? \\"\\", FILTER_VALIDATE_EMAIL);","lang":"php"},{"t":"p","text":{"it":"Senza `htmlspecialchars`, un utente potrebbe inserire un tag `<script>` che verrebbe eseguito: si chiama **XSS**. `??` dà un valore se il campo manca.","en":"Without `htmlspecialchars`, a user could insert a `<script>` tag that would run: it is called **XSS**. `??` gives a value if the field is missing."}}]','{"lang":"php","prompt":{"it":"Leggi `$_POST[\\"nome\\"]` con `??` e stampalo protetto da `htmlspecialchars`.","en":"Read `$_POST[\\"nome\\"]` with `??` and print it protected by `htmlspecialchars`."},"start":"<?php","html":"","checks":[{"re":"\\\\$_POST\\\\[\\\\s*[\\"'']nome[\\"'']\\\\s*\\\\]\\\\s*\\\\?\\\\?","label":{"it":"Leggi il campo in sicurezza","en":"You read the field safely"}},{"re":"echo\\\\s+htmlspecialchars\\\\(","label":{"it":"Proteggi il testo","en":"You protect the text"}}],"hint":"<?php\\n$nome = $_POST[\\"nome\\"] ?? \\"\\";\\necho htmlspecialchars($nome);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','files-sessions',6,2,'published','{"it":"Include, sessioni e cookie","en":"Includes, sessions and cookies"}','[{"t":"p","text":{"it":"`require` inserisce un altro file: comodo per testate e funzioni condivise. Le **sessioni** ricordano un utente tra le pagine, i **cookie** salvano piccoli dati nel browser.","en":"`require` inserts another file: handy for shared headers and functions. **Sessions** remember a user across pages, **cookies** keep small data in the browser."}},{"t":"code","code":"<?php\\nrequire __DIR__ . \\"/header.php\\";\\n\\nsession_start();\\n$_SESSION[\\"utente\\"] = \\"Sav\\";\\n\\nsetcookie(\\"tema\\", \\"scuro\\", [\\n    \\"expires\\" => time() + 86400,\\n    \\"httponly\\" => true,\\n    \\"samesite\\" => \\"Lax\\",\\n]);\\nheader(\\"Location: home.php\\");\\nexit;","lang":"php"},{"t":"p","text":{"it":"`session_start` e `header` vanno chiamati prima di stampare qualsiasi cosa. Dopo un `header(\\"Location: …\\")` scrivi sempre `exit`.","en":"`session_start` and `header` must be called before printing anything. After a `header(\\"Location: …\\")` always write `exit`."}}]','{"lang":"php","prompt":{"it":"Avvia la sessione e salva `\\"Sav\\"` in `$_SESSION[\\"utente\\"]`.","en":"Start the session and save `\\"Sav\\"` in `$_SESSION[\\"utente\\"]`."},"start":"<?php","html":"","checks":[{"re":"session_start\\\\(\\\\)","label":{"it":"Avvii la sessione","en":"You start the session"}},{"re":"\\\\$_SESSION\\\\[\\\\s*[\\"'']utente[\\"'']\\\\s*\\\\]\\\\s*=","label":{"it":"Salvi l’utente","en":"You save the user"}}],"hint":"<?php\\nsession_start();\\n$_SESSION[\\"utente\\"] = \\"Sav\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','classes',1,2,'published','{"it":"Classi e oggetti","en":"Classes and objects"}','[{"t":"p","text":{"it":"Una classe è lo stampo degli oggetti. Si accede a proprietà e metodi con `->`. Le visibilità `public`, `protected` e `private` decidono chi può usarli.","en":"A class is the mould of objects. You reach properties and methods with `->`. The visibilities `public`, `protected` and `private` decide who can use them."}},{"t":"code","code":"<?php\\nclass Eroe {\\n    public function __construct(\\n        public string $nome,\\n        private int $vite = 3,\\n    ) {}\\n\\n    public function colpisci(): void {\\n        $this->vite--;\\n    }\\n}\\n$e = new Eroe(\\"Ada\\");\\n$e->colpisci();\\necho $e->nome;","lang":"php"},{"t":"p","text":{"it":"La **promozione nel costruttore** dichiara e assegna le proprietà in un colpo. `$this` è l’oggetto stesso.","en":"**Constructor promotion** declares and assigns properties in one go. `$this` is the object itself."}}]','{"lang":"php","prompt":{"it":"Crea la classe `Gatto` con un costruttore che riceve `public string $nome`.","en":"Create the class `Gatto` with a constructor taking `public string $nome`."},"start":"<?php","html":"","checks":[{"re":"class\\\\s+Gatto","label":{"it":"La classe esiste","en":"The class exists"}},{"re":"__construct\\\\s*\\\\(\\\\s*public\\\\s+string\\\\s+\\\\$nome","label":{"it":"Il costruttore è giusto","en":"The constructor is right"}}],"hint":"<?php\\nclass Gatto {\\n    public function __construct(public string $nome) {}\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','pdo',2,2,'published','{"it":"Database con PDO","en":"Databases with PDO"}','[{"t":"p","text":{"it":"**PDO** collega PHP a un database. Le **query preparate** separano il comando dai dati: è la difesa contro la **SQL injection**. Non inserire mai una variabile dentro il testo di una query.","en":"**PDO** connects PHP to a database. **Prepared queries** keep the command apart from the data: it is the defence against **SQL injection**. Never put a variable inside the text of a query."}},{"t":"code","code":"<?php\\n$pdo = new PDO($dsn, $utente, $password, [\\n    PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,\\n]);\\n$st = $pdo->prepare(\\"SELECT nome FROM utenti WHERE id = ?\\");\\n$st->execute([$id]);\\n$riga = $st->fetch();\\n\\n$st = $pdo->prepare(\\"INSERT INTO corsi (titolo) VALUES (?)\\");\\n$st->execute([\\"PHP\\"]);","lang":"php"},{"t":"p","text":{"it":"`fetch` legge una riga, `fetchAll` tutte. Il `?` è un segnaposto: il valore viaggia separato e non può cambiare il comando.","en":"`fetch` reads one row, `fetchAll` all of them. `?` is a placeholder: the value travels apart and cannot change the command."}}]','{"lang":"php","prompt":{"it":"Prepara `SELECT * FROM corsi WHERE id = ?` ed eseguila con `[$id]`.","en":"Prepare `SELECT * FROM corsi WHERE id = ?` and run it with `[$id]`."},"start":"<?php","html":"","checks":[{"re":"\\\\$pdo->prepare\\\\(\\\\s*\\"SELECT \\\\* FROM corsi WHERE id = \\\\?\\"\\\\s*\\\\)","label":{"it":"La query è preparata","en":"The query is prepared"}},{"re":"->execute\\\\(\\\\s*\\\\[\\\\s*\\\\$id\\\\s*\\\\]\\\\s*\\\\)","label":{"it":"La esegui con il dato","en":"You run it with the data"}}],"hint":"<?php\\n$st = $pdo->prepare(\\"SELECT * FROM corsi WHERE id = ?\\");\\n$st->execute([$id]);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','passwords',3,2,'published','{"it":"Password e accessi","en":"Passwords and logins"}','[{"t":"p","text":{"it":"Le password non si salvano mai in chiaro. `password_hash` crea un’impronta sicura, `password_verify` controlla un tentativo. Un’impronta non si può riportare al testo originale.","en":"Passwords are never saved in clear text. `password_hash` creates a safe fingerprint, `password_verify` checks an attempt. A fingerprint cannot be turned back into the original text."}},{"t":"code","code":"<?php\\n$impronta = password_hash($password, PASSWORD_DEFAULT);\\n\\nif (password_verify($tentativo, $impronta)) {\\n    session_regenerate_id(true);\\n    $_SESSION[\\"id\\"] = $utente[\\"id\\"];\\n}\\n$token = bin2hex(random_bytes(32));","lang":"php"},{"t":"p","text":{"it":"Dopo l’accesso rigenera l’id di sessione. Per valori segreti usa `random_bytes`: `rand` è prevedibile. Limita anche i tentativi per fermare chi prova a indovinare.","en":"After login regenerate the session id. For secret values use `random_bytes`: `rand` is predictable. Also limit attempts to stop those trying to guess."}}]','{"lang":"php","prompt":{"it":"Crea l’impronta di `$password` con `password_hash` e `PASSWORD_DEFAULT`.","en":"Create the fingerprint of `$password` with `password_hash` and `PASSWORD_DEFAULT`."},"start":"<?php","html":"","checks":[{"re":"password_hash\\\\(\\\\s*\\\\$password\\\\s*,\\\\s*PASSWORD_DEFAULT\\\\s*\\\\)","label":{"it":"Usi `password_hash`","en":"You use `password_hash`"}}],"hint":"<?php\\n$impronta = password_hash($password, PASSWORD_DEFAULT);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','json-api',4,3,'published','{"it":"Costruire un’API JSON","en":"Building a JSON API"}','[{"t":"p","text":{"it":"Un’API risponde con dati invece che con pagine. Imposti il tipo di contenuto, il codice di stato e stampi il JSON. Il corpo di una richiesta si legge da `php://input`.","en":"An API answers with data instead of pages. You set the content type, the status code and print the JSON. The body of a request is read from `php://input`."}},{"t":"code","code":"<?php\\nheader(\\"Content-Type: application/json; charset=utf-8\\");\\n\\n$dati = json_decode(file_get_contents(\\"php://input\\"), true);\\nif (!is_array($dati) || empty($dati[\\"nome\\"])) {\\n    http_response_code(422);\\n    echo json_encode([\\"errore\\" => \\"Nome mancante\\"]);\\n    exit;\\n}\\necho json_encode([\\"ok\\" => true, \\"nome\\" => $dati[\\"nome\\"]]);","lang":"php"},{"t":"p","text":{"it":"Con `true`, `json_decode` restituisce array invece di oggetti. Usa i codici giusti: `200` riuscito, `401` non autenticato, `404` non trovato, `422` dati non validi.","en":"With `true`, `json_decode` gives back arrays instead of objects. Use the right codes: `200` success, `401` not signed in, `404` not found, `422` invalid data."}}]','{"lang":"php","prompt":{"it":"Imposta l’intestazione JSON e stampa `[\\"ok\\" => true]` con `json_encode`.","en":"Set the JSON header and print `[\\"ok\\" => true]` with `json_encode`."},"start":"<?php","html":"","checks":[{"re":"header\\\\(\\\\s*\\"Content-Type:\\\\s*application\\\\/json","label":{"it":"L’intestazione è giusta","en":"The header is right"}},{"re":"echo\\\\s+json_encode\\\\(","label":{"it":"Stampi il JSON","en":"You print the JSON"}}],"hint":"<?php\\nheader(\\"Content-Type: application/json\\");\\necho json_encode([\\"ok\\" => true]);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','errors',5,3,'published','{"it":"Errori ed eccezioni","en":"Errors and exceptions"}','[{"t":"p","text":{"it":"Quando qualcosa va storto, `throw` lancia un’eccezione e `catch` la gestisce. In produzione gli errori si scrivono nei log e non si mostrano mai ai visitatori.","en":"When something goes wrong, `throw` raises an exception and `catch` handles it. In production errors are written to logs and never shown to visitors."}},{"t":"code","code":"<?php\\ndeclare(strict_types=1);\\n\\nfunction dividi(int $a, int $b): float {\\n    if ($b === 0) {\\n        throw new InvalidArgumentException(\\"Divisione per zero\\");\\n    }\\n    return $a / $b;\\n}\\ntry {\\n    echo dividi(1, 0);\\n} catch (InvalidArgumentException $e) {\\n    error_log($e->getMessage());\\n    echo \\"Riprova\\";\\n} finally {\\n    echo \\"Fine\\";\\n}","lang":"php"},{"t":"p","text":{"it":"`strict_types` impedisce conversioni silenziose: passare un testo a un `int` diventa un errore. `Throwable` raccoglie tutti gli errori ed eccezioni.","en":"`strict_types` prevents silent conversions: passing text to an `int` becomes an error. `Throwable` gathers all errors and exceptions."}}]','{"lang":"php","prompt":{"it":"Con `try` e `catch (Exception $e)`, chiama `rischio()` e scrivi il messaggio con `error_log`.","en":"With `try` and `catch (Exception $e)`, call `rischio()` and write the message with `error_log`."},"start":"<?php","html":"","checks":[{"re":"try\\\\s*\\\\{[\\\\s\\\\S]*rischio\\\\(\\\\)","label":{"it":"Provi `rischio()`","en":"You try `rischio()`"}},{"re":"catch\\\\s*\\\\(\\\\s*Exception\\\\s+\\\\$e\\\\s*\\\\)","label":{"it":"Catturi l’eccezione","en":"You catch the exception"}},{"re":"error_log\\\\(","label":{"it":"Scrivi nel log","en":"You write to the log"}}],"hint":"<?php\\ntry {\\n    rischio();\\n} catch (Exception $e) {\\n    error_log($e->getMessage());\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','project',6,3,'published','{"it":"Progetti ordinati","en":"Tidy projects"}','[{"t":"p","text":{"it":"Un progetto serio usa **Composer** per le librerie e i **namespace** per non far scontrare i nomi. Le credenziali stanno fuori dal codice pubblico, in un file escluso da git o nelle variabili d’ambiente.","en":"A serious project uses **Composer** for libraries and **namespaces** to stop names clashing. Credentials stay out of public code, in a file excluded from git or in environment variables."}},{"t":"code","code":"<?php\\nnamespace Fucina\\\\Corsi;\\n\\nuse Fucina\\\\Db\\\\Connessione;\\n\\nrequire __DIR__ . \\"/vendor/autoload.php\\";\\n\\n$password = getenv(\\"DB_PASSWORD\\");\\n\\nfinal class Catalogo {\\n    public function __construct(private Connessione $db) {}\\n}","lang":"php"},{"t":"p","text":{"it":"Passare le dipendenze dal costruttore si chiama **iniezione delle dipendenze**: il codice diventa più facile da provare. `vendor/autoload.php` carica le classi da solo.","en":"Passing dependencies through the constructor is called **dependency injection**: code becomes easier to test. `vendor/autoload.php` loads classes by itself."}}]','{"lang":"php","prompt":{"it":"Dichiara il namespace `Fucina\\\\Corsi` e leggi la password con `getenv(\\"DB_PASSWORD\\")`.","en":"Declare the namespace `Fucina\\\\Corsi` and read the password with `getenv(\\"DB_PASSWORD\\")`."},"start":"<?php","html":"","checks":[{"re":"namespace\\\\s+Fucina\\\\\\\\Corsi","label":{"it":"Il namespace è giusto","en":"The namespace is right"}},{"re":"getenv\\\\(\\\\s*\\"DB_PASSWORD\\"\\\\s*\\\\)","label":{"it":"Leggi la variabile","en":"You read the variable"}}],"hint":"<?php\\nnamespace Fucina\\\\Corsi;\\n$password = getenv(\\"DB_PASSWORD\\");"}');
