INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),1,1,'{"it":"Dove va il contenuto visibile della pagina?","en":"Where does the visible content of the page go?"}','[{"it":"<head>","en":"<head>"},{"it":"<body>","en":"<body>"},{"it":"<title>","en":"<title>"},{"it":"<meta>","en":"<meta>"}]',1,'{"it":"Tutto ciò che si vede nella pagina sta dentro `<body>`.","en":"Everything visible on the page sits inside `<body>`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),2,1,'{"it":"A cosa serve `<!doctype html>`?","en":"What is `<!doctype html>` for?"}','[{"it":"Crea un titolo","en":"It creates a heading"},{"it":"Dice al browser che è una pagina HTML moderna","en":"It tells the browser this is a modern HTML page"},{"it":"Collega un foglio di stile","en":"It links a stylesheet"},{"it":"Chiude il documento","en":"It closes the document"}]',1,'{"it":"Va sempre sulla prima riga: evita che il browser usi la vecchia modalità di compatibilità.","en":"It always goes on the first line: it stops the browser using the old compatibility mode."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),3,1,'{"it":"Quale tag imposta il testo della scheda del browser?","en":"Which tag sets the text of the browser tab?"}','[{"it":"<h1>","en":"<h1>"},{"it":"<header>","en":"<header>"},{"it":"<title>","en":"<title>"},{"it":"<tab>","en":"<tab>"}]',2,'{"it":"`<title>` sta in `<head>` e dà il nome alla scheda.","en":"`<title>` sits in `<head>` and names the tab."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),1,1,'{"it":"Qual è il titolo più importante?","en":"Which is the most important heading?"}','[{"it":"<h6>","en":"<h6>"},{"it":"<h1>","en":"<h1>"},{"it":"<head>","en":"<head>"},{"it":"<p>","en":"<p>"}]',1,'{"it":"La numerazione va dal più importante, `h1`, al meno importante, `h6`.","en":"Numbering goes from the most important, `h1`, to the least, `h6`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),2,1,'{"it":"Quale tag indica un testo importante?","en":"Which tag marks important text?"}','[{"it":"<i>","en":"<i>"},{"it":"<strong>","en":"<strong>"},{"it":"<big>","en":"<big>"},{"it":"<u>","en":"<u>"}]',1,'{"it":"`<strong>` dà importanza al testo, anche per chi usa uno screen reader.","en":"`<strong>` gives the text importance, also for screen reader users."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),3,1,'{"it":"Quale di questi tag non ha un tag di chiusura?","en":"Which of these tags has no closing tag?"}','[{"it":"<p>","en":"<p>"},{"it":"<em>","en":"<em>"},{"it":"<br>","en":"<br>"},{"it":"<h2>","en":"<h2>"}]',2,'{"it":"`<br>` è un elemento vuoto: non ha contenuto e non si chiude.","en":"`<br>` is an empty element: it has no content and is not closed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),1,1,'{"it":"Quale attributo contiene la destinazione di un link?","en":"Which attribute holds the destination of a link?"}','[{"it":"src","en":"src"},{"it":"href","en":"href"},{"it":"link","en":"link"},{"it":"to","en":"to"}]',1,'{"it":"`href` sta per «hypertext reference».","en":"`href` stands for “hypertext reference”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),2,1,'{"it":"A cosa serve l’attributo `alt`?","en":"What is the `alt` attribute for?"}','[{"it":"Allinea l’immagine","en":"It aligns the image"},{"it":"Descrive l’immagine a chi non può vederla","en":"It describes the image to whoever cannot see it"},{"it":"Indica l’altezza","en":"It sets the height"},{"it":"Apre un link","en":"It opens a link"}]',1,'{"it":"Lo leggono gli screen reader e compare se l’immagine non si carica.","en":"Screen readers read it and it appears if the image fails to load."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),3,1,'{"it":"Quale riga è corretta?","en":"Which line is correct?"}','[{"it":"<a src=\\"a.html\\">Vai</a>","en":"<a src=\\"a.html\\">Vai</a>"},{"it":"<img href=\\"a.jpg\\">","en":"<img href=\\"a.jpg\\">"},{"it":"<a href=\\"a.html\\">Vai</a>","en":"<a href=\\"a.html\\">Vai</a>"},{"it":"<link a=\\"a.html\\">Vai</link>","en":"<link a=\\"a.html\\">Vai</link>"}]',2,'{"it":"I link usano `href`, le immagini `src`.","en":"Links use `href`, images use `src`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'lists'),1,1,'{"it":"Quale tag crea una lista numerata?","en":"Which tag creates a numbered list?"}','[{"it":"<ul>","en":"<ul>"},{"it":"<ol>","en":"<ol>"},{"it":"<li>","en":"<li>"},{"it":"<nl>","en":"<nl>"}]',1,'{"it":"`ol` sta per «ordered list».","en":"`ol` stands for “ordered list”."}',NULL);
