INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'forms'),1,2,'{"it":"Come si collega una `label` a un campo?","en":"How do you tie a `label` to a field?"}','[{"it":"Con `for` uguale all’`id` del campo","en":"With `for` equal to the field’s `id`"},{"it":"Con `name` uguale a `class`","en":"With `name` equal to `class`"},{"it":"Con `href`","en":"With `href`"},{"it":"Mettendola subito prima","en":"By placing it right before"}]',0,'{"it":"`for` e `id` devono avere lo stesso valore.","en":"`for` and `id` must have the same value."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'forms'),2,2,'{"it":"Quale attributo rende obbligatorio un campo?","en":"Which attribute makes a field mandatory?"}','[{"it":"needed","en":"needed"},{"it":"mandatory","en":"mandatory"},{"it":"required","en":"required"},{"it":"must","en":"must"}]',2,'{"it":"Con `required` il browser blocca l’invio se il campo è vuoto.","en":"With `required` the browser blocks sending if the field is empty."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'forms'),3,2,'{"it":"A cosa serve `name` in un campo?","en":"What is `name` for in a field?"}','[{"it":"È il testo mostrato","en":"It is the text shown"},{"it":"È il nome con cui il dato viene inviato","en":"It is the name the data is sent with"},{"it":"È il suo stile","en":"It is its style"},{"it":"Dà un titolo alla pagina","en":"It titles the page"}]',1,'{"it":"Senza `name` il valore del campo non viene inviato.","en":"Without `name` the value of the field is not sent."}',NULL);
