INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'entities'),3,2,'{"it":"Un commento è segreto?","en":"Is a comment secret?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"No, si legge nel sorgente","en":"No, it can be read in the source"},{"it":"Solo in `<head>`","en":"Only in `<head>`"},{"it":"Solo sul server","en":"Only on the server"}]',1,'{"it":"Mai scrivere password o dati privati in un commento.","en":"Never write passwords or private data in a comment."}',NULL);
