INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),2,2,'{"it":"Perché indicare `width` e `height` su `<img>`?","en":"Why set `width` and `height` on `<img>`?"}','[{"it":"Per comprimere il file","en":"To compress the file"},{"it":"Per riservare lo spazio ed evitare salti","en":"To reserve the space and avoid jumps"},{"it":"Per il SEO","en":"For SEO"},{"it":"Sono obbligatori","en":"They are mandatory"}]',1,'{"it":"Il browser conosce le proporzioni prima di scaricare il file.","en":"The browser knows the proportions before downloading the file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),3,2,'{"it":"Quale tag aggiunge i sottotitoli a un video?","en":"Which tag adds subtitles to a video?"}','[{"it":"<source>","en":"<source>"},{"it":"<caption>","en":"<caption>"},{"it":"<track>","en":"<track>"},{"it":"<subtitle>","en":"<subtitle>"}]',2,'{"it":"`<track kind=\\"captions\\">` collega un file di sottotitoli.","en":"`<track kind=\\"captions\\">` links a subtitle file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),1,2,'{"it":"Quale elemento funziona già da tastiera?","en":"Which element already works with the keyboard?"}','[{"it":"<div onclick>","en":"<div onclick>"},{"it":"<span>","en":"<span>"},{"it":"<button>","en":"<button>"},{"it":"<p>","en":"<p>"}]',2,'{"it":"`<button>` riceve il focus e si attiva con Invio e Spazio.","en":"`<button>` gets focus and activates with Enter and Space."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),2,2,'{"it":"Come dai un nome a un pulsante con solo un’icona?","en":"How do you name a button that only has an icon?"}','[{"it":"title-text","en":"title-text"},{"it":"aria-label","en":"aria-label"},{"it":"name","en":"name"},{"it":"alt","en":"alt"}]',1,'{"it":"`aria-label` è il nome che legge lo screen reader.","en":"`aria-label` is the name the screen reader reads."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),3,2,'{"it":"Qual è la prima regola di ARIA?","en":"What is the first rule of ARIA?"}','[{"it":"Usarla ovunque","en":"Use it everywhere"},{"it":"Preferire i tag HTML adatti","en":"Prefer suitable HTML tags"},{"it":"Metterla solo nei `div`","en":"Only put it on `div`s"},{"it":"Sostituisce le `label`","en":"It replaces `label`s"}]',1,'{"it":"L’HTML nativo porta con sé ruolo, stato e tastiera.","en":"Native HTML brings role, state and keyboard along."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),1,3,'{"it":"Quale meta è indispensabile per i telefoni?","en":"Which meta is essential for phones?"}','[{"it":"charset","en":"charset"},{"it":"viewport","en":"viewport"},{"it":"keywords","en":"keywords"},{"it":"author","en":"author"}]',1,'{"it":"Senza `viewport` il telefono mostra la pagina come su un computer, rimpicciolita.","en":"Without `viewport` the phone shows the page as on a computer, shrunk."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),2,3,'{"it":"Quali tag creano una sezione apribile senza JavaScript?","en":"Which tags create a collapsible section with no JavaScript?"}','[{"it":"<open> <close>","en":"<open> <close>"},{"it":"<details> <summary>","en":"<details> <summary>"},{"it":"<toggle> <item>","en":"<toggle> <item>"},{"it":"<section> <h2>","en":"<section> <h2>"}]',1,'{"it":"`<summary>` è la riga sempre visibile su cui si tocca.","en":"`<summary>` is the always-visible line you tap."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),3,3,'{"it":"Da dove vengono le anteprime dei link condivisi?","en":"Where do the previews of shared links come from?"}','[{"it":"Dai meta Open Graph","en":"From Open Graph metas"},{"it":"Da `<title>` soltanto","en":"From `<title>` alone"},{"it":"Dal CSS","en":"From CSS"},{"it":"Da `<footer>`","en":"From `<footer>`"}]',0,'{"it":"Le app leggono `og:title`, `og:description` e `og:image`.","en":"Apps read `og:title`, `og:description` and `og:image`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'data-attrs'),1,3,'{"it":"Quale attributo è valido?","en":"Which attribute is valid?"}','[{"it":"data-id","en":"data-id"},{"it":"id-data","en":"id-data"},{"it":"my:data","en":"my:data"},{"it":"data_","en":"data_"}]',0,'{"it":"Inizia sempre con `data-`.","en":"It always starts with `data-`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'data-attrs'),2,3,'{"it":"Il contenuto di `<template>` si vede subito?","en":"Is the content of `<template>` shown at once?"}','[{"it":"Sì","en":"Yes"},{"it":"No","en":"No"},{"it":"Solo su telefono","en":"Only on phones"},{"it":"Solo in grassetto","en":"Only in bold"}]',1,'{"it":"Resta nascosto finché uno script non lo copia.","en":"It stays hidden until a script copies it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'data-attrs'),3,3,'{"it":"A che cosa servono i `data-*`?","en":"What are `data-*` for?"}','[{"it":"A salvare dati su un elemento","en":"To keep data on an element"},{"it":"A collegare un database","en":"To connect a database"},{"it":"A cambiare font","en":"To change fonts"},{"it":"A inviare email","en":"To send emails"}]',0,'{"it":"Sono comodi per passare dati dall’HTML al JavaScript.","en":"They are handy for passing data from HTML to JavaScript."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'seo'),1,3,'{"it":"Che cosa decide `og:image`?","en":"What does `og:image` decide?"}','[{"it":"L’immagine quando condividi","en":"The image when you share"},{"it":"Il logo del browser","en":"The browser logo"},{"it":"La favicon","en":"The favicon"},{"it":"Lo sfondo","en":"The background"}]',0,'{"it":"`og` sta per Open Graph.","en":"`og` stands for Open Graph."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'seo'),2,3,'{"it":"A che cosa serve `rel=\\"canonical\\"`?","en":"What is `rel=\\"canonical\\"` for?"}','[{"it":"Indica l’indirizzo ufficiale","en":"It gives the official address"},{"it":"Blocca i motori","en":"It blocks engines"},{"it":"Apre una scheda","en":"It opens a tab"},{"it":"Carica il CSS","en":"It loads CSS"}]',0,'{"it":"Evita che più URL contino come pagine doppie.","en":"It stops several URLs counting as duplicate pages."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'seo'),3,3,'{"it":"Dove vanno questi tag?","en":"Where do these tags go?"}','[{"it":"<head>","en":"<head>"},{"it":"<body>","en":"<body>"},{"it":"<footer>","en":"<footer>"},{"it":"<main>","en":"<main>"}]',0,'{"it":"Sono metadati: stanno in `head`.","en":"They are metadata: they live in `head`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),1,1,'{"it":"Quale selettore sceglie la classe `nota`?","en":"Which selector picks the class `nota`?"}','[{"it":"#nota","en":"#nota"},{"it":".nota","en":".nota"},{"it":"nota","en":"nota"},{"it":"*nota","en":"*nota"}]',1,'{"it":"Il punto indica la classe, il cancelletto l’id.","en":"The dot marks a class, the hash an id."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),2,1,'{"it":"Che cosa sceglie `nav a`?","en":"What does `nav a` pick?"}','[{"it":"`nav` e tutti i link","en":"`nav` and all the links"},{"it":"I link dentro `nav`","en":"The links inside `nav`"},{"it":"Solo il primo link","en":"Only the first link"},{"it":"Nulla","en":"Nothing"}]',1,'{"it":"Lo spazio è il combinatore discendente.","en":"The space is the descendant combinator."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),3,1,'{"it":"Che cos’è `:hover`?","en":"What is `:hover`?"}','[{"it":"Una pseudo-classe","en":"A pseudo-class"},{"it":"Una proprietà","en":"A property"},{"it":"Un id","en":"An id"},{"it":"Un tag","en":"A tag"}]',0,'{"it":"Le pseudo-classi indicano uno stato o una posizione.","en":"Pseudo-classes mark a state or a position."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),1,1,'{"it":"Quale proprietà cambia il colore del testo?","en":"Which property changes the text colour?"}','[{"it":"text-color","en":"text-color"},{"it":"font-color","en":"font-color"},{"it":"color","en":"color"},{"it":"foreground","en":"foreground"}]',2,'{"it":"Si chiama semplicemente `color`.","en":"It is simply called `color`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),2,1,'{"it":"Quanto vale `2rem` se la base è 16px?","en":"What is `2rem` when the base is 16px?"}','[{"it":"2px","en":"2px"},{"it":"16px","en":"16px"},{"it":"32px","en":"32px"},{"it":"200px","en":"200px"}]',2,'{"it":"`rem` moltiplica la dimensione di base: 2 × 16.","en":"`rem` multiplies the base size: 2 × 16."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),3,1,'{"it":"Perché `font-family` elenca più caratteri?","en":"Why does `font-family` list several fonts?"}','[{"it":"Li usa tutti insieme","en":"It uses them all together"},{"it":"Se il primo manca usa il successivo","en":"If the first is missing it uses the next"},{"it":"Per il grassetto","en":"For bold"},{"it":"È obbligatorio","en":"It is mandatory"}]',1,'{"it":"L’ultimo di solito è una famiglia generica come `serif`.","en":"The last one is usually a generic family such as `serif`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),1,1,'{"it":"Quale strato è lo spazio interno?","en":"Which layer is the inner space?"}','[{"it":"margin","en":"margin"},{"it":"padding","en":"padding"},{"it":"border","en":"border"},{"it":"outline","en":"outline"}]',1,'{"it":"Il `padding` sta tra il contenuto e il bordo.","en":"`padding` sits between the content and the border."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),2,1,'{"it":"Con `border-box`, una scatola `width: 300px` e `padding: 20px` è larga…","en":"With `border-box`, a box with `width: 300px` and `padding: 20px` is…"}','[{"it":"300px","en":"300px wide"},{"it":"320px","en":"320px wide"},{"it":"340px","en":"340px wide"},{"it":"260px","en":"260px wide"}]',0,'{"it":"Il padding sta dentro i 300px: resta meno spazio al contenuto.","en":"The padding fits within the 300px: less room remains for the content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),3,1,'{"it":"Che cosa fa `margin: 0 auto`?","en":"What does `margin: 0 auto` do?"}','[{"it":"Toglie il bordo","en":"Removes the border"},{"it":"Centra orizzontalmente un blocco","en":"Centres a block horizontally"},{"it":"Centra il testo","en":"Centres the text"},{"it":"Nasconde il blocco","en":"Hides the block"}]',1,'{"it":"I margini laterali automatici si dividono lo spazio libero.","en":"Automatic side margins share the free space."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),1,1,'{"it":"Quale elemento è `inline` di natura?","en":"Which element is `inline` by default?"}','[{"it":"<div>","en":"<div>"},{"it":"<p>","en":"<p>"},{"it":"<a>","en":"<a>"},{"it":"<h1>","en":"<h1>"}]',2,'{"it":"`<a>` scorre nel testo senza andare a capo.","en":"`<a>` flows in the text without a line break."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),2,1,'{"it":"Qual è la differenza tra `display: none` e `visibility: hidden`?","en":"What is the difference between `display: none` and `visibility: hidden`?"}','[{"it":"Nessuna","en":"None"},{"it":"Il primo toglie anche lo spazio","en":"The first removes the space too"},{"it":"Il secondo toglie lo spazio","en":"The second removes the space"},{"it":"Il primo è solo per il testo","en":"The first is only for text"}]',1,'{"it":"`visibility: hidden` lascia un buco della stessa misura.","en":"`visibility: hidden` leaves a hole of the same size."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),3,1,'{"it":"Quale valore scorre nel testo e accetta `width`?","en":"Which value flows in the text and accepts `width`?"}','[{"it":"block","en":"block"},{"it":"inline","en":"inline"},{"it":"inline-block","en":"inline-block"},{"it":"flow","en":"flow"}]',2,'{"it":"È una via di mezzo tra `inline` e `block`.","en":"It is halfway between `inline` and `block`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),1,2,'{"it":"Rispetto a cosa si posiziona un elemento `absolute`?","en":"What is an `absolute` element positioned against?"}','[{"it":"Sempre la pagina","en":"Always the page"},{"it":"Il primo antenato posizionato","en":"The nearest positioned ancestor"},{"it":"L’elemento precedente","en":"The previous element"},{"it":"Lo schermo","en":"The screen"}]',1,'{"it":"Per questo si mette `position: relative` sul contenitore.","en":"That is why you set `position: relative` on the container."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),2,2,'{"it":"Quale valore resta fermo durante lo scorrimento della pagina?","en":"Which value stays still while the page scrolls?"}','[{"it":"static","en":"static"},{"it":"relative","en":"relative"},{"it":"fixed","en":"fixed"},{"it":"float","en":"float"}]',2,'{"it":"`fixed` si aggancia allo schermo.","en":"`fixed` is anchored to the screen."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),3,2,'{"it":"Quale proprietà decide cosa sta sopra?","en":"Which property decides what is on top?"}','[{"it":"z-index","en":"z-index"},{"it":"layer","en":"layer"},{"it":"top","en":"top"},{"it":"order-top","en":"order-top"}]',0,'{"it":"Funziona sugli elementi posizionati e sui figli di flex e grid.","en":"It works on positioned elements and on flex and grid children."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),1,2,'{"it":"Chi vince tra `.nota` e `#box` sullo stesso elemento?","en":"Which wins between `.nota` and `#box` on the same element?"}','[{"it":".nota","en":".nota"},{"it":"#box","en":"#box"},{"it":"L’ultima scritta","en":"The last one written"},{"it":"Nessuna","en":"Neither"}]',1,'{"it":"L’`id` ha una specificità più alta della classe.","en":"An `id` has higher specificity than a class."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),2,2,'{"it":"Con la stessa specificità chi vince?","en":"With the same specificity, which wins?"}','[{"it":"La prima scritta","en":"The first written"},{"it":"L’ultima scritta","en":"The last written"},{"it":"La più corta","en":"The shortest"},{"it":"Nessuna","en":"Neither"}]',1,'{"it":"È il senso della parola «cascata».","en":"That is the meaning of the word “cascade”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),3,2,'{"it":"Quale proprietà si eredita?","en":"Which property is inherited?"}','[{"it":"margin","en":"margin"},{"it":"border","en":"border"},{"it":"color","en":"color"},{"it":"padding","en":"padding"}]',2,'{"it":"Il colore del testo passa dai genitori ai figli.","en":"The text colour passes from parents to children."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),1,2,'{"it":"Quale funzione crea una sfumatura?","en":"Which function creates a gradient?"}','[{"it":"linear-gradient()","en":"linear-gradient()"},{"it":"fade()","en":"fade()"},{"it":"blend()","en":"blend()"},{"it":"mix()","en":"mix()"}]',0,'{"it":"Esiste anche `radial-gradient()`.","en":"There is also `radial-gradient()`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),2,2,'{"it":"Che cosa fa il terzo valore di `box-shadow: 0 4px 12px`?","en":"What does the third value of `box-shadow: 0 4px 12px` do?"}','[{"it":"La sfocatura","en":"The blur"},{"it":"Il colore","en":"The colour"},{"it":"Il raggio","en":"The radius"},{"it":"L’opacità","en":"The opacity"}]',0,'{"it":"Più è alto, più l’ombra è morbida.","en":"The higher it is, the softer the shadow."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),3,2,'{"it":"Quale proprietà mette un’ombra al testo?","en":"Which property puts a shadow on text?"}','[{"it":"text-shadow","en":"text-shadow"},{"it":"font-shadow","en":"font-shadow"},{"it":"shadow","en":"shadow"},{"it":"box-shadow","en":"box-shadow"}]',0,'{"it":"`box-shadow` vale per la scatola.","en":"`box-shadow` is for the box."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),1,2,'{"it":"`50%` di che cosa?","en":"`50%` of what?"}','[{"it":"Del contenitore","en":"Of the container"},{"it":"Dello schermo, sempre","en":"Of the screen, always"},{"it":"Del testo","en":"Of the text"},{"it":"Del file","en":"Of the file"}]',0,'{"it":"Le percentuali guardano al genitore.","en":"Percentages look at the parent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),2,2,'{"it":"Quanto vale `100vh`?","en":"What is `100vh`?"}','[{"it":"Tutta l’altezza dello schermo","en":"The full height of the screen"},{"it":"100 pixel","en":"100 pixels"},{"it":"La larghezza","en":"The width"},{"it":"Il doppio del testo","en":"Twice the text"}]',0,'{"it":"`vh` è l’1% dell’altezza della finestra.","en":"`vh` is 1% of the window height."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),3,2,'{"it":"Da che cosa dipende `rem`?","en":"What does `rem` depend on?"}','[{"it":"Dalla radice del documento","en":"On the root of the document"},{"it":"Dal genitore","en":"On the parent"},{"it":"Dallo schermo","en":"On the screen"},{"it":"Da nulla","en":"On nothing"}]',0,'{"it":"`r` sta per root.","en":"`r` stands for root."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),1,1,'{"it":"Che cosa sceglie `ul > li`?","en":"What does `ul > li` pick?"}','[{"it":"I figli diretti","en":"The direct children"},{"it":"Tutti i discendenti","en":"All descendants"},{"it":"Il primo","en":"The first one"},{"it":"Nulla","en":"Nothing"}]',0,'{"it":"Il `>` si ferma al primo livello.","en":"The `>` stops at the first level."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),2,1,'{"it":"Che cosa sceglie `h1 + p`?","en":"What does `h1 + p` pick?"}','[{"it":"Il `p` subito dopo `h1`","en":"The `p` right after `h1`"},{"it":"Tutti i `p`","en":"All `p`s"},{"it":"`h1` e `p`","en":"`h1` and `p`"},{"it":"I `p` dentro `h1`","en":"The `p`s inside `h1`"}]',0,'{"it":"`+` è il fratello adiacente.","en":"`+` is the adjacent sibling."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),3,1,'{"it":"Che cosa significa `[href$=\\".pdf\\"]`?","en":"What does `[href$=\\".pdf\\"]` mean?"}','[{"it":"Finisce con .pdf","en":"Ends with .pdf"},{"it":"Inizia con .pdf","en":"Starts with .pdf"},{"it":"Contiene pdf","en":"Contains pdf"},{"it":"Costa pdf","en":"Costs pdf"}]',0,'{"it":"Il dollaro indica la fine.","en":"The dollar marks the end."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),1,1,'{"it":"Quale pseudo-classe vale mentre premi?","en":"Which pseudo-class applies while pressing?"}','[{"it":":active","en":":active"},{"it":":press","en":":press"},{"it":":hover","en":":hover"},{"it":":down","en":":down"}]',0,'{"it":"`:hover` è il passaggio del mouse.","en":"`:hover` is the mouse passing over."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),2,1,'{"it":"Perché `:focus-visible` è utile?","en":"Why is `:focus-visible` useful?"}','[{"it":"Mostra il focus a chi usa la tastiera","en":"It shows focus to keyboard users"},{"it":"Nasconde il mouse","en":"It hides the mouse"},{"it":"Cambia il font","en":"It changes the font"},{"it":"Blocca il click","en":"It blocks the click"}]',0,'{"it":"Non disturba chi clicca col mouse.","en":"It does not bother those clicking with a mouse."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),3,1,'{"it":"Quando vale `input:invalid`?","en":"When does `input:invalid` apply?"}','[{"it":"Il valore non rispetta le regole","en":"The value breaks the rules"},{"it":"Il campo è vuoto sempre","en":"The field is always empty"},{"it":"Il campo è nascosto","en":"The field is hidden"},{"it":"Mai","en":"Never"}]',0,'{"it":"Dipende da `required`, `type`, `pattern`.","en":"It depends on `required`, `type`, `pattern`."}',NULL);
