INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'typography'),2,1,'{"it":"Che cos’è `65ch`?","en":"What is `65ch`?"}','[{"it":"Circa 65 caratteri","en":"About 65 characters"},{"it":"65 pixel","en":"65 pixels"},{"it":"65% dello schermo","en":"65% of the screen"},{"it":"65 righe","en":"65 lines"}]',0,'{"it":"Si basa sulla larghezza dello zero.","en":"It is based on the width of the zero."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'typography'),3,1,'{"it":"Che cosa carica un font personale?","en":"What loads a custom font?"}','[{"it":"@font-face","en":"@font-face"},{"it":"@import-font","en":"@import-font"},{"it":"font-load","en":"font-load"},{"it":"@text","en":"@text"}]',0,'{"it":"Si indicano nome e file.","en":"You give a name and a file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'overflow'),1,2,'{"it":"Quale valore mette le barre solo se servono?","en":"Which value adds scrollbars only if needed?"}','[{"it":"auto","en":"auto"},{"it":"scroll","en":"scroll"},{"it":"hidden","en":"hidden"},{"it":"bars","en":"bars"}]',0,'{"it":"`scroll` le mostra sempre.","en":"`scroll` always shows them."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'overflow'),2,2,'{"it":"`z-index` funziona su un elemento `static`?","en":"Does `z-index` work on a `static` element?"}','[{"it":"No","en":"No"},{"it":"Sì","en":"Yes"},{"it":"Solo sui link","en":"Only on links"},{"it":"Solo su `body`","en":"Only on `body`"}]',0,'{"it":"Serve un elemento posizionato.","en":"It needs a positioned element."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'overflow'),3,2,'{"it":"Che cosa aggiunge `text-overflow: ellipsis`?","en":"What does `text-overflow: ellipsis` add?"}','[{"it":"I puntini","en":"An ellipsis"},{"it":"Una barra","en":"A scrollbar"},{"it":"Un’ombra","en":"A shadow"},{"it":"Un link","en":"A link"}]',0,'{"it":"Funziona con `overflow: hidden`.","en":"It works with `overflow: hidden`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'components'),1,2,'{"it":"Che cosa toglie la sottolineatura?","en":"What removes the underline?"}','[{"it":"text-decoration: none","en":"text-decoration: none"},{"it":"underline: 0","en":"underline: 0"},{"it":"border: none","en":"border: none"},{"it":"font-style: none","en":"font-style: none"}]',0,'{"it":"I link la hanno di serie.","en":"Links have it by default."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'components'),2,2,'{"it":"Quale cursore indica che si può cliccare?","en":"Which cursor shows you can click?"}','[{"it":"pointer","en":"pointer"},{"it":"hand","en":"hand"},{"it":"click","en":"click"},{"it":"finger","en":"finger"}]',0,'{"it":"`cursor: pointer`.","en":"`cursor: pointer`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'components'),3,2,'{"it":"Quanto dovrebbe essere alto un bottone su telefono?","en":"How high should a button be on phones?"}','[{"it":"Almeno 44px","en":"At least 44px"},{"it":"10px","en":"10px"},{"it":"Non importa","en":"It does not matter"},{"it":"500px","en":"500px"}]',0,'{"it":"Le dita sono meno precise del mouse.","en":"Fingers are less precise than a mouse."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),1,2,'{"it":"Quale proprietà distribuisce lungo l’asse principale?","en":"Which property distributes along the main axis?"}','[{"it":"align-items","en":"align-items"},{"it":"justify-content","en":"justify-content"},{"it":"flex-wrap","en":"flex-wrap"},{"it":"gap","en":"gap"}]',1,'{"it":"Con `flex-direction: row` l’asse principale è orizzontale.","en":"With `flex-direction: row` the main axis is horizontal."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),2,2,'{"it":"Dove si scrive `display: flex`?","en":"Where do you write `display: flex`?"}','[{"it":"Sul contenitore","en":"On the container"},{"it":"Su ogni figlio","en":"On each child"},{"it":"Su `html`","en":"On `html`"},{"it":"Sul primo figlio","en":"On the first child"}]',0,'{"it":"Il contenitore diventa flex e i figli diretti ne seguono le regole.","en":"The container becomes flex and its direct children follow its rules."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),3,2,'{"it":"Come centri un elemento in entrambi i sensi?","en":"How do you centre an element both ways?"}','[{"it":"margin: center","en":"margin: center"},{"it":"align: middle","en":"align: middle"},{"it":"`justify-content` e `align-items` su `center`","en":"`justify-content` and `align-items` set to `center`"},{"it":"float: center","en":"float: center"}]',2,'{"it":"Sono i due assi del contenitore flex.","en":"They are the two axes of the flex container."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),1,2,'{"it":"Che cos’è l’unità `fr`?","en":"What is the `fr` unit?"}','[{"it":"Una frazione dello spazio libero","en":"A fraction of the free space"},{"it":"Un pixel","en":"A pixel"},{"it":"La larghezza del font","en":"The width of the font"},{"it":"Un frame","en":"A frame"}]',0,'{"it":"`1fr 2fr` divide lo spazio in tre parti: una e due.","en":"`1fr 2fr` splits the space into three parts: one and two."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),2,2,'{"it":"Come scrivi tre colonne uguali?","en":"How do you write three equal columns?"}','[{"it":"columns: 3","en":"columns: 3"},{"it":"grid-template-columns: repeat(3, 1fr)","en":"grid-template-columns: repeat(3, 1fr)"},{"it":"grid: 3","en":"grid: 3"},{"it":"flex: 3","en":"flex: 3"}]',1,'{"it":"`repeat()` evita di ripetere `1fr 1fr 1fr`.","en":"`repeat()` saves writing `1fr 1fr 1fr`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),3,2,'{"it":"Che cosa fa `grid-column: 1 / 3`?","en":"What does `grid-column: 1 / 3` do?"}','[{"it":"Occupa tre colonne","en":"It takes three columns"},{"it":"Va dalla linea 1 alla linea 3","en":"It goes from line 1 to line 3"},{"it":"Divide per tre","en":"It divides by three"},{"it":"Crea tre righe","en":"It creates three rows"}]',1,'{"it":"Le linee sono i bordi tra le colonne: l’elemento occupa due colonne.","en":"Lines are the edges between columns: the element takes two columns."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),1,2,'{"it":"Che cosa significa *mobile first*?","en":"What does *mobile first* mean?"}','[{"it":"Sviluppare solo per telefoni","en":"Developing for phones only"},{"it":"Partire dal telefono e aggiungere regole per gli schermi grandi","en":"Starting from the phone and adding rules for large screens"},{"it":"Usare un’app","en":"Using an app"},{"it":"Nascondere il desktop","en":"Hiding the desktop"}]',1,'{"it":"Si usano media query con `min-width`.","en":"It uses media queries with `min-width`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),2,2,'{"it":"Quando si applica `@media (min-width: 700px)`?","en":"When does `@media (min-width: 700px)` apply?"}','[{"it":"Sotto i 700px","en":"Under 700px"},{"it":"Da 700px in su","en":"From 700px up"},{"it":"Solo a 700px","en":"Only at 700px"},{"it":"Sempre","en":"Always"}]',1,'{"it":"`min-width` significa «almeno questa larghezza».","en":"`min-width` means “at least this width”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),3,2,'{"it":"Che cosa fa `clamp(1rem, 4vw, 2rem)`?","en":"What does `clamp(1rem, 4vw, 2rem)` do?"}','[{"it":"Sceglie a caso","en":"Picks at random"},{"it":"Tiene `4vw` tra 1rem e 2rem","en":"Keeps `4vw` between 1rem and 2rem"},{"it":"Somma i valori","en":"Adds the values"},{"it":"Blocca il font","en":"Locks the font"}]',1,'{"it":"Un valore fluido, con un minimo e un massimo.","en":"A fluid value, with a minimum and a maximum."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),1,2,'{"it":"Come si dichiara una variabile CSS?","en":"How do you declare a CSS variable?"}','[{"it":"$brand: red","en":"$brand: red"},{"it":"--brand: red","en":"--brand: red"},{"it":"@brand: red","en":"@brand: red"},{"it":"var brand = red","en":"var brand = red"}]',1,'{"it":"Inizia con due trattini e si dichiara dentro un selettore.","en":"It starts with two dashes and is declared inside a selector."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),2,2,'{"it":"Dove si dichiarano di solito le variabili globali?","en":"Where are global variables usually declared?"}','[{"it":":root","en":":root"},{"it":"head","en":"head"},{"it":"body::before","en":"body::before"},{"it":"@global","en":"@global"}]',0,'{"it":"`:root` è l’elemento radice, cioè `html`.","en":"`:root` is the root element, that is `html`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),3,2,'{"it":"A cosa serve il secondo argomento di `var()`?","en":"What is the second argument of `var()` for?"}','[{"it":"Al tipo","en":"The type"},{"it":"Al valore di riserva","en":"The fallback value"},{"it":"Alla durata","en":"The duration"},{"it":"All’unità","en":"The unit"}]',1,'{"it":"Si usa se la variabile non è definita.","en":"It is used if the variable is not defined."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),1,3,'{"it":"Quale proprietà anima il passaggio tra due stati?","en":"Which property animates the change between two states?"}','[{"it":"animation-state","en":"animation-state"},{"it":"transition","en":"transition"},{"it":"change","en":"change"},{"it":"keyframes","en":"keyframes"}]',1,'{"it":"Si scrive sullo stato di partenza, con durata e curva.","en":"It goes on the starting state, with duration and curve."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),2,3,'{"it":"Con che cosa si definiscono i passaggi di un’animazione?","en":"What defines the steps of an animation?"}','[{"it":"@media","en":"@media"},{"it":"@keyframes","en":"@keyframes"},{"it":"@animate","en":"@animate"},{"it":"@steps","en":"@steps"}]',1,'{"it":"Poi si applica con la proprietà `animation`.","en":"It is then applied with the `animation` property."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),3,3,'{"it":"Quale media query rispetta chi chiede meno movimento?","en":"Which media query respects those asking for less motion?"}','[{"it":"prefers-reduced-motion","en":"prefers-reduced-motion"},{"it":"no-animation","en":"no-animation"},{"it":"motion: off","en":"motion: off"},{"it":"reduced-data","en":"reduced-data"}]',0,'{"it":"Il sistema operativo la espone come preferenza di accessibilità.","en":"The operating system exposes it as an accessibility preference."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),1,3,'{"it":"Che cosa serve sempre a `::before`?","en":"What does `::before` always need?"}','[{"it":"content","en":"content"},{"it":"display","en":"display"},{"it":"width","en":"width"},{"it":"color","en":"color"}]',0,'{"it":"Senza `content` non viene creato nulla.","en":"Without `content` nothing is created."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),2,3,'{"it":"Quali elementi sceglie `li:nth-child(even)`?","en":"Which elements does `li:nth-child(even)` pick?"}','[{"it":"I pari","en":"The even ones"},{"it":"I dispari","en":"The odd ones"},{"it":"Il primo","en":"The first"},{"it":"Tutti","en":"All of them"}]',0,'{"it":"`even` è pari, `odd` dispari.","en":"`even` is even, `odd` is odd."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),3,3,'{"it":"Come si scrive uno pseudo-elemento?","en":"How is a pseudo-element written?"}','[{"it":"Con `::`","en":"With `::`"},{"it":"Con `#`","en":"With `#`"},{"it":"Con `$`","en":"With `$`"},{"it":"Con `@`","en":"With `@`"}]',0,'{"it":"Due punti doppi lo distinguono da una pseudo-classe.","en":"The double colon sets it apart from a pseudo-class."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),1,3,'{"it":"Che cosa sceglie `.card:has(img)`?","en":"What does `.card:has(img)` pick?"}','[{"it":"Le card con un’immagine","en":"Cards with an image"},{"it":"Le immagini","en":"The images"},{"it":"Tutte le card","en":"All cards"},{"it":"Nulla","en":"Nothing"}]',0,'{"it":"Si guarda dentro, ma viene scelto il genitore.","en":"It looks inside, but the parent is picked."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),2,3,'{"it":"A che cosa guarda `@container`?","en":"What does `@container` look at?"}','[{"it":"Al contenitore","en":"The container"},{"it":"Allo schermo","en":"The screen"},{"it":"Al font","en":"The font"},{"it":"Al server","en":"The server"}]',0,'{"it":"Un componente si adatta allo spazio che ha davvero.","en":"A component adapts to the space it really has."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),3,3,'{"it":"Il CSS moderno può annidare le regole?","en":"Can modern CSS nest rules?"}','[{"it":"Sì","en":"Yes"},{"it":"No, solo SCSS","en":"No, only SCSS"},{"it":"Solo in `@media`","en":"Only in `@media`"},{"it":"Solo con JavaScript","en":"Only with JavaScript"}]',0,'{"it":"Il nesting ora è nel CSS nativo, con `&`.","en":"Nesting is now in native CSS, with `&`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transitions'),1,2,'{"it":"Dove si scrive `transition`?","en":"Where does `transition` go?"}','[{"it":"Sullo stato normale","en":"On the normal state"},{"it":"Solo su `:hover`","en":"Only on `:hover`"},{"it":"Nell’HTML","en":"In the HTML"},{"it":"In `@media`","en":"In `@media`"}]',0,'{"it":"Così l’effetto vale nei due sensi.","en":"So the effect works both ways."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transitions'),2,2,'{"it":"Quanto dura `.3s`?","en":"How long is `.3s`?"}','[{"it":"300 millisecondi","en":"300 milliseconds"},{"it":"3 secondi","en":"3 seconds"},{"it":"30 secondi","en":"30 seconds"},{"it":"3 minuti","en":"3 minutes"}]',0,'{"it":"Tra 150 e 300ms un’interfaccia sembra rapida.","en":"Between 150 and 300ms an interface feels quick."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transitions'),3,2,'{"it":"Si può animare `display`?","en":"Can you animate `display`?"}','[{"it":"Di solito no","en":"Usually not"},{"it":"Sempre","en":"Always"},{"it":"Solo in rosso","en":"Only in red"},{"it":"Solo nei link","en":"Only in links"}]',0,'{"it":"Si anima ciò che ha valori intermedi, come `opacity`.","en":"You animate what has in-between values, like `opacity`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transforms'),1,2,'{"it":"Quale funzione sposta?","en":"Which function moves?"}','[{"it":"translate()","en":"translate()"},{"it":"move()","en":"move()"},{"it":"shift()","en":"shift()"},{"it":"go()","en":"go()"}]',0,'{"it":"Esistono `translateX` e `translateY`.","en":"There are `translateX` and `translateY`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transforms'),2,2,'{"it":"`transform` sposta gli altri elementi?","en":"Does `transform` move other elements?"}','[{"it":"No","en":"No"},{"it":"Sì","en":"Yes"},{"it":"Solo i fratelli","en":"Only siblings"},{"it":"Solo il genitore","en":"Only the parent"}]',0,'{"it":"Lo spazio occupato resta quello di prima.","en":"The space taken stays as before."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transforms'),3,2,'{"it":"Che cosa cambia `transform-origin`?","en":"What does `transform-origin` change?"}','[{"it":"Il punto di riferimento","en":"The reference point"},{"it":"La durata","en":"The duration"},{"it":"Il colore","en":"The colour"},{"it":"La curva","en":"The curve"}]',0,'{"it":"Una rotazione da un angolo sembra una porta.","en":"A rotation from a corner looks like a door."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'keyframes'),1,2,'{"it":"Che cosa definisce `@keyframes`?","en":"What does `@keyframes` define?"}','[{"it":"Le tappe di un’animazione","en":"The stages of an animation"},{"it":"Un font","en":"A font"},{"it":"Una variabile","en":"A variable"},{"it":"Una media query","en":"A media query"}]',0,'{"it":"Si usa poi con `animation`.","en":"It is then used with `animation`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'keyframes'),2,2,'{"it":"Come si ripete per sempre?","en":"How does it repeat for ever?"}','[{"it":"infinite","en":"infinite"},{"it":"loop","en":"loop"},{"it":"always","en":"always"},{"it":"repeat","en":"repeat"}]',0,'{"it":"Oppure un numero di giri.","en":"Or a number of rounds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'keyframes'),3,2,'{"it":"`from` e `to` equivalgono a…","en":"`from` and `to` are the same as…"}','[{"it":"0% e 100%","en":"0% e 100%"},{"it":"1 e 2","en":"1 e 2"},{"it":"start e end","en":"start e end"},{"it":"A e B","en":"A e B"}]',0,'{"it":"Per le tappe intermedie servono le percentuali.","en":"In-between stages need percentages."}',NULL);
