INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'timing'),2,3,'{"it":"Che cosa fa `forwards`?","en":"What does `forwards` do?"}','[{"it":"Tiene l’ultima tappa","en":"Keeps the last stage"},{"it":"Salta avanti","en":"Skips ahead"},{"it":"Va più veloce","en":"Goes faster"},{"it":"Ripete","en":"Repeats"}]',0,'{"it":"Senza, l’elemento torna com’era.","en":"Without it, the element goes back to how it was."}',NULL);
