INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),1,2,'{"it":"Il browser sa leggere un file `.scss`?","en":"Can the browser read a `.scss` file?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"No, va compilato in CSS","en":"No, it must be compiled to CSS"},{"it":"Solo Chrome","en":"Only Chrome"},{"it":"Solo con JavaScript attivo","en":"Only with JavaScript on"}]',1,'{"it":"Il compilatore trasforma SCSS in CSS.","en":"The compiler turns SCSS into CSS."}',NULL);
