INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),3,2,'{"it":"Perché non annidare troppo?","en":"Why not nest too deep?"}','[{"it":"Il compilatore si blocca","en":"The compiler stops"},{"it":"I selettori diventano lunghi e difficili da sovrascrivere","en":"Selectors become long and hard to override"},{"it":"Il browser rallenta del tutto","en":"The browser stalls completely"},{"it":"Non è permesso","en":"It is not allowed"}]',1,'{"it":"Lo stesso annidamento aumenta anche la specificità.","en":"Nesting also raises specificity."}',NULL);
