INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),2,2,'{"it":"Quale vantaggio hanno i mixin rispetto a `@extend`?","en":"What advantage do mixins have over `@extend`?"}','[{"it":"Accettano parametri","en":"They accept parameters"},{"it":"Sono più corti","en":"They are shorter"},{"it":"Non si compilano","en":"They are not compiled"},{"it":"Funzionano in HTML","en":"They work in HTML"}]',0,'{"it":"Un mixin produce regole diverse a seconda degli argomenti.","en":"A mixin produces different rules depending on its arguments."}',NULL);
