INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),1,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":["<!doctype html>","<html lang=\\"it\\">","<head>","  <title>Fucina</title>","</head>","<body>","  <h1>Ciao!</h1>","</body>","</html>"],"why":{"it":"Prima il doctype, poi `html` con dentro `head` e `body`.","en":"First the doctype, then `html` holding `head` and `body`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`<title>` si scrive dentro `<head>`","en":"`<title>` goes inside `<head>`"},true],[{"it":"Quello che si vede nella pagina sta in `<body>`","en":"What you see on the page lives in `<body>`"},true],[{"it":"Una pagina può avere due `<body>`","en":"A page can have two `<body>` elements"},false],[{"it":"`<!doctype html>` è l’ultima riga del file","en":"`<!doctype html>` is the last line of the file"},false],[{"it":"I tag di solito si aprono e si chiudono","en":"Tags usually open and close"},true]],"why":{"it":"`head` descrive la pagina, `body` la mostra.","en":"`head` describes the page, `body` shows it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'structure'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<html>","  <body>","    <h1>Benvenuto</h2>","  </body>","</html>"],"bug":2,"fix":"    <h1>Benvenuto</h1>","why":{"it":"Un tag si chiude con lo stesso nome con cui si apre.","en":"A tag closes with the same name it opens with."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["<h1>",{"it":"Titolo principale","en":"Main heading"}],["<p>",{"it":"Paragrafo","en":"Paragraph"}],["<strong>",{"it":"Testo importante","en":"Important text"}],["<em>",{"it":"Testo enfatizzato","en":"Emphasised text"}],["<br>",{"it":"A capo","en":"Line break"}]],"why":{"it":"Ogni tag dice che cosa è il testo, non solo come appare.","en":"Every tag says what the text is, not just how it looks."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<___>Le novità</h2>\\n<p>Oggi è <___>importante</strong>.</p>","gaps":["h2","strong"],"extra":["p","b","h1"],"why":{"it":"Il nome di apertura deve coincidere con quello di chiusura.","en":"The opening name must match the closing one."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'text'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`<h1>` è il titolo più importante","en":"`<h1>` is the most important heading"},true],[{"it":"`<h6>` è più grande di `<h1>`","en":"`<h6>` is bigger than `<h1>`"},false],[{"it":"`<br>` non ha un tag di chiusura","en":"`<br>` has no closing tag"},true],[{"it":"I titoli si scelgono in base alla grandezza che piace","en":"Headings are chosen by the size you like"},false],[{"it":"`<p>` crea un paragrafo","en":"`<p>` creates a paragraph"},true]],"why":{"it":"I titoli seguono la struttura del testo: la grandezza si cambia con il CSS.","en":"Headings follow the structure of the text: size is changed with CSS."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<a ___=\\"https://example.com\\">Scopri</a>\\n<img ___=\\"logo.png\\" ___=\\"Il logo\\">","gaps":["href","src","alt"],"extra":["link","title","url"],"why":{"it":"`href` è la destinazione, `src` il file, `alt` la descrizione.","en":"`href` is the destination, `src` the file, `alt` the description."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'links'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<p>Guarda la foto:</p>","<img href=\\"gatto.jpg\\" alt=\\"Un gatto\\">","<a href=\\"info.html\\">Altre info</a>"],"bug":1,"fix":"<img src=\\"gatto.jpg\\" alt=\\"Un gatto\\">","why":{"it":"Le immagini usano `src`, i link usano `href`.","en":"Images use `src`, links use `href`."}}');
