INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'lists'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`<ul>` è una lista puntata","en":"`<ul>` is a bullet list"},true],[{"it":"`<ol>` è una lista numerata","en":"`<ol>` is a numbered list"},true],[{"it":"`<li>` può stare fuori da una lista","en":"`<li>` can stay outside a list"},false],[{"it":"I numeri di `<ol>` vanno scritti a mano","en":"The numbers of `<ol>` must be typed by hand"},false],[{"it":"Una lista può contenerne un’altra","en":"A list can contain another one"},true]],"why":{"it":"Il browser numera `ol`, tu scrivi solo gli `li`.","en":"The browser numbers `ol`, you only write the `li` items."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'lists'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<ul>","  <li>Pane</li>","  <p>Latte</p>","  <li>Uova</li>","</ul>"],"bug":2,"fix":"  <li>Latte</li>","why":{"it":"Dentro `ul` e `ol` ci vanno solo elementi `li`.","en":"Only `li` items go directly inside `ul` and `ol`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'tables'),1,'order','{"prompt":{"it":"Costruisci la tabella.","en":"Build the table."},"lines":["<table>","  <tr>","    <th>Nome</th>","    <th>Punti</th>","  </tr>","  <tr>","    <td>Sav</td>","    <td>42</td>","  </tr>","</table>"],"why":{"it":"Una riga `tr` contiene le celle: `th` per le intestazioni, `td` per i dati.","en":"A `tr` row holds the cells: `th` for headers, `td` for data."}}');
