INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'tables'),3,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<tr>\\n  <td ___=\\"2\\">Totale</td>\\n  <td>10</td>\\n</___>","gaps":["colspan","tr"],"extra":["rowspan","td","span"],"why":{"it":"`colspan` allarga una cella su più colonne.","en":"`colspan` stretches a cell over several columns."}}');
