INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'semantic'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["<header>",{"it":"La testata","en":"The page header"}],["<nav>",{"it":"I link di navigazione","en":"The navigation links"}],["<main>",{"it":"Il contenuto principale","en":"The main content"}],["<article>",{"it":"Un contenuto autonomo","en":"A self-contained piece"}],["<aside>",{"it":"Un contenuto laterale","en":"Side content"}],["<footer>",{"it":"Il piè di pagina","en":"The page footer"}]],"why":{"it":"I tag semantici spiegano la pagina anche a chi non la vede.","en":"Semantic tags explain the page even to those who cannot see it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'semantic'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Ci dovrebbe essere un solo `<main>` visibile","en":"There should be just one visible `<main>`"},true],[{"it":"`<div>` ha un significato preciso","en":"`<div>` has a precise meaning"},false],[{"it":"`<section>` raggruppa contenuti su un tema","en":"`<section>` groups content on a topic"},true],[{"it":"I tag semantici aiutano i lettori di schermo","en":"Semantic tags help screen readers"},true],[{"it":"`<nav>` serve per le immagini","en":"`<nav>` is for images"},false]],"why":{"it":"`div` è un contenitore neutro: usalo solo se non esiste un tag migliore.","en":"`div` is a neutral container: use it only when no better tag exists."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'rich-forms'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<fieldset>\\n  <___>Piano</legend>\\n  <input type=\\"___\\" name=\\"piano\\">\\n  <input type=\\"radio\\" ___=\\"piano\\">\\n</fieldset>","gaps":["legend","radio","name"],"extra":["label","checkbox","id"],"why":{"it":"I radio con lo stesso `name` formano un gruppo: se ne sceglie uno solo.","en":"Radios with the same `name` form a group: only one can be picked."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'rich-forms'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["min / max",{"it":"Limiti di un numero","en":"Limits of a number"}],["pattern",{"it":"Regola con un’espressione regolare","en":"Rule with a regular expression"}],["<select>",{"it":"Menu a tendina","en":"Drop-down menu"}],["<textarea>",{"it":"Testo su più righe","en":"Multi-line text"}],["<datalist>",{"it":"Suggerimenti per un campo","en":"Suggestions for a field"}]],"why":{"it":"Il browser sa validare molti campi senza una riga di JavaScript.","en":"The browser can validate many fields without a line of JavaScript."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'rich-forms'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Le checkbox permettono più scelte","en":"Checkboxes allow several choices"},true],[{"it":"Due radio con `name` diversi si escludono","en":"Two radios with different `name` exclude each other"},false],[{"it":"`required` blocca l’invio se il campo è vuoto","en":"`required` blocks sending when the field is empty"},true],[{"it":"La validazione del browser basta da sola sul server","en":"Browser validation alone is enough for the server"},false],[{"it":"`<fieldset>` raggruppa campi correlati","en":"`<fieldset>` groups related fields"},true]],"why":{"it":"Il browser aiuta chi compila, ma il server deve sempre ricontrollare.","en":"The browser helps people filling in, but the server must always check again."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<video src=\\"film.mp4\\" ___></video>\\n<img src=\\"foto.jpg\\" alt=\\"Mare\\" loading=\\"___\\">","gaps":["controls","lazy"],"extra":["play","slow","autoload"],"why":{"it":"`controls` mostra i pulsanti, `loading=\\"lazy\\"` rimanda il caricamento.","en":"`controls` shows the buttons, `loading=\\"lazy\\"` delays the loading."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),2,'order','{"prompt":{"it":"Costruisci l’immagine responsive.","en":"Build the responsive image."},"lines":["<picture>","  <source media=\\"(min-width: 800px)\\" srcset=\\"grande.jpg\\">","  <img src=\\"piccola.jpg\\" alt=\\"Paesaggio\\">","</picture>"],"why":{"it":"Il browser sceglie la prima `source` adatta; `img` è la riserva e va per ultima.","en":"The browser picks the first fitting `source`; `img` is the fallback and comes last."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`srcset` offre più versioni di un’immagine","en":"`srcset` offers several versions of an image"},true],[{"it":"`<audio>` può avere dei `controls`","en":"`<audio>` can have `controls`"},true],[{"it":"`alt` serve solo se l’immagine è grande","en":"`alt` is only needed for large images"},false],[{"it":"`loading=\\"lazy\\"` rende la pagina più pesante","en":"`loading=\\"lazy\\"` makes the page heavier"},false],[{"it":"`<figcaption>` è la didascalia di `<figure>`","en":"`<figcaption>` is the caption of `<figure>`"},true]],"why":{"it":"Immagini giuste e caricate al momento giusto rendono la pagina veloce.","en":"The right images, loaded at the right moment, make a page fast."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<h1>Il negozio</h1>","<img src=\\"scarpe.jpg\\">","<button>Compra</button>"],"bug":1,"fix":"<img src=\\"scarpe.jpg\\" alt=\\"Scarpe rosse\\">","why":{"it":"Senza `alt`, chi usa un lettore di schermo non sa che cosa c’è nell’immagine.","en":"Without `alt`, screen reader users cannot know what the image shows."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<button ___=\\"Chiudi\\">✕</button>\\n<nav aria-___=\\"Menu principale\\">…</nav>","gaps":["aria-label","label"],"extra":["title","name","alt"],"why":{"it":"`aria-label` dà un nome a ciò che non ha testo visibile.","en":"`aria-label` names what has no visible text."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un `<button>` si usa anche da tastiera","en":"A `<button>` also works from the keyboard"},true],[{"it":"Un `<div>` cliccabile è accessibile come un bottone","en":"A clickable `<div>` is as accessible as a button"},false],[{"it":"Il testo deve avere abbastanza contrasto","en":"Text must have enough contrast"},true],[{"it":"Va bene saltare da `<h1>` a `<h4>`","en":"It is fine to jump from `<h1>` to `<h4>`"},false],[{"it":"Il colore non deve essere l’unico segnale","en":"Colour must not be the only signal"},true]],"why":{"it":"Prima i tag nativi: ARIA serve solo dove l’HTML non basta.","en":"Native tags first: ARIA is only for where HTML is not enough."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),1,'order','{"prompt":{"it":"Ordina la testata del documento.","en":"Order the head of the document."},"lines":["<head>","  <meta charset=\\"utf-8\\">","  <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\">","  <title>Fucina</title>","</head>"],"why":{"it":"`charset` va per primo: il browser deve sapere subito come leggere il testo.","en":"`charset` comes first: the browser must know at once how to read the text."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["charset",{"it":"La codifica del testo","en":"The text encoding"}],["viewport",{"it":"L’adattamento ai telefoni","en":"Fitting mobile screens"}],["description",{"it":"Il riassunto per i motori di ricerca","en":"The summary for search engines"}],["<details>",{"it":"Contenuto che si apre e si chiude","en":"Content that opens and closes"}],["<dialog>",{"it":"Una finestra di dialogo","en":"A dialog window"}]],"why":{"it":"I metadati parlano al browser, non al lettore.","en":"Metadata speaks to the browser, not to the reader."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),3,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<___>\\n  <summary>Spoiler</___>\\n  <p>Vince la forgia.</p>\\n</details>","gaps":["details","summary"],"extra":["dialog","title"],"why":{"it":"`details` si apre da solo quando tocchi il suo `summary`: niente JavaScript.","en":"`details` opens by itself when you tap its `summary`: no JavaScript."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["p",{"it":"Tutti i paragrafi","en":"All paragraphs"}],[".nota",{"it":"La classe nota","en":"The class nota"}],["#box",{"it":"L’id box","en":"The id box"}],["nav a",{"it":"I link dentro nav","en":"Links inside nav"}],["a:hover",{"it":"Il link sotto al mouse","en":"The link under the mouse"}]],"why":{"it":"Punto per le classi, cancelletto per gli id, spazio per «dentro».","en":"A dot for classes, a hash for ids, a space for “inside”."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___nota { color: red; }\\n___box { width: 200px; }\\nnav ___ { color: navy; }","gaps":[".","#","a"],"extra":["*","@",":"],"why":{"it":"`.` sceglie una classe, `#` un id.","en":"`.` picks a class, `#` an id."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".card {","  color: navy","  padding: 12px;","}"],"bug":1,"fix":"  color: navy;","why":{"it":"Ogni dichiarazione finisce con il punto e virgola: senza, si perde anche quella dopo.","en":"Every declaration ends with a semicolon: without it, the next one is lost too."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),1,'tune','{"prompt":{"it":"Copia il bersaglio: stesso colore e stessa trasparenza.","en":"Copy the target: same colour and same transparency."},"layout":"box","items":1,"props":[{"prop":"background-color","choices":["#FF5B2E","#3D9BFF","#12B886","#FFC53D"],"target":"#3D9BFF"},{"prop":"opacity","unit":"","min":0.25,"max":1,"step":0.25,"target":0.5,"start":1}],"base":[],"itemBase":{"width":"55%","height":"60%","border-radius":"16px"},"why":{"it":"`opacity` va da 0 (invisibile) a 1 (pieno).","en":"`opacity` goes from 0 (invisible) to 1 (solid)."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["#FF0000",{"it":"Rosso, in esadecimale","en":"Red, in hexadecimal"}],["rgb(0 0 255)",{"it":"Blu, in RGB","en":"Blue, in RGB"}],["hsl(120 100% 25%)",{"it":"Verde, in HSL","en":"Green, in HSL"}],["transparent",{"it":"Nessun colore","en":"No colour"}]],"why":{"it":"Lo stesso colore si può scrivere in molti modi.","en":"The same colour can be written in many ways."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`color` cambia il colore del testo","en":"`color` changes the text colour"},true],[{"it":"`2rem` con base 16px vale 32px","en":"`2rem` on a 16px base is 32px"},true],[{"it":"`font-color` è una proprietà CSS","en":"`font-color` is a CSS property"},false],[{"it":"`#000` è il bianco","en":"`#000` is white"},false],[{"it":"`font-weight: 700` è il grassetto","en":"`font-weight: 700` is bold"},true]],"why":{"it":"In esadecimale `#000` è nero, `#fff` è bianco.","en":"In hexadecimal `#000` is black, `#fff` is white."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),1,'tune','{"prompt":{"it":"Muovi i comandi finché la tua figura è uguale al bersaglio.","en":"Move the controls until your figure matches the target."},"layout":"box","items":1,"props":[{"prop":"padding","unit":"px","min":0,"max":40,"step":4,"target":24},{"prop":"border-radius","unit":"px","min":0,"max":48,"step":4,"target":28},{"prop":"border-width","unit":"px","min":0,"max":12,"step":2,"target":6}],"base":{"padding":"10px"},"itemBase":{"border-style":"solid","border-color":"#1B1B4B","background-clip":"content-box","background-color":"#FF5B2E","width":"60%","height":"70%","box-sizing":"border-box"},"why":{"it":"Il `padding` spinge il contenuto verso l’interno, il bordo lo racchiude.","en":"`padding` pushes the content inwards, the border wraps it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),2,'order','{"prompt":{"it":"Metti gli strati in ordine, dall’interno verso l’esterno.","en":"Put the layers in order, from the inside out."},"lines":["content","padding","border","margin"],"why":{"it":"Contenuto, spazio interno, bordo, spazio esterno.","en":"Content, inner space, border, outer space."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Il `margin` è lo spazio esterno","en":"`margin` is the outer space"},true],[{"it":"Con `border-box` il padding allarga la scatola","en":"With `border-box` padding widens the box"},false],[{"it":"`margin: 0 auto` centra un blocco con una larghezza","en":"`margin: 0 auto` centres a block with a width"},true],[{"it":"`padding` accetta valori negativi","en":"`padding` accepts negative values"},false],[{"it":"`border-radius` arrotonda gli angoli","en":"`border-radius` rounds the corners"},true]],"why":{"it":"Con `border-box` la larghezza comprende padding e bordo.","en":"With `border-box` the width includes padding and border."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),1,'tune','{"prompt":{"it":"Fai stare le tre scatole una accanto all’altra, come nel bersaglio.","en":"Put the three boxes side by side, like in the target."},"layout":"box","items":3,"props":[{"prop":"display","choices":["block","inline-block","none"],"target":"inline-block"},{"prop":"margin-right","unit":"px","min":0,"max":24,"step":4,"target":12}],"base":[],"itemBase":{"width":"26%","height":"44px","background-color":"#12B886","border-radius":"10px","margin-bottom":"6px"},"why":{"it":"`inline-block` sta in riga ma accetta larghezza e altezza.","en":"`inline-block` stays in line but accepts width and height."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["block",{"it":"Occupa tutta la riga","en":"Takes the whole row"}],["inline",{"it":"Sta nel testo, ignora la larghezza","en":"Sits in the text, ignores width"}],["inline-block",{"it":"In riga, ma con larghezza e altezza","en":"In line, but with width and height"}],["none",{"it":"Sparisce del tutto","en":"Disappears completely"}]],"why":{"it":"`display` decide come un elemento occupa lo spazio.","en":"`display` decides how an element takes up space."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`<div>` è un blocco per natura","en":"`<div>` is a block by nature"},true],[{"it":"`<span>` è in riga per natura","en":"`<span>` is inline by nature"},true],[{"it":"`display: none` lascia il posto vuoto","en":"`display: none` leaves an empty gap"},false],[{"it":"`visibility: hidden` lascia il posto vuoto","en":"`visibility: hidden` leaves an empty gap"},true],[{"it":"`width` funziona su `display: inline`","en":"`width` works on `display: inline`"},false]],"why":{"it":"`none` toglie l’elemento dalla pagina, `hidden` lo rende solo invisibile.","en":"`none` removes the element from the page, `hidden` only makes it invisible."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),1,'tune','{"prompt":{"it":"Porta il quadrato nel punto del bersaglio.","en":"Move the square to the spot of the target."},"layout":"box","items":1,"props":[{"prop":"top","unit":"px","min":0,"max":120,"step":10,"target":70},{"prop":"left","unit":"px","min":0,"max":180,"step":10,"target":120}],"base":{"position":"relative"},"itemBase":{"position":"absolute","width":"48px","height":"48px","background-color":"#FF4D8D","border-radius":"12px"},"why":{"it":"Con `position: absolute`, `top` e `left` contano dal contenitore posizionato.","en":"With `position: absolute`, `top` and `left` count from the positioned container."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["static",{"it":"Il flusso normale","en":"The normal flow"}],["relative",{"it":"Si sposta dal suo posto","en":"Moves from its own place"}],["absolute",{"it":"Esce dal flusso","en":"Leaves the flow"}],["fixed",{"it":"Resta fermo sullo schermo","en":"Stays still on the screen"}],["sticky",{"it":"Si aggancia scorrendo","en":"Sticks while scrolling"}]],"why":{"it":"`position` cambia il punto di riferimento di un elemento.","en":"`position` changes the reference point of an element."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".padre {","  position: static;","}",".figlio {","  position: absolute;","  top: 0;","}"],"bug":1,"fix":"  position: relative;","why":{"it":"Un elemento `absolute` si aggancia al primo antenato posizionato: `static` non conta.","en":"An `absolute` element anchors to the first positioned ancestor: `static` does not count."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),1,'order','{"prompt":{"it":"Ordina dal selettore più debole al più forte.","en":"Order from the weakest selector to the strongest."},"lines":["p",".nota","#box","style=\\"…\\"","!important"],"why":{"it":"Tag, classe, id, stile in linea e infine `!important`.","en":"Tag, class, id, inline style and finally `!important`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"A parità di forza vince la regola scritta dopo","en":"With equal strength the rule written last wins"},true],[{"it":"Un id batte dieci classi","en":"One id beats ten classes"},true],[{"it":"`color` si eredita dai genitori","en":"`color` is inherited from parents"},true],[{"it":"`padding` si eredita dai genitori","en":"`padding` is inherited from parents"},false],[{"it":"`!important` va usato ovunque","en":"`!important` should be used everywhere"},false]],"why":{"it":"Cascata: prima conta la specificità, poi l’ordine.","en":"Cascade: specificity counts first, then order."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),3,'bug','{"prompt":{"it":"Il testo dovrebbe essere blu: tocca la riga che lo impedisce.","en":"The text should be blue: tap the line that prevents it."},"lines":["p.nota { color: red; }",".nota { color: blue; }"],"bug":0,"fix":"p { color: red; }","why":{"it":"`p.nota` è più specifico di `.nota`, anche se è scritto prima.","en":"`p.nota` is more specific than `.nota`, even if it comes first."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),1,'tune','{"prompt":{"it":"Disponi le scatole come nel bersaglio.","en":"Arrange the boxes like the target."},"layout":"flex","items":3,"props":[{"prop":"justify-content","choices":["flex-start","center","space-between","flex-end"],"target":"space-between"},{"prop":"align-items","choices":["flex-start","center","flex-end"],"target":"center"}],"base":[],"itemBase":[],"why":{"it":"`justify-content` lavora sull’asse principale, `align-items` su quello trasversale.","en":"`justify-content` works on the main axis, `align-items` on the cross axis."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),2,'tune','{"prompt":{"it":"Ora in colonna, con più respiro.","en":"Now in a column, with more room."},"layout":"flex","items":3,"props":[{"prop":"flex-direction","choices":["row","column","row-reverse"],"target":"column"},{"prop":"align-items","choices":["flex-start","center","flex-end"],"target":"flex-end"},{"prop":"gap","unit":"px","min":0,"max":24,"step":4,"target":12}],"base":[],"itemBase":[],"why":{"it":"Con `flex-direction: column` gli assi si scambiano: `align-items` ora è orizzontale.","en":"With `flex-direction: column` the axes swap: `align-items` is now horizontal."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),3,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":".barra {\\n  display: ___;\\n  ___: center;\\n  gap: 12px;\\n}","gaps":["flex","justify-content"],"extra":["block","text-align","float"],"why":{"it":"`display: flex` si scrive sul contenitore, non sugli elementi.","en":"`display: flex` goes on the container, not on the items."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),1,'tune','{"prompt":{"it":"Muovi i comandi finché la tua figura è uguale al bersaglio.","en":"Move the controls until your figure matches the target."},"layout":"grid","items":6,"props":[{"prop":"grid-template-columns","choices":["1fr","1fr 1fr","1fr 1fr 1fr","2fr 1fr"],"target":"1fr 1fr 1fr"},{"prop":"gap","unit":"px","min":0,"max":24,"step":4,"target":16}],"base":[],"itemBase":[],"why":{"it":"`fr` divide lo spazio libero in parti uguali.","en":"`fr` splits the free space into equal parts."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),2,'tune','{"prompt":{"it":"Una colonna larga e una stretta: trova la griglia.","en":"One wide column and a narrow one: find the grid."},"layout":"grid","items":4,"props":[{"prop":"grid-template-columns","choices":["1fr 1fr","1fr 2fr","2fr 1fr","1fr 1fr 1fr"],"target":"2fr 1fr"},{"prop":"gap","unit":"px","min":0,"max":24,"step":4,"target":8}],"base":[],"itemBase":[],"why":{"it":"`2fr 1fr` dà alla prima colonna il doppio dello spazio.","en":"`2fr 1fr` gives the first column twice the space."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),3,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":".lista {\\n  display: ___;\\n  grid-template-columns: ___(3, 1fr);\\n  ___: 12px;\\n}","gaps":["grid","repeat","gap"],"extra":["flex","columns","margin"],"why":{"it":"`repeat(3, 1fr)` è il modo breve per scrivere `1fr 1fr 1fr`.","en":"`repeat(3, 1fr)` is the short way of writing `1fr 1fr 1fr`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),1,'order','{"prompt":{"it":"Scrivi la media query mobile first.","en":"Write the mobile-first media query."},"lines":[".lista { display: block; }","@media (min-width: 700px) {","  .lista { display: flex; }","}"],"why":{"it":"Prima lo stile per il telefono, poi le aggiunte per gli schermi più larghi.","en":"First the phone style, then the additions for wider screens."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Mobile first parte dallo schermo piccolo","en":"Mobile first starts from the small screen"},true],[{"it":"`min-width: 700px` vale sotto i 700px","en":"`min-width: 700px` applies below 700px"},false],[{"it":"`vw` è una percentuale della larghezza dello schermo","en":"`vw` is a percentage of the screen width"},true],[{"it":"`clamp()` limita un valore tra minimo e massimo","en":"`clamp()` keeps a value between a minimum and a maximum"},true],[{"it":"Senza meta viewport il telefono rimpicciolisce la pagina","en":"Without the viewport meta the phone shrinks the page"},true],[{"it":"`max-width: 100%` ingrandisce le immagini oltre il contenitore","en":"`max-width: 100%` enlarges images beyond the container"},false]],"why":{"it":"`min-width` si attiva da quella larghezza in su.","en":"`min-width` applies from that width upwards."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".card { width: 100%; }","@media (max-width: 700px {","  .card { width: 50%; }","}"],"bug":1,"fix":"@media (max-width: 700px) {","why":{"it":"Manca la parentesi che chiude la condizione: tutto il blocco verrebbe ignorato.","en":"The bracket closing the condition is missing: the whole block would be ignored."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":":root {\\n  ___brand: #FF5B2E;\\n}\\n.card {\\n  color: ___(--brand);\\n  width: ___(100% - 32px);\\n}","gaps":["--","var","calc"],"extra":["$","@","val"],"why":{"it":"Le variabili CSS iniziano con `--` e si leggono con `var()`.","en":"CSS variables start with `--` and are read with `var()`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[":root { --spazio: 16px; }",".card {","  padding: --spazio;","}"],"bug":2,"fix":"  padding: var(--spazio);","why":{"it":"Per leggere una variabile serve sempre `var()`.","en":"Reading a variable always takes `var()`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),3,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["var(--x)",{"it":"Legge una variabile","en":"Reads a variable"}],["calc()",{"it":"Fa un calcolo","en":"Does a calculation"}],["min()",{"it":"Sceglie il valore minore","en":"Picks the smaller value"}],["clamp()",{"it":"Limita tra due estremi","en":"Limits between two ends"}],[":root",{"it":"Il posto delle variabili globali","en":"The home of global variables"}]],"why":{"it":"Funzioni e variabili rendono il CSS facile da cambiare.","en":"Functions and variables make CSS easy to change."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),1,'tune','{"prompt":{"it":"Ruota e ingrandisci la scatola come il bersaglio.","en":"Rotate and enlarge the box like the target."},"layout":"box","items":1,"props":[{"prop":"rotate","unit":"deg","min":0,"max":90,"step":15,"target":45},{"prop":"scale","unit":"","min":0.5,"max":1.5,"step":0.25,"target":1.25,"start":0.5}],"base":{"display":"grid","place-items":"center"},"itemBase":{"width":"70px","height":"70px","background-color":"#FFC53D","border-radius":"14px"},"why":{"it":"`rotate` e `scale` cambiano l’aspetto senza spostare gli altri elementi.","en":"`rotate` and `scale` change the look without moving other elements."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),2,'order','{"prompt":{"it":"Componi l’animazione.","en":"Put the animation together."},"lines":["@keyframes pulsa {","  from { opacity: 1; }","  to { opacity: .4; }","}",".luce { animation: pulsa 1s infinite; }"],"why":{"it":"Prima si definiscono i `@keyframes`, poi li si usa con `animation`.","en":"First you define the `@keyframes`, then you use them with `animation`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),3,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":".card {\\n  ___: transform .2s;\\n}\\n.card:___ {\\n  transform: ___(1.05);\\n}","gaps":["transition","hover","scale"],"extra":["animation","active","zoom"],"why":{"it":"`transition` si scrive sullo stato di partenza, così vale andando e tornando.","en":"`transition` goes on the starting state, so it works both ways."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___: #FF5B2E;\\n.titolo {\\n  color: ___;\\n}","gaps":["$brand","$brand"],"extra":["--brand","@brand"],"why":{"it":"In SCSS una variabile inizia con `$`.","en":"In SCSS a variable starts with `$`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Il browser legge direttamente lo SCSS","en":"The browser reads SCSS directly"},false],[{"it":"Lo SCSS viene compilato in CSS","en":"SCSS is compiled into CSS"},true],[{"it":"Ogni file CSS valido è anche SCSS valido","en":"Every valid CSS file is also valid SCSS"},true],[{"it":"Le variabili `$` esistono ancora nel CSS finale","en":"`$` variables still exist in the final CSS"},false],[{"it":"I file parziali iniziano con `_`","en":"Partial files start with `_`"},true]],"why":{"it":"Lo SCSS esiste solo prima della compilazione: al browser arriva CSS puro.","en":"SCSS exists only before compiling: the browser gets plain CSS."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["$bordo: 2px;",".card {","  border: bordo solid red;","}"],"bug":2,"fix":"  border: $bordo solid red;","why":{"it":"Il nome della variabile si scrive sempre con il `$`.","en":"The name of a variable is always written with `$`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"a {\\n  color: navy;\\n  ___:hover { color: red; }\\n  ___-attivo { color: green; }\\n}","gaps":["&","&"],"extra":["#",".","*"],"why":{"it":"`&` è il selettore genitore: `&:hover` diventa `a:hover`.","en":"`&` is the parent selector: `&:hover` becomes `a:hover`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),2,'match','{"prompt":{"it":"Abbina lo SCSS al CSS che produce.","en":"Match the SCSS with the CSS it produces."},"pairs":[["nav { a { … } }","nav a"],["a { &:hover { … } }","a:hover"],[".btn { &-big { … } }",".btn-big"],[".card { .titolo & { … } }",".titolo .card"]],"why":{"it":"La posizione di `&` decide dove finisce il genitore.","en":"The position of `&` decides where the parent ends up."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),3,'bug','{"prompt":{"it":"Una di queste righe non produce `.menu:hover`: trovala.","en":"One of these lines does not produce `.menu:hover`: find it."},"lines":[".menu {","  color: navy;","  :hover { color: red; }","}"],"bug":2,"fix":"  &:hover { color: red; }","why":{"it":"Senza `&` c’è uno spazio: il risultato è `.menu :hover`, tutta un’altra cosa.","en":"Without `&` there is a space: you get `.menu :hover`, something else entirely."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),1,'order','{"prompt":{"it":"Definisci il mixin e poi usalo.","en":"Define the mixin, then use it."},"lines":["@mixin ombra($colore) {","  box-shadow: 0 2px 8px $colore;","}",".card {","  @include ombra(gray);","}"],"why":{"it":"Prima `@mixin` lo definisce, poi `@include` lo inserisce dove serve.","en":"First `@mixin` defines it, then `@include` puts it where needed."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___ tondo($r: 8px) {\\n  border-radius: $r;\\n}\\n.foto {\\n  ___ tondo(50%);\\n}\\n.grande {\\n  ___ .foto;\\n}","gaps":["@mixin","@include","@extend"],"extra":["@use","@function"],"why":{"it":"`@mixin` e `@include` copiano regole, `@extend` condivide un selettore.","en":"`@mixin` and `@include` copy rules, `@extend` shares a selector."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),3,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["@mixin",{"it":"Definisce un blocco riutilizzabile","en":"Defines a reusable block"}],["@include",{"it":"Usa un mixin","en":"Uses a mixin"}],["@extend",{"it":"Eredita da un altro selettore","en":"Inherits from another selector"}],["%segnaposto",{"it":"Selettore che non finisce nel CSS","en":"Selector that never reaches the CSS"}]],"why":{"it":"Un mixin può avere parametri, `@extend` no.","en":"A mixin can have parameters, `@extend` cannot."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___ \\"colori\\";\\n.card {\\n  color: colori___$brand;\\n}","gaps":["@use","."],"extra":["@import","::","->"],"why":{"it":"`@use` carica un modulo; i suoi nomi si leggono con `modulo.nome`.","en":"`@use` loads a module; its names are read with `module.name`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),2,'order','{"prompt":{"it":"Scrivi il ciclo sulla mappa.","en":"Write the loop over the map."},"lines":["$temi: (ok: green, ko: red);","@each $nome, $tinta in $temi {","  .avviso-#{$nome} {","    color: $tinta;","  }","}"],"why":{"it":"`@each` scorre la mappa, `#{…}` mette il valore nel nome del selettore.","en":"`@each` walks the map, `#{…}` puts the value in the selector name."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),3,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["@use",{"it":"Carica un modulo","en":"Loads a module"}],["@each",{"it":"Scorre una lista o una mappa","en":"Walks a list or a map"}],["@if",{"it":"Applica una condizione","en":"Applies a condition"}],["#{$x}",{"it":"Inserisce un valore nel testo","en":"Puts a value into text"}],["map.get()",{"it":"Legge una voce della mappa","en":"Reads an entry of a map"}]],"why":{"it":"Con moduli e cicli lo stile si genera da pochi dati.","en":"With modules and loops, style is generated from little data."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'indented'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".titolo","  color: red;","  font-size: 2rem"],"bug":1,"fix":"  color: red","why":{"it":"Nella sintassi indentata non ci sono né graffe né punti e virgola.","en":"The indented syntax has no braces and no semicolons."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'indented'),2,'order','{"prompt":{"it":"Rimetti in ordine il codice Sass.","en":"Put the Sass code back in order."},"lines":["$brand: orange",".card","  color: $brand","  .titolo","    font-size: 2rem"],"why":{"it":"Il rientro dice che cosa sta dentro che cosa.","en":"Indentation says what goes inside what."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'indented'),3,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"In Sass contano i rientri","en":"In Sass indentation matters"},true],[{"it":"I file Sass finiscono in `.sass`","en":"Sass files end in `.sass`"},true],[{"it":"Sass usa le parentesi graffe","en":"Sass uses curly braces"},false],[{"it":"Un rientro sbagliato cambia il significato","en":"A wrong indent changes the meaning"},true],[{"it":"Ogni riga finisce con `;`","en":"Every line ends with `;`"},false]],"why":{"it":"Meno simboli, ma il rientro diventa parte del codice.","en":"Fewer symbols, but indentation becomes part of the code."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'mixins'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___tondo\\n  border-radius: 50%\\n\\n.avatar\\n  ___tondo","gaps":["=","+"],"extra":["@","&","$"],"why":{"it":"`=` definisce un mixin, `+` lo usa.","en":"`=` defines a mixin, `+` uses it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'mixins'),2,'match','{"prompt":{"it":"Abbina la scrittura Sass a quella SCSS.","en":"Match the Sass form with the SCSS form."},"pairs":[["=tondo","@mixin tondo"],["+tondo","@include tondo"],["=box($r)","@mixin box($r)"],["+box(4px)","@include box(4px)"]],"why":{"it":"Stessa logica: cambiano solo i simboli.","en":"Same logic: only the symbols change."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'mixins'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["=ombra","  box-shadow: 0 2px 8px gray",".card","  =ombra"],"bug":3,"fix":"  +ombra","why":{"it":"Dentro una regola il mixin si usa con `+`: `=` serve a definirlo.","en":"Inside a rule a mixin is used with `+`: `=` is for defining it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'choose'),1,'match','{"prompt":{"it":"Di quale sintassi è la caratteristica?","en":"Which syntax does each feature belong to?"},"pairs":[["{ }  ;","SCSS"],[{"it":"Rientri","en":"Indentation"},"Sass"],[".css",{"it":"Lo diventano entrambe","en":"Both become this"}]],"why":{"it":"Stesso motore, due modi di scrivere.","en":"Same engine, two ways of writing."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'choose'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"SCSS e Sass hanno le stesse funzioni","en":"SCSS and Sass have the same features"},true],[{"it":"Un file CSS valido è valido anche in `.sass`","en":"A valid CSS file is also valid in `.sass`"},false],[{"it":"Lo SCSS è la scelta più diffusa","en":"SCSS is the most widespread choice"},true],[{"it":"Il browser preferisce Sass","en":"The browser prefers Sass"},false],[{"it":"Si possono usare entrambi nello stesso progetto","en":"You can use both in the same project"},true]],"why":{"it":"Per il browser non cambia nulla: alla fine arriva sempre CSS.","en":"Nothing changes for the browser: in the end it always gets CSS."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'choose'),3,'order','{"prompt":{"it":"Rimetti in ordine la strada del tuo stile.","en":"Put the journey of your style in order."},"lines":["main.scss",{"it":"compilatore Sass","en":"Sass compiler"},"main.css","<link rel=\\"stylesheet\\">",{"it":"browser","en":"browser"}],"why":{"it":"Si scrive lo SCSS, si compila, e la pagina collega il CSS.","en":"You write SCSS, compile it, and the page links the CSS."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'entities'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["&lt;","<"],["&gt;",">"],["&amp;","&"],["&copy;","©"],["&euro;","€"]],"why":{"it":"Ogni entità è un modo sicuro di scrivere quel simbolo.","en":"Each entity is a safe way of writing that symbol."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'entities'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<p>Il prezzo è 5 &euro;</p>","<!-- Nota per il team --","<p>Fine</p>"],"bug":1,"fix":"<!-- Nota per il team -->","why":{"it":"Un commento si chiude con `-->`: senza, nasconde tutto quello che segue.","en":"A comment closes with `-->`: without it, it hides everything after it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'page-project'),1,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":["<body>","  <h1>Il mio sito</h1>","  <p>Benvenuto!</p>","  <a href=\\"info.html\\">Info</a>","</body>"],"why":{"it":"Dall’alto in basso, come la leggerà il visitatore.","en":"From top to bottom, as the visitor will read it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-base' AND slug = 'page-project'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`<a>` serve per i link","en":"`<a>` is for links"},true],[{"it":"`<img>` ha un tag di chiusura","en":"`<img>` has a closing tag"},false],[{"it":"`<li>` sta dentro `<ul>`","en":"`<li>` goes inside `<ul>`"},true],[{"it":"`<p>` è un titolo","en":"`<p>` is a heading"},false]],"why":{"it":"Sai già riconoscere tutti i pezzi di una pagina.","en":"You can already recognise every piece of a page."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'attributes'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["id",{"it":"Nome unico","en":"Unique name"}],["class",{"it":"Gruppo di elementi","en":"Group of elements"}],["title",{"it":"Suggerimento al passaggio","en":"Tooltip on hover"}],["hidden",{"it":"Nasconde l’elemento","en":"Hides the element"}],["lang",{"it":"Lingua del contenuto","en":"Language of the content"}]],"why":{"it":"Gli attributi globali funzionano quasi ovunque.","en":"Global attributes work almost everywhere."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'attributes'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<p class=\\"nota\\" class=\\"grande\\">Ciao</p>","<p class=\\"nota grande\\">Mondo</p>"],"bug":0,"fix":"<p class=\\"nota grande\\">Ciao</p>","why":{"it":"Un attributo si scrive una volta sola: le classi si mettono insieme.","en":"An attribute is written once only: classes go together."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'anchors'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["#fine",{"it":"Un punto della pagina","en":"A spot in the page"}],["pagina.html",{"it":"Un file vicino","en":"A nearby file"}],["../pagina.html",{"it":"Un file una cartella sopra","en":"A file one folder up"}],["https://…",{"it":"Un altro sito","en":"Another site"}],["mailto:",{"it":"Una email","en":"An email"}]],"why":{"it":"Il prefisso dice al browser dove andare.","en":"The prefix tells the browser where to go."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'anchors'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"<a href=\\"___contatti\\">Contatti</a>\\n<section ___=\\"contatti\\">…</section>","gaps":["#","id"],"extra":[".","class","name"],"why":{"it":"Il cancelletto nel link, l’`id` nella destinazione.","en":"The hash in the link, the `id` at the destination."}}');
