INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-base' AND slug = 'files-sessions'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<?php","echo \\"Benvenuto\\";","session_start();"],"bug":2,"fix":"session_start(); // prima di echo","why":{"it":"Dopo un `echo` è troppo tardi: `session_start` va chiamato prima di ogni output.","en":"After an `echo` it is too late: `session_start` must come before any output."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'classes'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"class Mago ___ Eroe {\\n    public function lancia(): void {\\n        ___->magia--;\\n    }\\n}\\n$m = ___ Mago(\\"Ada\\");\\n$m___lancia();","gaps":["extends","$this","new","->"],"extra":["implements","self","."],"why":{"it":"Ereditarietà, oggetto corrente, creazione e chiamata.","en":"Inheritance, current object, creation and call."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'classes'),2,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["public",{"it":"Tutti","en":"Everyone"}],["protected",{"it":"Classe e sottoclassi","en":"Class and subclasses"}],["private",{"it":"Solo la classe","en":"Only the class"}],["static",{"it":"Della classe, non dell’oggetto","en":"Of the class, not the object"}],["abstract",{"it":"Solo da estendere","en":"Only to be extended"}]],"why":{"it":"Chi può toccare che cosa.","en":"Who can touch what."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'pdo'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["$id = $_GET[\\"id\\"];","$st = $pdo->query(\\"SELECT * FROM utenti WHERE id = $id\\");","$riga = $st->fetch();"],"bug":1,"fix":"$st = $pdo->prepare(\\"SELECT * FROM utenti WHERE id = ?\\");","why":{"it":"Una variabile dentro la query apre alla SQL injection: serve `prepare`.","en":"A variable inside the query opens the door to SQL injection: use `prepare`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'pdo'),2,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":["$pdo = new PDO($dsn, $utente, $password);","$st = $pdo->prepare(\\"SELECT * FROM corsi WHERE id = ?\\");","$st->execute([$id]);","$corso = $st->fetch();"],"why":{"it":"Connetti, prepara, esegui, leggi.","en":"Connect, prepare, run, read."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'passwords'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"$h = ___($pw, PASSWORD_DEFAULT);\\nif (___($prova, $h)) {\\n    session_regenerate_id(true);\\n}\\n$t = bin2hex(___(32));","gaps":["password_hash","password_verify","random_bytes"],"extra":["md5","rand","strcmp"],"why":{"it":"Impronta, verifica e casualità sicura.","en":"Fingerprint, verification and safe randomness."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'passwords'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`md5` va bene per le password","en":"`md5` is fine for passwords"},false],[{"it":"Due utenti con la stessa password hanno impronte diverse","en":"Two users with the same password get different fingerprints"},true],[{"it":"Limitare i tentativi è utile","en":"Limiting attempts is useful"},true],[{"it":"`rand()` è sicuro per i token","en":"`rand()` is safe for tokens"},false]],"why":{"it":"Il sale casuale rende diversa ogni impronta.","en":"Random salt makes every fingerprint different."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'json-api'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["200",{"it":"Riuscito","en":"Success"}],["401",{"it":"Non autenticato","en":"Not signed in"}],["403",{"it":"Non permesso","en":"Forbidden"}],["404",{"it":"Non trovato","en":"Not found"}],["422",{"it":"Dati non validi","en":"Invalid data"}],["500",{"it":"Errore del server","en":"Server error"}]],"why":{"it":"Il codice dice a colpo d’occhio com’è andata.","en":"The code says at a glance how it went."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'json-api'),2,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":["header(\\"Content-Type: application/json\\");","$dati = json_decode(file_get_contents(\\"php://input\\"), true);","http_response_code(201);","echo json_encode([\\"ok\\" => true]);"],"why":{"it":"Intestazioni, lettura, stato, risposta.","en":"Headers, reading, status, response."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'errors'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___ {\\n    salva();\\n} ___ (Throwable $e) {\\n    error_log($e->___());\\n}","gaps":["try","catch","getMessage"],"extra":["do","except","message"],"why":{"it":"Prova, cattura, scrivi nel log.","en":"Try, catch, write to the log."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'errors'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["try {","    salva();","} catch (Throwable $e) {","    echo $e->getMessage();","}"],"bug":3,"fix":"    error_log($e->getMessage());","why":{"it":"Mostrare l’errore al visitatore rivela dettagli interni: va nel log.","en":"Showing the error to visitors reveals internal details: it goes to the log."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'project'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["composer.json",{"it":"Elenco delle librerie","en":"List of libraries"}],["vendor/",{"it":"Le librerie scaricate","en":"Downloaded libraries"}],["namespace",{"it":"Cognome delle classi","en":"Surname of classes"}],["use",{"it":"Importa una classe","en":"Imports a class"}],[".gitignore",{"it":"File esclusi da git","en":"Files kept out of git"}]],"why":{"it":"L’ordine oggi vale tempo domani.","en":"Order today is time saved tomorrow."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'project'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`vendor/` di solito sta fuori da git","en":"`vendor/` usually stays out of git"},true],[{"it":"Le password si scrivono nel codice pubblico","en":"Passwords go in public code"},false],[{"it":"L’iniezione delle dipendenze aiuta i test","en":"Dependency injection helps testing"},true],[{"it":"Un namespace rende il codice più lento","en":"A namespace makes code slower"},false]],"why":{"it":"Segreti fuori dal codice, dipendenze dentro al costruttore.","en":"Secrets out of the code, dependencies into the constructor."}}');
