-- Fucina — tables for phpMyAdmin (prefix fc_). Generated by tools/build-sql.php. Alternative to install-db.php.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `fc_meta` (
  `k` VARCHAR(40) NOT NULL PRIMARY KEY,
  `v` VARCHAR(255) NOT NULL
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fc_users` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(80) NOT NULL,
  `email` VARCHAR(190) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL DEFAULT '',
  `google_sub` VARCHAR(64) NULL,
  `lang` CHAR(2) NOT NULL DEFAULT 'en',
  `status` ENUM('active','disabled') NOT NULL DEFAULT 'active',
  `role` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `xp` INT UNSIGNED NOT NULL DEFAULT 0,
  `points` INT UNSIGNED NOT NULL DEFAULT 0,
  `streak` INT UNSIGNED NOT NULL DEFAULT 0,
  `best_streak` INT UNSIGNED NOT NULL DEFAULT 0,
  `win_streak` INT UNSIGNED NOT NULL DEFAULT 0,
  `best_win_streak` INT UNSIGNED NOT NULL DEFAULT 0,
  `drill_streak` INT UNSIGNED NOT NULL DEFAULT 0,
  `best_drill_streak` INT UNSIGNED NOT NULL DEFAULT 0,
  `on_board` TINYINT(1) NOT NULL DEFAULT 1,
  `last_day` DATE NULL,
  `created_at` DATETIME NOT NULL,
  `last_login_at` DATETIME NULL,
  `last_seen_at` DATETIME NULL,
  UNIQUE KEY `uq_email` (`email`),
  UNIQUE KEY `uq_google` (`google_sub`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fc_auth_tokens` (
  `token_hash` CHAR(64) NOT NULL PRIMARY KEY,
  `user_id` INT UNSIGNED NOT NULL,
  `csrf_token` CHAR(48) NOT NULL,
  `user_agent` VARCHAR(255) NOT NULL DEFAULT '',
  `ip` VARCHAR(45) NOT NULL DEFAULT '',
  `created_at` DATETIME NOT NULL,
  `last_seen_at` DATETIME NOT NULL,
  `expires_at` DATETIME NOT NULL,
  KEY `ix_user` (`user_id`),
  CONSTRAINT `fk_fc_tok_user` FOREIGN KEY (`user_id`) REFERENCES `fc_users` (`id`) ON DELETE CASCADE
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fc_attempts` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
